import 'https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate@83c1e1f6305013713a2f1f5979f461cc1e80488d/artifact/bundle.js';
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource@4e1de2820a66bc685ddcfff91af638838c4e156c/dist/util/mvu_zod.js';

// ═══════════════════════════════════════════════════════════════
//  方舟：生存进化 V3.4 · MVU Zod Schema（八根状态源 · MVU 唯一事实源）
//  V3.4：新增 NPC系统（私聊历史/归档/玩家设置/通道设置）与 方舟_引擎（当层操作流水）；
//  恐龙系统补 自定义生物库/驯服会话/印痕度/颜色区；一切长期信息全部保存于 MVU
//  依赖：酒馆助手脚本环境 + MagVarUpdate + mvu_zod（由 MVU引擎 脚本先行加载）
//  V3.0：资源改动态 number record；删建筑块（设施归部落系统.营地设施）；
//  新增 NPC图鉴/繁殖中；已驯服条目补可选 成长进度/变异/繁殖冷却/颜色变异 字段
// ═══════════════════════════════════════════════════════════════

const text = (fallback = '') => z.coerce.string().catch(fallback).prefault(fallback);
const number = (fallback = 0) => z.coerce.number().catch(fallback).prefault(fallback);
const integer = (fallback = 0) => number(fallback).transform(v => Math.trunc(v));
const bool = (fallback = false) => z.preprocess(v => {
  if (typeof v === 'string') {
    const n = v.trim().toLowerCase();
    if (n === 'false' || n === '0' || n === '否' || n === '无') return false;
    if (n === 'true' || n === '1' || n === '是' || n === '有') return true;
  }
  if (v === 0) return false;
  if (v === 1) return true;
  return v;
}, z.boolean()).catch(fallback).prefault(fallback);
const stringList = () => z.array(z.coerce.string()).catch([]).prefault([]);
const looseRecord = () => z.record(z.string(), z.any()).catch({}).prefault({});
const looseObject = () => z.record(z.string(), z.any()).catch({}).prefault({});
const clamp = (lo, hi) => v => _.clamp(v, lo, hi);

export const Schema = z.object({
  // ── 根1：会话设置 ──────────────────────────────────────────
  方舟_会话设置: z.object({
    MVU数据版本: text('2.2-ark-core'),
    开局状态: text('等待角色创建'),
    地图: text('孤岛'),
    出生区域: text('南部海滩'),
    难度: text('标准'),
    难度标签: text('【难度：标准】'),
    旁白模式: text('无要求'),
    玩法偏好: stringList(),
    禁忌: stringList(),
    作弊选项: stringList(),
    死亡次数: integer(0),
    复活模式: text('标准'),   // V3.4.1：硬核(恐龙永久死亡)/标准/宽松(恐龙可复活)——开局创建器设定
    开局场景: text('标准海滩苏醒'), // V3.4.1：开局场景预设或自定义文本
  }).passthrough().prefault({}),

  // ── 根2：主角生存状态 ──────────────────────────────────────
  主角_生存状态: z.object({
    姓名: text('未命名生存者'),
    性别: text('不指定'),
    身份: text('现代人类'),
    外观: text('未记录'),
    等级: integer(1),
    经验: number(0),
    经验上限: number(40),
    属性点: integer(0),
    印痕点: integer(0),
    属性: z.object({
      生命加成: integer(0),
      耐力加成: integer(0),
      氧气加成: integer(0),
      食物加成: integer(0),
      水分加成: integer(0),
      负重加成: integer(0),
      移速加成: integer(0),
      近战加成: integer(0),
      抗性加成: integer(0),
    }).passthrough().prefault({}),
    生存指标: z.object({
      生命值: z.coerce.number().transform(clamp(0, 2000)).prefault(100),
      生命上限: z.coerce.number().transform(clamp(1, 2000)).prefault(100),
      耐力: z.coerce.number().transform(clamp(0, 2000)).prefault(100),
      耐力上限: z.coerce.number().transform(clamp(1, 2000)).prefault(100),
      氧气: z.coerce.number().transform(clamp(0, 4000)).prefault(100),
      氧气上限: z.coerce.number().transform(clamp(1, 4000)).prefault(200), // 对齐引擎 STATS['氧气'].base=200（defaultState 同值）
      食物: z.coerce.number().transform(clamp(0, 2000)).prefault(100),
      食物上限: z.coerce.number().transform(clamp(1, 2000)).prefault(100),
      水分: z.coerce.number().transform(clamp(0, 2000)).prefault(100),
      水分上限: z.coerce.number().transform(clamp(1, 2000)).prefault(100),
      体温: number(36.5),
      负重: number(0),
      负重上限: z.coerce.number().transform(clamp(1, 2000)).prefault(100),
    }).passthrough().prefault({}),
    状态效果: stringList(),
    装备: z.object({
      头部: text('无'),
      胸部: text('无'),
      腿部: text('无'),
      手持: text('无'),
      背包: text('无'),
    }).passthrough().prefault({}),
    重生点: text('无'),
    处于骑乘: text('无'),
    中毒: bool(false),
    濒死: bool(false),
  }).passthrough().prefault({}),

  // ── 根3：物品与印痕 ────────────────────────────────────────
  主角_物品与印痕: z.object({
    物品栏: z.record(z.string(), z.object({
      描述: text(''),
      数量: number(0),
      类别: text('材料'),
      耐久: text(''),
    })).transform(d => _.pickBy(d, ({ 数量 }) => 数量 > 0)).catch({}).prefault({}),
    资源: z.record(z.string(), number(0)).catch({}).prefault({}), // V3.0：动态资源键（数量归零即删）
    已解锁印痕: stringList(),
    可制作提示: text('无'),
  }).passthrough().prefault({}),

  // ── 根4：恐龙系统 ──────────────────────────────────────────
  恐龙系统: z.object({
    自定义生物库: looseRecord().optional(), // V3.4：玩家自定义生物（名称→定义），驯服/繁殖可用
    驯服会话: looseObject().optional(),     // V3.4：驯服进行中的会话态（随楼层回滚）
    已驯服: z.record(z.string(), z.object({
      名称: text(''),
      种族: text(''),
      性别: text('未知'),
      性格: text(''),
      等级: integer(1),
      生命值: number(100),
      生命上限: number(100),
      食物度: number(100),
      攻击力: text(''),
      特殊技能: stringList(),
      鞍具: text('无鞍'),
      是否在场: bool(true),
      状态: text('待命'),
      年龄阶段: text('成年'),
      忠诚度: z.coerce.number().transform(clamp(0, 100)).prefault(80),
      驯服方式: text('击晕驯服'),
      // V3.3 ARK 风格属性与升级（可选：旧档无这些字段时不强制注入）
      野生等级: integer(1).optional(),
      属性: z.object({
        生命: integer(0),
        耐力: integer(0),
        氧气: integer(0),
        食物: integer(0),
        负重: integer(0),
        近战: integer(0),
        速度: integer(0),
      }).passthrough().prefault({}).optional(),
      经验: number(0).optional(),
      经验上限: number(0).optional(),
      可分配点数: integer(0).optional(),
      负重上限: number(0).optional(),
      食物上限: number(0).optional(),
      移动速度: text('').optional(),
      眩晕上限: number(0).optional(),
      // V3.0 可选：成长/变异/繁殖字段（旧档无这些字段时不强制注入）
      成长进度: number(100).optional(),
      变异次数: z.any().optional(), // V3.4：数字（旧档）或 {父系: n, 母系: n}
      变异详情: stringList().optional(),
      繁殖冷却: number(0).optional(),
      颜色变异: text('').optional(),
      // V3.4 繁殖深化：印痕培养与六区颜色
      印痕度: number(0).optional(),
      印痕加成: text('').optional(),
      颜色区: looseRecord().optional(),
    })).catch({}).prefault({}),
    驯服中: z.object({
      状态: text('无'),
      种族: text('无'),
      等级: integer(1),
      驯服进度: z.coerce.number().transform(clamp(0, 100)).prefault(0),
      麻醉度: z.coerce.number().transform(clamp(0, 100)).prefault(0),
      食物槽: text('无'),
      偏好食物: text('未知'),
      驯服效率: text('普通'),
      预计鞍具需求: text('无'),
    }).passthrough().prefault({}),
    骑乘中: text('无'),
    繁殖中: looseObject(), // V3.4：{状态/父体/母体/种族/开始/孵化需求秒/温度需求/繁殖方式(蛋生|胎生)}
  }).passthrough().prefault({}),

  // ── 根5：部落系统 ──────────────────────────────────────────
  部落系统: z.object({
    部落名称: text('未组建'),
    部落等级: integer(0),
    营地设施: z.record(z.string(), integer(0)).catch({}).prefault({}), // V3.0：篝火/研钵/铁匠台…动态设施计数
    成员: z.record(z.string(), z.object({
      性别: text(''),
      国籍: text(''),
      // V3.4.2（H3）：年龄改文本（'26岁'/'未记录'——与创建器 H2 契约及引擎 initStateInto 同口径；
      // 旧档整数年龄会被 coerce 成字符串，不触发 record 级 catch 清空成员表）
      年龄: text('未记录'),
      身份: text(''),
      性格: text(''),
      时代: text(''),
      状态: text('健康'),
      好感度: z.coerce.number().transform(clamp(0, 100)).prefault(50),
      掌握技能: text(''),
      信任度: z.coerce.number().transform(clamp(0, 100)).prefault(50),
      情绪: text('平静'),
      喜好: text(''),
      厌恶: text(''),
      关系: text(''),
      外貌: text(''),
      记忆: z.array(text('')).catch([]).prefault([]),
      // V3.4.4：成员档案与 NPC图鉴 同构（修复 HUD NPC详情五区字段对部落成员无 MVU 变量对应）
      阵营: text('玩家部落'),
      态度: text('友善'),
      地点: text(''),
      备注: text(''),
      头衔: text(''),
      口癖: text(''),
      说话风格: text(''),
      惯用动作: text(''),
      武器: text(''),
      战斗力: text(''),
      初遇时间: text(''),
      初遇地点: text(''),
      互动次数: integer(0),
      最近互动: text(''),
      交易记录: z.array(text('')).catch([]).prefault([]),
    })).catch({}).prefault({}),
  }).passthrough().prefault({}),

  // ── 根6：世界领土势力 ──────────────────────────────────────
  世界_领土势力: z.object({
    当前时间: text('第1天 08:00'),
    时段: text('白天'),
    天气: text('晴朗'),
    当前地点: text('孤岛_南部海滩'),
    环境温度: text('24°C'),
    已探索区域: stringList(),
    NPC图鉴: z.record(z.string(), z.object({
      身份: text(''),
      阵营: text(''),
      态度: text('中立'),
      地点: text(''),
      备注: text(''),
      性格: text(''),
      好感度: z.coerce.number().transform(clamp(0, 100)).prefault(50),
      信任度: z.coerce.number().transform(clamp(0, 100)).prefault(50),
      情绪: text('平静'),
      喜好: text(''),
      厌恶: text(''),
      关系: text(''),
      外貌: text(''),
      记忆: z.array(text('')).catch([]).prefault([]),
      // V3.4.1 详细档案扩充：身份底细 / 谈吐特征 / 实力评估 / 相遇与互动轨迹
      性别: text(''),
      年龄: text(''),
      国籍: text(''),
      时代: text(''),
      头衔: text(''),
      口癖: text(''),
      说话风格: text(''),
      武器: text(''),
      战斗力: text(''),
      惯用动作: text(''),
      初遇时间: text(''),
      初遇地点: text(''),
      互动次数: integer(0),
      最近互动: text(''),
      交易记录: z.array(text('')).catch([]).prefault([]),
    })).catch({}).prefault({}), // V3.4.1：世界NPC完整档案（基础/关系/谈吐/实力/互动轨迹）
    生物图鉴: z.record(z.string(), z.object({
      名称: text(''),
      食性: text(''),
      性情: text(''),
      驯服建议: text(''),
      发现地点: text(''),
      图鉴等级: text('普通'),
    })).catch({}).prefault({}),
    Boss进度: z.object({
      育母蜘蛛: text('未挑战'),
      大金刚: text('未挑战'),
      喷火龙: text('未挑战'),
      监察者: text('未挑战'),
      狮身蝎尾兽: text('未挑战'),
    }).passthrough().prefault({}),
    神器收集: stringList(),
    威胁事件: text('无'),
    大事记: z.array(z.any()).catch([]).prefault([]), // V3.4.1：生存编年史（引擎独占：{t,day,kind,text}×40）
    隐秘事件: looseRecord(),
  }).passthrough().prefault({}),

  // ── 根7：NPC系统（V3.4 · 私聊与玩家自定义，全部长期保存于 MVU）──
  NPC系统: z.object({
    私聊历史: looseRecord(),   // { npcName: [{role,content,t}...] }（上限24条/NPC）
    私聊归档: looseRecord(),   // { npcName: [{t,s}...] }（上限10条/NPC）
    玩家设置: looseRecord(),   // { npcName: {len,style,persona,spoiler,honor,knowledge,initiative} }
    通道设置: looseObject(),   // {mode,model,maxTokens,npcLen,npcStyle,npcSpoiler,npcHonor}（不含 apiKey）
  }).passthrough().prefault({}),

  // ── 根8：方舟引擎（V3.4 · 当层操作流水与版本标识，引擎独占，AI 只读勿改）──
  方舟_引擎: z.object({
    引擎版本: text('3.4'),
    当层操作: z.array(z.any()).catch([]).prefault([]), // 本楼层生成后玩家的界面操作流水（跨楼层清零）
  }).passthrough().prefault({}),
});

registerMvuSchema(Schema);
console.log('[方舟V3.4] MVU Zod Schema 已注册（八根状态源·MVU唯一事实源）');

