  var PILL_ID  = 'ark-shell-pill';        // 入口悬浮球（挂宿主 document）
  var THEME_ID = 'ark-shell-theme';       // 原生界面主题化样式（宿主 head；进入启用/退出禁用）
  var PILLCSS_ID = 'ark-shell-pillcss';   // 悬浮球样式（注入宿主 head）
  var BACKDROP_ID = 'ark-shell-backdrop'; // 背景增暗+青调层（body 首子；z 高于 bg1 低于 sheld）
