    inputSlot: null, inputBar: null, inputTa: null, inputSend: null,  // V9：战术控制台
    railEl: null,                    // V9：桌面左缘导航 rail
    veilEl: null, theme: 'island',    // V8：veil 遮罩 / 当前主题（五套配色）
    viewsEl: null, overlayHost: null, toastHost: null,
