    try { return H().document || document; } catch (e) { return document; }
  }

  /* ── 本机偏好存取（宿主 localStorage，键带项目前缀）──────────── */
  function lsGet(key, dft) {
    try {
      var v = H().localStorage.getItem(LS_PREFIX + key);
      return v === null || v === undefined ? dft : v;
    } catch (e) { return dft; }
  }
  function lsSet(key, val) {
    try { H().localStorage.setItem(LS_PREFIX + key, String(val)); } catch (e) {}
  }

  /* ── 通用小工具 ──────────────────────────────────────────────── */
  function debounce(fn, wait) {
    var t = null;
    var d = function () {
      var args = arguments, self = this;
      if (t) clearTimeout(t);
      t = setTimeout(function () { t = null; fn.apply(self, args); }, wait);
    };
    d.cancel = function () { if (t) { clearTimeout(t); t = null; } };
    return d;
  }
  function rafThrottle(fn) {  // rAF 节流（保留给模块 08 字号同步等场景）
    var queued = false, lastArgs = null;
    return function () {
      lastArgs = arguments;
      if (queued) return;
      queued = true;
      requestAnimationFrame(function () {
        queued = false;
        try { fn.apply(null, lastArgs); } catch (e) { logErr(e); }
      });
    };
  }
  function clamp(v, lo, hi) { var n = Number(v); if (!isFinite(n)) n = lo; return Math.min(hi, Math.max(lo, n)); }
  function trimS(s) { return String(s == null ? '' : s).replace(/^\s+|\s+$/g, ''); }
  function pct(cur, max) {
    var c = Number(cur) || 0, m = Number(max) || 0;
    if (m <= 0) return 0;
    return clamp(Math.round((c / m) * 100), 0, 100);
  }
  function el(tag, cls, text) {  // 宿主文档建元素；text 一律 textContent（XSS 纪律）
    var d = HD();
    var e = d.createElement(tag);
    if (cls) e.className = cls;
    if (text != null && text !== '') e.textContent = String(text);
    return e;
  }
