  }

  /* 等待 ARK_CORE（引擎脚本与壳脚本的加载顺序不保证）：
   * 250ms 轮询，至多 90s；超时 → 只读模式（仍挂壳 + 警示条 + 楼层兜底解析）。 */
  function waitCore(onDone) {
    if (SH.coreWaited && SH.coreReady) { onDone(); return; }
    if (SH.coreWaited && !SH.coreReady) { SH.coreWaited = false; }
    var tried = 0, limit = 360;
    var timer = setInterval(function () {
      tried++;
      var ok = false;
      try { ok = !!(H().ARK_CORE && H().ARK_CORE.ready); } catch (e) {}
      if (ok) {
        clearInterval(timer);
        SH.coreReady = true; SH.coreWaited = true;
        onDone(); return;
      }
      if (tried >= limit) {
        clearInterval(timer);
        SH.coreReady = false; SH.coreWaited = true;
        console.warn('[ark-shell] ARK_CORE 90s 未就绪 → 只读模式（楼层兜底解析）');
