     * 兜底 = 停止按钮内联 display（css('display') 读级联值，同样免疫）。
     * 连续 2 次（≥5s）判定不在生成才解锁。 */
    genPoll = setInterval(function () {
      try {
        if (!SH.genActive) return;
        var busy = false;
        try {
          var hb = H().document.body;
          busy = !!(hb && hb.dataset && hb.dataset.generating !== undefined);
        } catch (e1) {}
        if (!busy) {
          var jq = H().jQuery;
          if (jq) { try { busy = jq('#mes_stop').css('display') !== 'none'; } catch (e2) {} }
        }
        if (!busy) {
          genMiss++;
          if (genMiss >= 2) {
            console.warn('[ark-shell] 生成对账：宿主已退出生成态，自愈解锁');
            try { onGenEnd(); } catch (e3) {}
          }
        } else genMiss = 0;
      } catch (e) {}
    }, 2500);
    genWatchdog = setTimeout(function () {
      genWatchdog = null;
      if (SH.genActive) {
        console.warn('[ark-shell] 生成看门狗：40s 无消息，自愈解锁徽标');
        SH.genActive = false;
        try { finalizeGen(); } catch (e) { logErr(e); }
        try { markDirty(); } catch (e) {}
      }
    }, 40000);
  }
  function disarmGenWatchdog() {
    if (genWatchdog) { clearTimeout(genWatchdog); genWatchdog = null; }
    if (genPoll) { clearInterval(genPoll); genPoll = 0; }
  }

  function markDirty() {
    SH.dirty = true;
    scheduleRerender();
  }

  /* ── 自动进入评估：仅当「楼数从 0 变 ≥1」（游戏开始）时自动一次 ── */
  function evaluateAutoEnter() {
    if (SH.mounted || SH.userExited || SH.autoEntered) return;
    if (lsGet('autoEnter', '1') !== '1') return;
    var last = -1;
    try { last = getLastMessageId(); } catch (e) {}
    if (last >= 1) {
      SH.autoEntered = true;
      try { enterShell(); } catch (e) { logErr(e); }
    }
  }

  /* ── CHAT_CHANGED：chatId 守卫 + 重载状态 + 非方舟上下文拆除 ──── */
  function onChatChanged() {
    if (!isArkContext()) { teardown(); return; }
    if (!SH.booted) {
      try { boot(); } catch (e) { logErr(e); }
      return;
    }
    if (!SH.pillEl) {
      if (ensureActive()) return;
    }
    var id = currentChatId();
    if (id && SH.chatId && id !== SH.chatId) {
      SH.autoEntered = false; SH.userExited = false;
      SH.chatId = id;
      SH.epoch++;
      SH.floors = []; SH.dirty = true;
      SH.schemaBridged = false;
      SH.busy = false; SH.genActive = false;
      if (SH.mounted) {
        try { switchView('story'); } catch (e) {}
        try { closeAllOverlays(); } catch (e) {}
        markDirty();
        try { refreshStatus(); } catch (e) {}
      }
      evaluateAutoEnter();
      return;
    }
    if (!SH.chatId) SH.chatId = id;
    markDirty();
    evaluateAutoEnter();
  }

  /* ── 事件接线（全部经 eventOn；一次接线跨拆除/复活存活）───────── */
  function wireEvents() {
    if (SH.wired) return;
    SH.wired = true;
    var TE = (typeof tavern_events !== 'undefined') ? tavern_events : {};

    // 楼层事件 → 失效重绘（楼层 DOM 本体=原生渲染，壳只刷新状态条/行动条/面板）
    var onMsg = function () {
      if (!SH.mounted) { evaluateAutoEnter(); return; }
      markDirty();
      evaluateAutoEnter();
    };
    if (TE.MESSAGE_RECEIVED)    eventOn(TE.MESSAGE_RECEIVED, onMsg);
    if (TE.MESSAGE_UPDATED)     eventOn(TE.MESSAGE_UPDATED, onMsg);
    if (TE.MESSAGE_EDITED)      eventOn(TE.MESSAGE_EDITED, onMsg);
    if (TE.MESSAGE_DELETED)     eventOn(TE.MESSAGE_DELETED, onMsg);
    if (TE.MESSAGE_SWIPED)      eventOn(TE.MESSAGE_SWIPED, onMsg);
    if (TE.MESSAGE_RECEIVED) eventOn(TE.MESSAGE_RECEIVED, function () {
      scheduleMvuBridge();
    });

    // 生成生命周期：started→锁定/生成中徽标；ended/stopped→解锁。
    // 流式渲染由酒馆原生完成（楼层 DOM 实时打字），壳零参与。
    // 注意：Generate() 连 dry-run 也会发 GENERATION_STARTED（且无 ENDED），
    //       必须以第三参 dryRun 过滤，否则悬浮球会卡在「生成中」。
    if (TE.GENERATION_STARTED) eventOn(TE.GENERATION_STARTED, function (type, opts, dryRun) {
      if (dryRun) return;
      if (type === 'quiet') return;                    /* V7：静默生成不点亮「生成中」 */
      if (opts && opts.automatic_trigger) return;      /* V7：自动触发（聊天标题等）不锁输入栏 */
      SH.genActive = true;
      updatePill('gen');
      armGenWatchdog();
      try { refreshStatus(); } catch (e) {}
      try { syncInputState(); } catch (e) {}   // V9：控制台发送钮→停止态即刻切换
    });
    var onGenEnd = function () {
      SH.genActive = false;
      disarmGenWatchdog();
      try { finalizeGen(); } catch (e) { logErr(e); }
      markDirty();
      evaluateAutoEnter();
    };
    if (TE.GENERATION_ENDED)   eventOn(TE.GENERATION_ENDED, onGenEnd);
    if (TE.GENERATION_STOPPED) eventOn(TE.GENERATION_STOPPED, onGenEnd);

    // 兜底：真实 AI 楼层到达即视为生成结束（ENDED 缺席时对账）
    var onMsgRcv = function () {
      if (!SH.mounted) { evaluateAutoEnter(); return; }
      if (SH.genActive) { onGenEnd(); return; }
      markDirty();
      evaluateAutoEnter();
    };
    if (TE.MESSAGE_RECEIVED) eventOn(TE.MESSAGE_RECEIVED, onMsgRcv);

    if (TE.CHAT_CHANGED) eventOn(TE.CHAT_CHANGED, function () { onChatChanged(); });

    // 设置更新 → 重绘（正则渲染全部原生完成，无需任何缓存失效逻辑）
    if (TE.SETTINGS_UPDATED) eventOn(TE.SETTINGS_UPDATED, function () {
      markDirty();
    });

    // 页面卸载 → 恢复原生 + 清理（bfcache 友好：pagehide 也挂）
    var hw = H();
    try {
      hw.addEventListener('beforeunload', pageCleanup);
      hw.addEventListener('pagehide', pageCleanup);
    } catch (e) {}

    /* V4.2 关键：iframe 自身 pagehide 兜底自清理。
     * 场景：切到其他角色卡/关闭本脚本/重载 TH 时，酒馆助手会直接移除本脚本
     * iframe——若 iframe 先死而 CHAT_CHANGED 未能送达，宿主中的主题样式、
     * 槽位与残留节点将成为永久残留。iframe 被移除时浏览器会向其自身 window
     * 派发 pagehide —— 在此处恢复原生并清除残留（与 TH 官方 cleanup 同机制）。 */
    try {
      window.addEventListener('pagehide', pageCleanup);
      window.addEventListener('beforeunload', pageCleanup);
    } catch (e) {}
  }

  function pageCleanup() {
    try {
      restoreNative();                       // 先恢复原生显示（对称退出）
      removeResidue();
    } catch (e) {}
  }

  /* ── 完整退场：恢复原生 → 移除壳/槽位/主题样式/监听 ──────────── */
  function teardown() {
    try { exitShell(false); } catch (e) {}   // 先恢复原生再收壳（对称）
    removeResidue();
    SH.booted = false; SH.mounted = false;
    SH.floors = []; SH.dirty = false;
    SH.autoEntered = false; SH.userExited = false;
    SH.coreSubscribed = false;
    SH.coreReady = false; SH.coreWaited = false;   // 允许复活时重新等待引擎
    SH.tbSlot = null; SH.abSlot = null; SH.actionBar = null;
    SH.inputSlot = null; SH.inputBar = null; SH.inputTa = null; SH.inputSend = null;
    SH.railEl = null;
    console.info('[ark-shell] 非方舟上下文/退场清理完成');
  }

  /* ── 活性保障：上下文就绪则挂pill等，未就绪则轮询等待 ────────── */
  function ensureActive() {
    if (!isArkContext()) return false;
    if (!SH.pillEl) {
      if (!SH.chatId) SH.chatId = currentChatId();
      try { mountPill(); } catch (e) { logErr(e); }
      try { updatePill(''); } catch (e) {}
      waitCore(function () {
        try { if (SH.coreReady) subscribeEngine(); } catch (e) { logErr(e); }
        try { mvuSchemaBridge(); } catch (e) {}
        markDirty();
        evaluateAutoEnter();
        if (!SH.coreReady && SH.mounted) {
          toast('游戏引擎未就绪，前端处于只读模式', 'warning');
        }
      });
    }
    return true;
  }

  /* ── 启动入口（99-footer 调用；任何失败 → 恢复原生 + 报错）──── */
  function boot() {
    if (SH.booted) return;
    SH.booted = true;

    removeResidue();                          // 幂等：清掉上一轮残留（含 V4 遗留）
    wireEvents();                             // 无条件接线（处理器内部自守卫）

    if (ensureActive()) {
      console.info('[ark-shell] V' + SHELL_VERSION + ' 启动（巨龙守望 · 战术控制台 · 原生渲染 + 卡内外过滤）');
    } else {
      console.info('[ark-shell] 上下文未就绪，进入等待轮询（≤60s×2s）');
      var tries = 0;
      var poll = setInterval(function () {
        tries++;
        if (ensureActive()) { clearInterval(poll); console.info('[ark-shell] 上下文就绪，启动完成'); return; }
        if (tries >= 30 || !SH.booted) { clearInterval(poll); }
      }, 2000);
    }
  }


  /* ═══════════════════════════════════════════════════════════════════
   * 模块 02 · 挂载：悬浮球 / 原生主题化（V8：#chat 原生保留 + CSS
   *              重新皮肤化，正则/流式/滑动管线 100% 原生）/ 顶栏槽位
   *              插入 #sheld 流 / 进入退出对称 / Esc 浮层栈+退面板 / Toast
   * 纪律：壳首帧渲染完成后才启用主题样式；退出先禁用主题再收壳。
   * ═══════════════════════════════════════════════════════════════════ */

  /* ── 入口悬浮球（宿主 document，fixed 右缘中部，44px 触摸目标）── */
  function mountPill() {
    var d = HD();
    try { ensurePillStyle(); } catch (e) { logErr(e); }
    if (d.getElementById(PILL_ID)) return;
    var b = el('button');
    b.id = PILL_ID;
    b.type = 'button';
    b.setAttribute('aria-label', '打开方舟终端（全屏前端）');
    var ico = el('span', 'pill-ico', '🦖');
    var label = el('span', 'pill-label', '方舟终端');
    var badge = el('span', 'pill-badge');
    b.appendChild(ico); b.appendChild(label); b.appendChild(badge);
    b.addEventListener('click', function (ev) {
      ev.preventDefault(); ev.stopPropagation();
      try { enterShell(); } catch (e) { logErr(e); toast('进入终端失败：' + (e && e.message), 'error'); }
    });
    d.body.appendChild(b);
    SH.pillEl = b;
  }

  /* 悬浮球状态徽标：''=未开局 / 'live'=进行中 / 'gen'=生成中 */
  function updatePill(state) {
    if (!SH.pillEl || SH.lastPillState === state) return;
    SH.lastPillState = state;
    var badge = SH.pillEl.querySelector('.pill-badge');
    if (!badge) return;
    badge.className = 'pill-badge' + (state ? ' on ' + state : '');
    badge.textContent = state === 'gen' ? '生成中' : (state === 'live' ? '进行中' : '未开局');
  }

  /* ── 原生界面主题化样式：宿主 head；创建时即 disabled，首帧后才启用。
   * V8 核心：THEME_CSS = body.ark-shell-on 作用域的原生 DOM 重新皮肤
   * （楼层玻璃卡/箭头/表单/滚动条），不隐藏任何原生管线；禁用本表
   * （退出/降级）即恢复原生直陈。 */
  function ensureThemeStyle() {
    var d = HD();
    var s = d.getElementById(THEME_ID);
    if (s) { SH.themeEl = s; return s; }
    s = d.createElement('style');
    s.id = THEME_ID;
    s.media = 'not all';                      // disabled 等价（media 不匹配即不生效）
    s.textContent = THEME_CSS;                // 08：原生界面主题（楼层/表单/布局）
    (d.head || d.documentElement).appendChild(s);
    SH.themeEl = s;
    return s;
  }
  function applyTheme()  { var s = ensureThemeStyle(); try { s.media = 'all'; } catch (e) {} }
  function restoreNative() {                   // 恢复原生显示（退出第一步，必须最先做）
    try { var s = HD().getElementById(THEME_ID); if (s) s.media = 'not all'; } catch (e) {}
  }

  /* ── 背景增暗+青调层（body 首子；z=1 高于 #bg1 的 -1、低于 #sheld 的 30）
   * 用户背景透出但整体压暗偏青；退出对称移除。 */
  function ensureBackdrop() {
    var d = HD();
    var b = d.getElementById(BACKDROP_ID);
    if (b) { SH.backdropEl = b; return b; }
    b = el('div');
    b.id = BACKDROP_ID;
    try { b.appendChild(el('div', 'ark-bglow')); } catch (e0) {}   // V9：底缘辉光（黑边修复）
    try { b.appendChild(buildDragonLayer()); } catch (eD) {}   // V10：巨龙背景层（模块 04d）
    if (d.body && d.body.firstChild) d.body.insertBefore(b, d.body.firstChild);
    else if (d.body) d.body.appendChild(b);
    SH.backdropEl = b;
    return b;
  }

  /* ── 实时节点定位：ST 1.19 存在 jQuery UI 菜单克隆出的同名隐藏节点
   * （实测 document.querySelectorAll('#sheld') 可得 2 个，首个不可见）。
   * 取「有真实尺寸」的那个；全部不可见时退回 getElementById。 */
  function liveNode(id) {
    try {
      var d = HD();
      var list = d.querySelectorAll('#' + id);
      for (var i = 0; i < list.length; i++) {
        var n = list[i];
        try {
          if (n.getBoundingClientRect().height > 0 && getComputedStyle(n).display !== 'none') return n;
        } catch (e) {}
      }
      /* V6：全部候选不可见（#chat 被 THEME_CSS 隐藏）→ 排除 jQuery
       * UI 弹层克隆（.ui-dialog / #ui-id-*），取祖先直达 body 的真身 */
      for (var j = 0; j < list.length; j++) {
        var m = list[j];
        try {
          if (m.closest && (m.closest('.ui-dialog') || m.closest('.ui-dialog-content') ||
              m.closest('[id^="ui-id-"]'))) continue;
        } catch (e0) {}
        var p = m.parentElement, hops = 0;
        while (p && hops < 5) { if (p === d.body) return m; p = p.parentElement; hops++; }
      }
      return d.getElementById(id);
    } catch (e) { return null; }
  }

  /* ── 顶栏槽位：插入 #sheld 原生 flex 流（#chat 之前）─────────────
   * V8：唯一的流内注入。正文区 = 原生 #chat 本尊，输入区 = 原生
   * #form_sheld 本尊（均由 THEME_CSS 重新皮肤化，DOM/事件/正则/
   * 流式/滑动管线 100% 原生）。原生 flex 列自适应：键盘弹出/旋转/
   * 窄屏全部由原生布局兜底，壳不做任何 fixed 定位补丁。 */
  function mountTopbar() {
    var d = HD();
    var sheld = liveNode('sheld');
    if (!sheld) { console.warn('[ark-shell] 未找到 #sheld，顶栏跳过（仅覆盖层模式）'); return; }

    var tb = d.getElementById('ark-tb-slot');
    if (!tb) {
      tb = el('div'); tb.id = 'ark-tb-slot';
      var chatEl = liveNode('chat');
      if (chatEl && chatEl.parentNode === sheld) sheld.insertBefore(tb, chatEl);
      else sheld.insertBefore(tb, sheld.firstChild);
    }
    SH.tbSlot = tb;
    SH.topbar = el('header', 'topbar');
    try { renderTopbar(SH.topbar); } catch (e) { logErr(e); }
    tb.textContent = '';
    tb.appendChild(SH.topbar);
    try { syncTopNav(); } catch (e) {}

    /* V9：行动指令条槽位（#chat 之后、控制台之前；原生 flex 流）*/
    var ab = d.getElementById('ark-ab-slot');
    if (!ab) {
      ab = el('div'); ab.id = 'ark-ab-slot';
      var form0 = liveNode('form_sheld');
      if (form0 && form0.parentNode === sheld) sheld.insertBefore(ab, form0);
      else sheld.appendChild(ab);
    }
    SH.abSlot = ab;
    SH.actionBar = el('div', 'action-bar');
    SH.actionBar.setAttribute('hidden', '');
    ab.textContent = '';
    ab.appendChild(SH.actionBar);

    /* V9：战术控制台槽位（原生 #form_sheld 由 THEME_CSS 隐藏退位）*/
    var ips = d.getElementById('ark-input-slot');
    if (!ips) {
      ips = el('div'); ips.id = 'ark-input-slot';
      var form1 = liveNode('form_sheld');
      if (form1 && form1.parentNode === sheld) sheld.insertBefore(ips, form1);
      else sheld.appendChild(ips);
    }
    SH.inputSlot = ips;
    try { buildConsole(); } catch (e) { logErr(e); }
    try { buildActionBar(); } catch (e) { logErr(e); }
  }

  function enterShell() {
    if (SH.mounted) return;
    var d = HD();
    ensureThemeStyle();                       // 预置主题样式（仍 disabled）
    ensureBackdrop();                         // 背景层（立即可见：非破坏性）

    var root = el('div');
    root.id = ROOT_ID;
    // pointer-events:none 覆盖层：点击穿透到原生楼层/表单/箭头；铬件子元素自行恢复 auto
    root.style.cssText = 'position:fixed;top:0;left:0;right:0;height:100vh;height:100dvh;z-index:9000;pointer-events:none;';
    root.setAttribute('data-view', 'story');
    root.setAttribute('data-fs', lsGet('fs', 'm'));
    root.setAttribute('data-theme', lsGet('theme', 'island'));   /* V7 主题令牌 */
    root.setAttribute('data-motion', lsGet('motion', 'auto'));
    try { SH.backdropEl.setAttribute('data-motion', lsGet('motion', 'auto')); } catch (e0) {}
    d.body.appendChild(root);
    SH.rootEl = root;
    SH.mounted = true;
    SH.enteredAt = Date.now();
    SH.overlayStack = [];

    try { injectStyle(root); } catch (e) { logErr(e); }   // 08：壳铬件样式
    try { buildIface(root); } catch (e) { logErr(e); }    // 04：铬件装配（veil/面板/浮层宿主）
    try { mountTopbar(); } catch (e) { logErr(e); }       // V9 槽位组：顶栏+行动条+控制台（#sheld 流内）
    try { applyFs(lsGet('fs', 'm')); } catch (e) {}       // 字号同步（原生楼层 + 壳）

    // 主题启用：等待壳首帧真实渲染完成（两帧 rAF）——壳未就绪不动原生界面。
    // V8：接管 = 主题样式表（body.ark-shell-on 作用域）+ body 类双保险。
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        if (!SH.mounted || !SH.rootEl) return;
        try { enterTakeover(); } catch (e) {}             // ① body.ark-shell-on
        applyTheme();                                     // ② THEME_CSS 启用（原生重皮肤）
        try { startCardFilter(); } catch (e) {}            // ③ 卡内前端过滤（外来正则零影响）
        try { HD().documentElement.setAttribute('data-ark-theme', lsGet('theme', 'island')); } catch (e) {}
        try { markDirty(); } catch (e) {}                 // 首轮数据渲染
        try { refreshStatus(); } catch (e) {}
        try { if (SH.pillEl) SH.pillEl.style.display = 'none'; } catch (e) {}
        try { scrollChatBottom(); } catch (e) {}
      });
    });

    // Esc 浮层栈（挂宿主 document；壳卸载时移除）
    try {
      SH.escHandler = function (ev) {
        if (ev.key !== 'Escape') return;
        if (!SH.mounted) return;
        if (popOverlay()) return;                                              /* 先关浮层 */
        if (SH.view !== 'story') { try { switchView('story'); } catch (e0) {} } /* 再退面板（锁死保险④）*/
      };
      d.addEventListener('keydown', SH.escHandler, true);
    } catch (e) {}

    updatePill(SH.busy || SH.genActive ? 'gen' : 'live');
  }

  /* ── 退出终端（对称：先禁用主题恢复原生，再收顶栏槽位与壳）────── */
  function exitShell(byUser) {
    if (!SH.mounted) { if (byUser) SH.userExited = true; return; }
    var d = HD();
    restoreNative();                          // ① 主题禁用 → 原生外观即刻恢复
    try { exitTakeover(); } catch (e) {}      // ② body.ark-shell-on 移除（双保险）
    try { stopCardFilter(true); } catch (e) {} // ③ 卡内过滤停止+清标记 → 原生挂件即刻恢复
    try { if (SH.escHandler) d.removeEventListener('keydown', SH.escHandler, true); } catch (e) {}
    SH.escHandler = null;
    try { closeAllOverlays(); } catch (e) {}
    // ③ 移除顶栏/行动条/控制台槽位（#sheld 恢复原结构：header/chat/form）
    try { if (SH.tbSlot && SH.tbSlot.parentNode) SH.tbSlot.parentNode.removeChild(SH.tbSlot); } catch (e) {}
    try { if (SH.abSlot && SH.abSlot.parentNode) SH.abSlot.parentNode.removeChild(SH.abSlot); } catch (e) {}
    try { if (SH.inputSlot && SH.inputSlot.parentNode) SH.inputSlot.parentNode.removeChild(SH.inputSlot); } catch (e) {}
    try { HD().documentElement.removeAttribute('data-ark-theme'); } catch (e) {}
    SH.tbSlot = null; SH.topbar = null; SH.abSlot = null; SH.actionBar = null;
    SH.inputSlot = null; SH.inputBar = null; SH.inputTa = null; SH.inputSend = null;
    SH.railEl = null;
    requestAnimationFrame(function () {        // ④ 原生可见后再移除壳根与背景层
      try { if (SH.rootEl && SH.rootEl.parentNode) SH.rootEl.parentNode.removeChild(SH.rootEl); } catch (e) {}
      try { if (SH.backdropEl && SH.backdropEl.parentNode) SH.backdropEl.parentNode.removeChild(SH.backdropEl); } catch (e) {}
      SH.rootEl = null; SH.backdropEl = null; SH.mounted = false;
      SH.veilEl = null; SH.viewsEl = null; SH.overlayHost = null; SH.toastHost = null;
      SH.statusSheet = null; SH.dashIframe = null; SH.dashOpen = false;
      SH.view = 'story';
      try { if (SH.pillEl) SH.pillEl.style.display = ''; } catch (e) {}
      updatePill(SH.busy || SH.genActive ? 'gen' : 'live');
    });
    if (byUser) SH.userExited = true;         // 用户主动退出 → 本会话不再自动进入
  }

  /* ── 浮层栈：push 返回 close()；Esc 逐层关闭 ────────────────── */
  function pushOverlay(node, opts) {
    var host = SH.overlayHost || SH.rootEl;
    if (!host || !node) return function () {};
    var closed = false;
    function close() {
      if (closed) return; closed = true;
      var i = SH.overlayStack.indexOf(close);
      if (i >= 0) SH.overlayStack.splice(i, 1);
      try {
        node.classList.add('ov-out');
        setTimeout(function () { if (node.parentNode) node.parentNode.removeChild(node); }, 180);
      } catch (e) { try { if (node.parentNode) node.parentNode.removeChild(node); } catch (e2) {} }
    }
    SH.overlayStack.push(close);
    node.classList.add('ov-in');
    if (opts && opts.sheet) node.classList.add('sheet');
    host.appendChild(node);
    return close;
  }
  function popOverlay() {
    var close = SH.overlayStack.pop();
    if (typeof close === 'function') { close(); return true; }
    return false;
  }
  function closeAllOverlays() {
    while (SH.overlayStack.length) { try { SH.overlayStack.pop()(); } catch (e) {} }
  }

  /* ── Toast：toastr 优先（宿主全局），壳内/宿主自绘兜底 ───────── */
  function toast(msg, type) {
    var t = type || 'info';
    try {
      var tt = H().toastr;
      if (tt && tt[t] && typeof tt[t] === 'function') { tt[t](String(msg)); return; }
    } catch (e) {}
    try {
      var d = HD();
      var host = (SH.mounted && SH.toastHost) ? SH.toastHost : d.body;
      var n = el('div', 'ark-toast ' + t, msg);
      host.appendChild(n);
      setTimeout(function () {
        n.classList.add('out');
        setTimeout(function () { if (n.parentNode) n.parentNode.removeChild(n); }, 300);
      }, 2600);
    } catch (e) {}
  }


  /* ═══════════════════════════════════════════════════════════════════
   * 模块 03 · 数据：楼层读取与八块解析 / HUD 快照 / 字段解析器 /
   *              图鉴影像映射 + chainLoad 四层镜像链
   * 解析正则沿用卡内 findRegex 模式；流式半截标签容忍（按原文显示）。
   * ═══════════════════════════════════════════════════════════════════ */

  /* ── 八块标签（与卡内正则 findRegex 同构）────────────────────── */
  var TAG_NAMES = ['NARRATIVE', 'ARK_EVENT', 'CONTEXT_options', 'CONTEXT_summary',
                   'UpdateVariable', 'ARK_HUD_DATA', 'ARK_BOSS_DATA', 'ARK_DOSSIER_DATA'];
  var RX_OPENING = /<ARK_OPENING>[\s\S]*?(?:<\/ARK_OPENING>|$)/;
  var RX_AWAKEN  = /【苏醒】/;
  // 外卡常见包装标签黑名单（仅从显示文本剥离；闭合才剥，半截只剥标签本身）
  var RX_FOREIGN = /<(status_panel|statuspanel|StatusPanel|StatusPlaceHolderImpl|dream_[a-z_]*|SUOT|advice|sepia_[a-z_]*|content|exchange|options|Analysis|JSONPatch|narrative_out|narrator_block_ignore|thinking|thought)>([\s\S]*?)<\/\1>/gi;
  var RX_FOREIGN_TAG = /<\/?\s*(?:status_panel|statuspanel|StatusPanel|StatusPlaceHolderImpl|dream_[a-z_]*|SUOT|advice|sepia_[a-z_]*|content|exchange|options|Analysis|JSONPatch|narrative_out|narrator_block_ignore|thinking|thought)\b[^>]*>/gi;
  // 本卡协议标签任意形态（开/闭/半截）：仅用于显示文本净化（块提取已先行）
  var RX_OUR_TAG_ANY = /<\/?\s*(?:NARRATIVE|ARK_EVENT|CONTEXT_options|CONTEXT_summary|UpdateVariable|ARK_HUD_DATA|ARK_BOSS_DATA|ARK_DOSSIER_DATA)\s*(?:\s[^>]*)?>/gi;
  var RX_OUR_OPEN_ANY = /<\s*(?:NARRATIVE|ARK_EVENT|CONTEXT_options|UpdateVariable|ARK_HUD_DATA|ARK_BOSS_DATA|ARK_DOSSIER_DATA)\b/i;

  function blockRx(name) {
    /* 容错：允许标签内空白/属性/大小写差异（其他正则或模型微小偏离不致命） */
    return new RegExp('<\\s*' + name + '(?:\\s[^>]*)?>\\r?\\n?([\\s\\S]*?)<\\s*/\\s*' + name + '\\s*>', 'i');
  }

  /* user 楼判定（is_user 与 role 双通道容错）*/
  function isUserMsg(cm) {
    if (!cm) return false;
    if (cm.is_user !== undefined) return !!cm.is_user;
    return cm.role === 'user';
  }

  /* ── 单楼解析：AI 楼拆八块；user 楼原样；容错免疫非本卡楼层 ────
   * V4.3 顺序调整：外卡标签（options/tucao/content 等用户其他卡的正则
   * 目标）不再在此剥离——先保留进 f.text，让全局/预设正则有机会转换
   * （与原生顺序一致：正则先跑）；未被任何正则消费的残余由
   * stripForeignLeftovers() 在正则之后统一清理（readAll 内调用）。*/
  function parseFloor(cm) {
    var f = {
      id: cm.message_id,
      isUser: isUserMsg(cm),
      name: cm.name || '',
      raw: cm.message || '',
      text: '',            // 展示正文（叙事；V4.3 起保留外卡标签，正则后再清）
      blocks: null,        // {narrative,event,options,summary,hud,boss,dossier}
      opening: false,      // 楼0 ARK_OPENING 开局占位
      awakening: false,    // 【苏醒】开局指令标记（user 楼）
      streaming: false,    // 流式中（存在未闭合块标签）
      valid: false,        // 属于方舟协议楼层
      day: 0               // 从 HUD 时间提取的天数（分节线用）
    };
    f.isSystem = !!(cm && cm.is_system);   // V6：系统楼标记（feed 跳过，与原生 #chat 隐藏一致）
    var t = f.raw;
    if (f.isUser) {
      f.awakening = RX_AWAKEN.test(t);
      f.text = t;
      f.valid = true;      // user 楼一律展示（右对齐指令气泡）
      return f;
    }
    // AI 楼：本卡八块提取（外卡标签保留——用户正则的目标，见函数头注释）
    var rest = String(t);
    var blocks = {}, hit = false;
    for (var i = 0; i < TAG_NAMES.length; i++) {
      var name = TAG_NAMES[i];
      var m = rest.match(blockRx(name));
      if (m) { blocks[name] = m[1]; hit = true; }
    }
    if (hit) {
      // 从展示文本中移除已捕获的闭合块（用函数替换，规避 $ 转义陷阱）
      for (var k = 0; k < TAG_NAMES.length; k++) {
        var nm = TAG_NAMES[k];
        var grx = new RegExp('<\\s*' + nm + '(?:\\s[^>]*)?>[\\s\\S]*?<\\s*/\\s*' + nm + '\\s*>', 'gi');
        rest = rest.replace(grx, function () { return ''; });
      }
      blocks.narrative = blocks.NARRATIVE != null ? blocks.NARRATIVE : null;
      blocks.event     = blocks.ARK_EVENT != null ? blocks.ARK_EVENT : null;
      blocks.options   = blocks.CONTEXT_options != null ? blocks.CONTEXT_options : null;
      blocks.summary   = blocks.CONTEXT_summary != null ? blocks.CONTEXT_summary : null;
      blocks.hud       = blocks.ARK_HUD_DATA != null ? blocks.ARK_HUD_DATA : null;
      blocks.boss      = blocks.ARK_BOSS_DATA != null ? blocks.ARK_BOSS_DATA : null;
      blocks.dossier   = blocks.ARK_DOSSIER_DATA != null ? blocks.ARK_DOSSIER_DATA : null;
    }
    // 本卡协议标签净化（含流式半截）与围栏标记剥离照旧；
    // 外卡标签处理已移至外部正则之后（stripForeignLeftovers）
    rest = rest.replace(RX_OUR_TAG_ANY, '')
               .replace(/```[a-zA-Z]*\r?\n?/g, '');
    if (!hit) rest = stripResidue(rest);   // 其他正则已剥掉标签的楼：启发式滤掉协议残迹
    /* V7.0.1：streaming = 存在未闭合协议块（开闭计数差）。V6 起此判定
     * 只查开标签存在，完整楼也命中 → 生成结束后打字光标永挂。 */
    f.streaming = (function () {
      var s = String(t);
      var tags = ['NARRATIVE', 'ARK_EVENT', 'CONTEXT_options', 'UpdateVariable', 'ARK_HUD_DATA', 'ARK_BOSS_DATA', 'ARK_DOSSIER_DATA'];
      for (var i = 0; i < tags.length; i++) {
        var open = (s.match(new RegExp('<\\s*' + tags[i] + '\\b', 'gi')) || []).length;
        var close = (s.match(new RegExp('</\\s*' + tags[i] + '\\s*>', 'gi')) || []).length;
        if (open > close) return true;
      }
      return false;
    })();
    f.opening = RX_OPENING.test(String(t));
    f.valid = hit || f.opening;
    // 展示正文：优先 NARRATIVE 内容；否则净化后的剩余文本（开局楼显示降级说明）
    if (blocks.narrative != null) f.text = blocks.narrative;
    else f.text = rest;
    f.blocks = hit ? blocks : null;
    if (blocks.hud != null) {
      f.day = hudParseDay(blocks.hud);   // 从 HUD 时间字段提取天数（分节线）
    }
    return f;
  }

  /* ── 外卡残余清理（V4.3：外部正则之后调用）──────────────────────
   * 用户正则已消费的标签（如 <options>→前端）不会到达这里；
   * 未被消费的外卡标签按 V4.2 纪律剥离（闭合剥块[内含本卡标签只剥壳]、
   * 任意形态剥标签），绝不让原始标签文字混进正文。*/
  function stripForeignLeftovers(text) {
    var out = String(text == null ? '' : text);
    out = out.replace(RX_FOREIGN, function (all, tag, inner) {
      return RX_OUR_OPEN_ANY.test(inner) ? inner : '';
    });
    out = out.replace(RX_FOREIGN_TAG, '');
    return out;
  }

  /* ── 协议残迹过滤器（其他正则把标签剥掉后，数据行不该当正文展示）──
   * 只删「几乎全是协议数据」的行，叙事行一字不动 */
  function stripResidue(text) {
    var lines = String(text || '').split(/\r?\n/);
    var keep = [];
    for (var i = 0; i < lines.length; i++) {
      var t = trimS(lines[i]);
      if (!t) { keep.push(''); continue; }
      if (/^[[{]/.test(t) && /"(?:op|path|value|opText|ref|opid)"/.test(t)) continue;      // JSONPatch 残迹
      if (/^(?:分析|变更说明|变量更新)[:：]/.test(t)) continue;                              // 补丁说明
      if (/^驯服开始\s*[|｜]/.test(t)) continue;                                             // 驯服指令行
      if (/^(?:稳妥|进取|探索)行动\s*[:：]/.test(t)) continue;                                // 选项残迹
      if (isEventChainLine(t)) continue;                                                     // 事件链行
      if (isHudFieldLine(t)) continue;                                                       // HUD 字段行
      keep.push(lines[i]);
    }
    return trimS(keep.join('\n').replace(/\n{3,}/g, '\n\n'));
  }
  /* 事件链行：「经验+8｜物品+纤维×40｜…」绝大多数段都是事件格式 */
  function isEventChainLine(t) {
    var parts = t.split(/[｜|;；]/);
    if (parts.length < 2) return false;
    var hits = 0, nonEmpty = 0;
    for (var i = 0; i < parts.length; i++) {
      var s = trimS(parts[i]).replace(/\s+/g, '');
      if (!s) continue;
      nonEmpty++;
      if (/^(?:经验|物品|麻醉|驯服|状态|属性点|印痕点|生物经验)[+\-＋－]/.test(s)) hits++;
    }
    return nonEmpty >= 2 && hits >= nonEmpty - 1;
  }
  /* HUD 字段行：「生命: 100/100｜耐力: 92/100｜…」≥3 段键值对 */
  function isHudFieldLine(t) {
    var parts = t.split(/[｜|]/);
    if (parts.length < 3) return false;
    var kv = 0, nonEmpty = 0;
    for (var i = 0; i < parts.length; i++) {
      var s = trimS(parts[i]);
      if (!s) continue;
      nonEmpty++;
      if (/^[^:：]{1,8}[:：]\s*\S/.test(s)) kv++;
    }
    return nonEmpty >= 3 && kv >= nonEmpty;
  }


  /* ── 全量楼层读取（getChatMessages 全楼，逐楼解析入缓存）────── */
  function readAll() {
    var list = [];
    /* depth 表：楼号 → 原生语义深度（非 is_system 楼倒数计数）。
     * 原生源：script.js messageFormatting 的 usableMessages 逻辑；
     * 宿主 chat 数组缺席（极端环境）→ 全楼 depth=undefined（不按深度
     * 过滤，等价于原生「不传 depth」语义，宁多勿漏）。*/
    var depthMap = null;
    try {
      var hostChat = H().SillyTavern.getContext().chat;
      if (hostChat && hostChat.length) {
        depthMap = {};
        var usable = [];
        for (var d = 0; d < hostChat.length; d++) {
          if (!(hostChat[d] && hostChat[d].is_system)) usable.push(d);
        }
        for (var u = 0; u < usable.length; u++) depthMap[usable[u]] = usable.length - u - 1;
      }
    } catch (e) { depthMap = null; }
    try {
      var raw = (typeof getChatMessages === 'function')
        ? getChatMessages('0-{{lastMessageId}}') : [];
      if (raw && raw.length) {
        for (var i = 0; i < raw.length; i++) {
          if (!raw[i]) continue;
          try {
            var f = parseFloor(raw[i]);
            f.depth = depthMap ? depthMap[f.id] : undefined;
            list.push(f);
          } catch (e) { logErr(e); }
        }
      }
    } catch (e) { logErr(e); }
    SH.floors = list;
    SH.dirty = false;
  }
  function ensureFloors() {
    if (SH.dirty || !SH.floors) readAll();
    return SH.floors;
  }
  function lastFloor() {
    var fs = ensureFloors();
    return fs.length ? fs[fs.length - 1] : null;
  }
  function latestAiFloor() {
    var fs = ensureFloors();
    for (var i = fs.length - 1; i >= 0; i--) if (!fs[i].isUser) return fs[i];
    return null;
  }

  /* ── HUD 载荷解析：13 全角字段。
   * 兼容两种形态：多行（AI 常见输出，规范示例即逐行）与单行全角｜分隔。
   * 分隔符集：换行 / 全角｜半角| / 全角；半角; 均可，中英冒号均可。*/
  function hudParseFields(line) {
    var out = { order: [], map: {} };
    var s = String(line == null ? '' : line).trim();
    if (!s) return out;
    var parts = s.split(/[\r\n]+|[｜|；;]/);
    for (var i = 0; i < parts.length; i++) {
      var p = trimS(parts[i]);
      if (!p) continue;
      var m = p.match(/^([^:：]{1,12})[:：]\s*(.*)$/);
      if (m) {
        var key = trimS(m[1]), val = trimS(m[2]);
        if (key) {
          if (!(key in out.map)) out.order.push(key);
          out.map[key] = val;
        }
      }
    }
    return out;
  }
  /* HUD 时间字段 → 天数（"第N天 HH:MM（时段）"） */
  function hudParseDay(line) {
    var m = String(line || '').match(/第(\d+)天/);
    return m ? (parseInt(m[1], 10) || 0) : 0;
  }

  /* HUD 快照：优先 ARK_CORE.hud.payload()（HUD≡引擎状态），兜底最新楼 ARK_HUD_DATA */
  function hudSnapshot() {
    var raw = '';
    if (SH.coreReady) {
      try { raw = String(H().ARK_CORE.hud.payload() || ''); } catch (e) { raw = ''; }
    }
    if (raw) return { src: 'core', raw: raw, fields: hudParseFields(raw) };
    var ai = latestAiFloor();
    if (ai && ai.blocks && ai.blocks.hud) {
      return { src: 'floor', raw: ai.blocks.hud, fields: hudParseFields(ai.blocks.hud) };
    }
    return null;
  }

  /* ── 具名字段块解析（Boss 8 字段 / 图鉴 9 字段：行式 key: value）─ */
  function parseNamedFields(text) {
    var map = {}, order = [];
    var lines = String(text || '').split(/\r?\n/);
    for (var i = 0; i < lines.length; i++) {
      var ln = trimS(lines[i]);
      if (!ln) continue;
      var m = ln.match(/^([^:：]{1,14})[:：]\s*(.*)$/);
      if (m) {
        var key = trimS(m[1]);
        if (key && !(key in map)) { map[key] = trimS(m[2]); order.push(key); }
      }
    }
    return { map: map, order: order };
  }

  /* ── 行动选项解析：稳妥行动：/进取行动：/探索行动： 恰好三项 ─── */
  function parseOptions(text) {
    var opts = [];
    var lines = String(text || '').split(/\r?\n/);
    for (var i = 0; i < lines.length; i++) {
      var ln = trimS(lines[i]);
      if (!ln) continue;
      var m = ln.match(/^([^:：]{1,8})[:：]\s*(.+)$/);
      if (m && /行动$/.test(trimS(m[1]))) {
        opts.push({ label: trimS(m[1]), text: trimS(m[2]) });
      } else if (ln) {
        opts.push({ label: '', text: ln });   // 容错：无前缀行也当选项
      }
    }
    return opts;
  }

  /* ── ARK_EVENT 增量解析（与引擎 parseEvent 同规则，显示与结算一致）──
   * 规则：先捕特殊指令「驯服开始|种族|Lv|方式」（半角竖线容错），
   * 再按 [｜|;；\n] 分段，归一 ＋－ｘ＊ 与空白，逐段归类。 */
  function parseEvents(text) {
    var evts = [];
    var line = String(text || '');
    // 特殊指令：驯服开始|种族|Lv等级|方式（挂件同款容错正则）
    line = line.replace(/驯服开始\s*[|｜]\s*([^|｜;；]+?)\s*[|｜]\s*(?:[Ll][Vv]\.?\s*|等级\s*)?(\d+)\s*[|｜]\s*(击晕|被动)/g,
      function (all, sp, lv, md) {
        evts.push({ kind: 'tamestart', species: trimS(sp), level: parseInt(lv, 10) || 1, mode: md, text: '驯服开始 ' + trimS(sp) + ' Lv.' + (parseInt(lv, 10) || 1) + ' ' + md });
        return ' ';
      });
    var parts = line.split(/[｜|;；\n]/);
    for (var i = 0; i < parts.length; i++) {
      var seg = String(parts[i]).replace(/＋/g, '+').replace(/－/g, '-').replace(/[ｘ＊]/g, 'x').replace(/\s+/g, '');
      if (!seg) continue;
      var e = { kind: 'other', text: seg, neg: false };
      var m;
      if ((m = seg.match(/^经验([+\-])([\d.]+)/))) { e.kind = 'exp'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^生物经验([+\-])(\d+)[·,，:：](.+)$/))) { e.kind = 'dinoexp'; e.num = m[2]; e.name = m[3]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^生物经验[·,，:：](.+?)([+\-])(\d+)$/))) { e.kind = 'dinoexp'; e.name = m[1]; e.num = m[3]; e.neg = m[2] === '-'; }
      else if ((m = seg.match(/^物品([+\-])(\d+)[×xX*](.+)$/))) { e.kind = 'item'; e.name = m[3]; e.num = m[2]; e.sign = m[1]; e.neg = m[1] === '-'; }  // 数量前置：物品+3×纤维
      else if ((m = seg.match(/^物品([+\-])(.+?)(?:[×xX*](\d+))?$/))) { e.kind = 'item'; e.name = trimS(m[2]); e.num = m[3] != null ? m[3] : '1'; e.sign = m[1]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^麻醉([+\-])(\d+)/))) { e.kind = 'narc'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^驯服([+\-])(\d+)/))) { e.kind = 'tame'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^状态([+\-])(.+)$/))) { e.kind = 'status'; e.name = m[2]; e.sign = m[1]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^属性点([+\-])(\d+)/))) { e.kind = 'statpt'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^印痕点([+\-])(\d+)/))) { e.kind = 'engpt'; e.num = m[2]; e.neg = m[1] === '-'; }
      evts.push(e);
    }
    return evts;
