  /* 文件名白名单校验：防注入（只允许安全字符，严禁协议/路径分隔） */
  function safeImgFile(file) {
    var f = String(file || '');
    if (!/^[A-Za-z0-9_.\-() ]{3,120}\.png$/i.test(f)) return '';
    if (f.indexOf('..') >= 0) return '';
    return f;
  }

  /* chainLoad 四层镜像链：wsrv.nl → images.weserv.nl → wiki 直链 → 剪影占位
   * 影像仅限 wsrv.nl / images.weserv.nl / ark.wiki.gg 三域白名单；
   * URL 构造与原卡图鉴正则逐字一致（明文斜杠），另加 12s 超时防慢链路无限挂起 */
  function chainLoad(imgEl, file, w) {
    var f = safeImgFile(file);
    if (!imgEl) return;
    if (!f) { silhouetteFallback(imgEl); return; }
    var urls = [
      'https://wsrv.nl/?url=ark.wiki.gg/images/' + f + '&w=' + w + '&output=webp&q=58',
      'https://images.weserv.nl/?url=ark.wiki.gg/images/' + f + '&w=' + w + '&output=webp&q=58',
      'https://ark.wiki.gg/images/thumb/' + f + '/' + (w + 40) + 'px-' + f
    ];
    var i = -1, timer = null;
    imgEl.classList.remove('img-fallback');
    function next() {
      if (timer) { clearTimeout(timer); timer = null; }
      i++;
      if (i < urls.length) {
        imgEl.src = urls[i];
        timer = setTimeout(next, 12000);            // 慢链路兑底：12s 无响应试下一层
      } else {
        silhouetteFallback(imgEl);                  // 剪影/emoji 占位
      }
    }
    imgEl.addEventListener('error', function onErr() {
      if (i >= urls.length) { imgEl.removeEventListener('error', onErr); return; }
      next();
    });
    next();
  }
  /* 物种名 → Dossier 文件（与原卡图鉴正则 lookup 同规则：剥括注→最长子串→前缀）
   * 实测教训：真机模型常输出「渡渡鸟（Dodo）」带英文括注，精确匹配必挂 */
  function speciesImg(species) {
    var s = String(species || '').trim();
    if (!s) return '';
    if (Object.prototype.hasOwnProperty.call(IMG_MAP, s)) return IMG_MAP[s];
    var cn = s.replace(/[（(][^（()）]*[）)]/g, '')          // 剥括注：渡渡鸟（Dodo）→渡渡鸟
               .replace(/^(?:一只|一头|一群|几只)/, '')
               .replace(/[\s·、，。.!！?？\-—~～]+$/g, '').trim();
    if (!cn) return '';
    if (Object.prototype.hasOwnProperty.call(IMG_MAP, cn)) return IMG_MAP[cn];
    var best = '';
    for (var k in IMG_MAP) {                                   // 最长子串包含
      if (Object.prototype.hasOwnProperty.call(IMG_MAP, k) && k.length > best.length && cn.indexOf(k) > -1) best = k;
    }
    if (best) return IMG_MAP[best];
    if (cn.length > 1) {                                       // 前缀匹配（渡渡鸟群→渡渡鸟）
      for (var k2 in IMG_MAP) {
        if (Object.prototype.hasOwnProperty.call(IMG_MAP, k2) && k2.indexOf(cn) === 0) return IMG_MAP[k2];
      }
    }
    return '';
  }

  /* 四层全失败 → 剪影/emoji 占位节点（img 是替换元素，::after 伪元素不可用）
   * 挂载安全：若 img 尚未 append（调用方顺序错误/未来改动），rAF 重试至挂载后再替换；
   * 实测教训：旧版在未挂载时静默降级 → img 无 src 留在 DOM → 浏览器显示 alt 文字空白框 */
  function silhouetteFallback(imgEl) {
    var tries = 0;
    (function attempt() {
      if (!imgEl) return;
      if (imgEl.parentNode) {
        try {
          var fb = el('div', 'img-fb');
          fb.textContent = '🦖';
          fb.setAttribute('aria-label', (imgEl.alt || '未知生物') + '（无影像）');
          imgEl.parentNode.insertBefore(fb, imgEl);
          imgEl.parentNode.removeChild(imgEl);
          return;
        } catch (e) {}
      }
      if (tries++ < 40) requestAnimationFrame(attempt);      // ≤40帧（约0.7s）等调用方挂载
      else { imgEl.classList.add('img-fallback'); imgEl.removeAttribute('src'); }
    })();
  }

  /* ── MVU schema 兼容桥（V4.1）──────────────────────────────────
   * 实测（ST1.19 + TH4.11 + 卡内锁定版 MVU）：MVU 补丁门 gn() 要求基线
   * 快照同时含 stat_data 与 schema 标记；本卡引擎的 MVU 直写只写
   * stat_data，新会话 0 号楼亦可能未被 Un 自举（欢迎面板竞态）→
   * 后续全部 UpdateVariable 补丁被静默丢弃（图鉴/编年史/状态全空）。
   * 桥：发现「有 stat_data 且无 schema」的最新楼时，仅补写 MVU 生态
   * 约定的技术标记 schema:'没有用别管这个'（zod util 同款字符串），
   * 不触碰任何游戏数据。幂等；健康环境（已有 schema）下永不触发。 */
  function mvuSchemaBridge() {
    if (!SH.coreReady || SH.schemaBridged) return;
    try {
      if (typeof getVariables !== 'function' || typeof replaceVariables !== 'function') return;
      var cur = getVariables({ type: 'message', message_id: -1 });
      if (!cur || typeof cur !== 'object') return;
      if (!cur.stat_data || cur.schema !== undefined) return;
      cur.schema = '没有用别管这个';
      replaceVariables(cur, { type: 'message', message_id: -1 });
      SH.schemaBridged = true;
      console.info('[ark-shell] MVU schema 兼容桥：最新楼快照缺 schema 标记，已补写（仅技术标记，游戏数据零触碰）');
    } catch (e) {}
  }

  /* ── 引擎状态便捷读取（只读；引擎缺席时全部返回 null/{}）────── */
  function statOf() {
    if (!SH.coreReady) return null;
    try { var st = H().ARK_CORE.getState(); if (st && st['主角_生存状态']) return st; } catch (e) {}
    return null;
  }
  function levelInfo() {
    var st = statOf();
    if (!st) return null;
    var su = st['主角_生存状态'] || {};
    return {
      level: su['等级'], exp: su['经验'], expMax: su['经验上限'],
      statPts: su['属性点'], engPts: su['印痕点'], name: su['姓名']
    };
  }
  function dossierEntries() {
    var st = statOf();
    if (!st) return null;
    var w = st['世界_领土势力'] || {};
    var d = w['生物图鉴'];
    return (d && typeof d === 'object') ? d : null;
  }
  function chronicleEntries() {
    if (SH.coreReady) {
      try {
        var l = H().ARK_CORE.chronicle.list();
        if (l && l.length) return l;
      } catch (e) {}
    }
    var st = statOf();
    if (!st) return null;
    var arr = (st['世界_领土势力'] || {})['大事记'];
    return Array.isArray(arr) ? arr : null;
  }


  /* ═══════════════════════════════════════════════════════════════════
   * 模块 04 · 界面装配：壳根=pointer-events:none 覆盖层。
   *   桌面(≥900)：左缘 rail 图标栏（V9 恢复并加大）
