  function buildIface(root) {
    /* V9：桌面左缘导航 rail（≥900 显示；按钮加大；用户第八轮钦定
     * 「电脑端那一排按钮就和之前一样放在左边」）*/
    SH.railEl = el('nav', 'rail');
    SH.railEl.setAttribute('aria-label', '终端导航');
    try { buildRail(SH.railEl); } catch (e) { logErr(e); }
    root.appendChild(SH.railEl);

    /* V8：veil 遮罩（抽屉打开时压暗原生正文层；点击关闭）*/
    SH.veilEl = el('div', 'veil');
    SH.veilEl.setAttribute('aria-hidden', 'true');
    SH.veilEl.addEventListener('click', function () { try { switchView('story'); } catch (e) {} });
    root.appendChild(SH.veilEl);

    /* 面板视图宿主（V7 抽屉化：桌面右滑 / 手机底部滑出） */
    SH.viewsEl = el('div', 'views');
    try { buildPanels(SH.viewsEl); } catch (e) { logErr(e); }
    root.appendChild(SH.viewsEl);

    /* 浮层宿主（状态明细/图鉴详情/手机功能表等 sheet） */
    SH.overlayHost = el('div', 'overlay-host');
    root.appendChild(SH.overlayHost);

    SH.toastHost = el('div', 'ark-toasts');
    root.appendChild(SH.toastHost);
  }

  /* ── 桌面左 rail 导航装配（V9 恢复；与顶栏 tb-nav 共用 syncTopNav）── */
  function buildRail(railEl) {
    railEl.textContent = '';
    railEl.setAttribute('aria-label', '终端导航');
    for (var i = 0; i < NAV_ITEMS.length; i++) {
      (function (item) {
        var b = el('button', 'nv-btn' + (item.id === SH.view ? ' on' : ''));
        b.type = 'button';
        b.setAttribute('data-nav', item.id);
        b.setAttribute('aria-label', item.label);
        b.appendChild(el('i', 'nv-ico', item.ico));
        b.appendChild(el('span', 'nv-label', item.label));
        b.addEventListener('click', function () { try { switchView(item.id); } catch (e) { logErr(e); } });
        railEl.appendChild(b);
      })(NAV_ITEMS[i]);
    }
  }

