   *     切角/扫描线顶缘光线/FLOOR 编号/箭头按钮/表单/滚动条）；
   *   · 原生 swipe 箭头（每楼左下 .swipe_left / 右下 swipeRightBlock
   *     内 .swipe_right + .swipes-counter 版本计数）仅重皮肤化，交互
   *     100% 走 ST 原生绑定：左箭头=上一版本、右箭头=下一版本、越过
   *     末版=重新生成新回复（OVERSWIPE REGENERATE）、历史楼层原生
   *     swipe-picker 查看/分支——壳不代答不拦截；
   *   · 楼层编号 FLOOR NN = 纯 CSS counter（.mes_block::before），
   *     零 DOM 注入 → updateMessageBlock / 流式打字 / 楼层编辑天然免疫；
   *   · 流式 = 原生打字指示（V7「闪烁」「冻结」两类问题同源消失，
   *     iframe 永不重建、图片永不重载）。
   * 退出对称：exitTakeover 移除 body 类 + restoreNative 禁用主题样式表，
   * 双保险恢复原生外观。 */

  function enterTakeover() {
    try {
      var b = HD().body;
      if (b && !b.classList.contains('ark-shell-on')) b.classList.add('ark-shell-on');
    } catch (e) { logErr(e); }
  }
  function exitTakeover() {
    try {
      var b = HD().body;
      if (b) b.classList.remove('ark-shell-on');
    } catch (e) {}
  }


  /* ═══════════════════════════════════════════════════════════════════
   * 模块 04c · V9 战术控制台：自绘输入栏 / 行动指令条 / 卡内前端过滤
   * ═══════════════════════════════════════════════════════════════════
   * 用户第八轮实测差评的三项根治：
   *   「你怎么又把聊天框做回酒馆原生界面的样子了！我不要酒馆原生输入框！」
   *   「仪表盘那一排按钮做的太小了；电脑端和之前一样放左边；手机另想办法」
   *   「在全屏前端里要单独过滤卡内原生的前端，只渲染外来的预设正则或
   *    全局正则的前端就好了」
   *
   * ① 战术控制台（#ark-input-slot 流内槽位）：
   *   · 原生 #form_sheld 由 THEME_CSS 整体隐藏（display:none —— DOM/
   *     jQuery 事件全保留，发送走 #send_but 点击触发、停止走 #mes_stop，
   *     与原生键盘行为同源；退出终端主题失效 → 原生输入区即刻回来）；
   *   · 自绘 = 单行 [战术灯标] + 自增高 textarea + 发送/停止双态大按钮
   *     （V7 全息玻璃版验证过的对账链：nt.value 赋值 → input 事件 →
   *     #send_but 触发；IME 合成期不误发；触屏 Enter=换行）；
   *   · 无 ◀▶↻ 楼层按钮 —— 楼层级切换/重生成由原生 swipe 箭头承担
   *     （用户第七轮钦定，模块 04b 保留）。
   * ② 行动指令条（#ark-ab-slot，V8 废除 V9 复活）：
   *   · 卡内「行动选项面板」正则产物被过滤后，壳内行动选项的唯一入口；
   *   · 最新 AI 楼 CONTEXT_options → 三枚全文按钮（点击=填入控制台，
   *     不自动发送）+ ARK_EVENT 增量 chips；窄屏折叠条（38px）。
   * ③ 卡内前端过滤（body.ark-shell-on 期间仅）：
   *   · 卡内 6 条显示正则的产物（创建器/HUD/事件挂件/Boss/图鉴/选项
   *     面板）在壳内与壳组件重复 → 识别 = iframe srcdoc 含卡内自然标记
   *     （ARK_CORE / ark-payload / ark-evt / ark-boss / ark-opt / akRoot /
   *     dwrap），命中给 TH 包裹元素加 .ark-card-off 类，THEME_CSS 隐藏；
   *   · 不改卡、不改正则、不动楼层原文 —— 退出壳清类即完整恢复原生；
   *   · 外来正则（预设/全局/未来任何来源）产物不含标记 → 原样呈现。
   * ═══════════════════════════════════════════════════════════════════ */

  /* ── 原生输入通道（隐藏的原生表单仍在 DOM 中） ─────────────────── */
  function nativeTa() {
    try {
      var form = liveNode('form_sheld');
      var ta = form ? form.querySelector('#send_textarea') : null;
      if (ta) return ta;
    } catch (e) {}
    return liveNode('send_textarea');
  }

  /* ── 控制台：自增高 / 发送 / 停止 ──────────────────────────────── */
  function autoGrowTa() {
    var ta = SH.inputTa;
    if (!ta) return;
    try {
      ta.style.height = 'auto';
      ta.style.height = Math.min(150, ta.scrollHeight) + 'px';
    } catch (e) {}
  }

  /* ── 原生触发（V9 关键修复） ────────────────────────────────
   * 实测：页面可能同时存在两个 jQuery 实例（元素 expando ≠
   * window.jQuery 的 expando）—— jQuery('…').trigger('click')
   * 会对“另一个实例”触发 = 打空（V9 实测发送链路曾因此断裂）。
   * 正解：原生 .click()（任何实例绑定的处理器都响应原生事件）；
   * 目标节点过滤掉 jQuery UI 弹层/页签面板里的同名克隆（文档序
   * 在前的 #ui-id-* 隐藏副本）。 */
  function isClonedNode(n) {
    try {
      if (!n || !n.closest) return false;
      var p = n.closest('.ui-dialog');
      if (p) return true;
      var t = n.closest('.ui-tabs-panel');   // #ui-id-* 页签面板内的同名表单副本
      if (t && /^ui-id-/.test(t.id || '')) return true;
    } catch (e) {}
    return false;
  }
  function triggerNative(sel) {
    try {
      var d = HD();
      var nodes = d.querySelectorAll(sel);
      var live = null;
      for (var i = 0; i < nodes.length; i++) {
        if (isClonedNode(nodes[i])) continue;
        live = nodes[i]; break;
      }
      if (!live && nodes.length) live = nodes[nodes.length - 1];
      if (live) { live.click(); return true; }
    } catch (e) {}
    try {
      var jq = H().jQuery;
      if (jq && jq(sel).length) { jq(sel).trigger('click'); return true; }
    } catch (e) {}
    return false;
  }

  function stopGeneration() {
    if (triggerNative('#mes_stop')) return;
    try { if (typeof triggerSlash === 'function') { triggerSlash('/stop'); return; } } catch (e) {}
    toast('停止按钮不可用', 'warning');
  }

  function sendCommand() {
    if (SH.genActive) { stopGeneration(); return; }         // 生成中：发送钮=停止
    var ta = SH.inputTa;
    if (!ta) return;
    var txt = trimS(ta.value);
    if (!txt) { toast('请输入生存指令', 'warning'); try { ta.focus(); } catch (e) {} return; }
    /* ST 的 sendTextareaMessage 读文档序第一个 #send_textarea（可能是
     * #ui-id-* 页签面板副本）——写入全部同名 textarea 保证任一实现都
     * 能读到；触发用原生 click 打真身 #send_but。 */
    var written = false;
    try {
      var d = HD();
      var tas = d.querySelectorAll('#send_textarea');
      for (var i = 0; i < tas.length; i++) {
        tas[i].value = txt;
        try { tas[i].dispatchEvent(new Event('input', { bubbles: true })); } catch (e0) {}
        written = true;
      }
    } catch (e) {}
    if (!written) {
      var nt = nativeTa();
      if (!nt) { toast('未找到酒馆输入通道', 'error'); return; }
      try { nt.value = txt; try { nt.dispatchEvent(new Event('input', { bubbles: true })); } catch (e0) {} } catch (e) {}
    }
    if (!triggerNative('#send_but')) { toast('酒馆发送按钮不可用', 'error'); return; }
    try { ta.value = ''; autoGrowTa(); } catch (e1) {}
  }

  function syncInputState() {
    if (!SH.inputSend) return;
    var gen = !!(SH.busy || SH.genActive);
    SH.inputSend.textContent = gen ? '停 止' : '发 送';
    SH.inputSend.classList.toggle('stop', gen);
    SH.inputSend.setAttribute('aria-label', gen ? '停止生成' : '发送指令');
    var lamp = SH.rootEl ? SH.rootEl.querySelector('.ip-lamp') : null;
    if (lamp) lamp.classList.toggle('gen', gen);
  }

  /* ── 控制台装配（#ark-input-slot 槽位内） ──────────────────────── */
  function buildConsole() {
    var slot = HD().getElementById('ark-input-slot');
    if (!slot) return;
    slot.textContent = '';
    var bar = el('div', 'ip-bar');

    var row = el('div', 'ip-row');
    /* 战术灯标（纯装饰：状态灯 + 微缩铭牌；生成中红闪） */
    var brand = el('div', 'ip-brandcol');
    brand.appendChild(el('i', 'ip-lamp'));
    brand.appendChild(el('span', 'ip-tag', 'TACTICAL'));
    row.appendChild(brand);

    var ta = el('textarea', 'ip-ta');
    ta.rows = 1;
    ta.setAttribute('placeholder', '输入生存指令…');
    ta.setAttribute('aria-label', '生存指令输入框');
    ta.addEventListener('input', autoGrowTa);
    var coarse = false;
    try { coarse = !!(H().matchMedia && H().matchMedia('(pointer: coarse)').matches); } catch (e) {}
    ta.addEventListener('keydown', function (ev) {
      if (ev.key !== 'Enter' || ev.shiftKey || ev.isComposing) return;
      if (coarse) return;                       // 触屏：Enter=换行，发送走按钮
      ev.preventDefault();
      sendCommand();
    });
    row.appendChild(ta);

    var send = el('button', 'ip-send');
    send.type = 'button';
    send.textContent = '发 送';
    send.setAttribute('aria-label', '发送指令');
    send.addEventListener('click', function () { sendCommand(); });
    row.appendChild(send);

    var hint = el('div', 'ip-hint');
    hint.appendChild(el('span', null, coarse ? '输入指令后点「发送」 · 楼层箭头可切换/重生成回复' : 'Enter 发送 · Shift+Enter 换行 · 楼层箭头可切换/重生成回复'));
    hint.appendChild(el('span', 'ip-hint-brand', 'ARK SURVIVOR TERMINAL'));

    bar.appendChild(row);
    bar.appendChild(hint);
    slot.appendChild(bar);
    SH.inputBar = bar;
    SH.inputTa = ta;
    SH.inputSend = send;
    syncInputState();
    autoGrowTa();
  }

  /* ── 行动选项/面板按钮 → 填入控制台 + 聚焦（不自动发送） ────────── */
  function setInput(text) {
    var ta = SH.inputTa || nativeTa();
    if (!ta) { toast('输入区不可用', 'warning'); return; }
    try {
      ta.value = String(text == null ? '' : text);
      ta.focus();
      var n = ta.value.length;
      try { ta.setSelectionRange(n, n); } catch (e) {}
      try { ta.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {}
      try {
        ta.classList.remove('ark-pulse');
        void ta.offsetWidth;                  // 重启动画
        ta.classList.add('ark-pulse');
      } catch (e) {}
      if (ta === SH.inputTa) autoGrowTa();      // 自增高同步
    } catch (e) { logErr(e); }
    try { switchView('story'); } catch (e) {}  // 从抽屉点击时回到正文
  }

  /* ── 行动指令条（V7 全文纪律移植；V8 废除 V9 复活） ─────────────── */
  function parseOptions(text) {
    var opts = [];
    var lines = String(text || '').split(/\r?\n/);
    for (var i = 0; i < lines.length; i++) {
      var ln = trimS(lines[i]);
      if (!ln) continue;
      var m = ln.match(/^([^:：]{1,8})[:：]\s*(.+)$/);
      if (m && /行动$/.test(trimS(m[1]))) {
        opts.push({ label: trimS(m[1]), text: trimS(m[2]) });
      } else {
        opts.push({ label: '', text: ln });    // 容错：无前缀行也当选项
      }
    }
    return opts;
  }
  function parseEvents(text) {
    var evts = [];
    var line = String(text || '');
    line = line.replace(/驯服开始\s*[|｜]\s*([^|｜;；]+?)\s*[|｜]\s*(?:[Ll][Vv]\.?\s*|等级\s*)?(\d+)\s*[|｜]\s*(击晕|被动)/g,
      function (all, sp, lv, md) {
        evts.push({ kind: 'tamestart', species: trimS(sp), level: parseInt(lv, 10) || 1, mode: md, text: '驯服开始 ' + trimS(sp) + ' Lv.' + (parseInt(lv, 10) || 1) + ' ' + md });
        return ' ';
      });
    var parts = line.split(/[｜|;；\n]/);
    for (var i = 0; i < parts.length; i++) {
      var seg = String(parts[i]).replace(/＋/g, '+').replace(/－/g, '-').replace(/[ｘ＊]/g, 'x').replace(/\s+/g, '');
      if (!seg) continue;
      var e = { kind: 'other', text: seg, neg: false };
      var m;
      if ((m = seg.match(/^经验([+\-])([\d.]+)/))) { e.kind = 'exp'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^生物经验([+\-])(\d+)[·,，:：](.+)$/))) { e.kind = 'dinoexp'; e.num = m[2]; e.name = m[3]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^生物经验[·,，:：](.+?)([+\-])(\d+)$/))) { e.kind = 'dinoexp'; e.name = m[1]; e.num = m[3]; e.neg = m[2] === '-'; }
      else if ((m = seg.match(/^物品([+\-])(\d+)[×xX*](.+)$/))) { e.kind = 'item'; e.name = m[3]; e.num = m[2]; e.sign = m[1]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^物品([+\-])(.+?)(?:[×xX*](\d+))?$/))) { e.kind = 'item'; e.name = trimS(m[2]); e.num = m[3] != null ? m[3] : '1'; e.sign = m[1]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^麻醉([+\-])(\d+)/))) { e.kind = 'narc'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^驯服([+\-])(\d+)/))) { e.kind = 'tame'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^状态([+\-])(.+)$/))) { e.kind = 'status'; e.name = m[2]; e.sign = m[1]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^属性点([+\-])(\d+)/))) { e.kind = 'statpt'; e.num = m[2]; e.neg = m[1] === '-'; }
      else if ((m = seg.match(/^印痕点([+\-])(\d+)/))) { e.kind = 'engpt'; e.num = m[2]; e.neg = m[1] === '-'; }
      evts.push(e);
    }
    return evts;
  }
  function latestAiFloor() {
    var fs = ensureFloors();
    for (var i = fs.length - 1; i >= 0; i--) if (!fs[i].isUser) return fs[i];
    return null;
  }

  function buildActionBar() {
    if (!SH.actionBar) return;
    var ai = latestAiFloor();
    var opts = (ai && ai.blocks && ai.blocks.options) ? parseOptions(ai.blocks.options) : [];
    var evts = [];
    try { evts = (ai && ai.blocks && ai.blocks.event) ? parseEvents(ai.blocks.event) : []; } catch (e0) {}
    if (!opts.length && !evts.length) { SH.actionBar.setAttribute('hidden', ''); SH.actionBar.textContent = ''; return; }
    SH.actionBar.textContent = '';
    SH.actionBar.removeAttribute('hidden');

    // 新楼到达 → 折叠态复位（用户看过上一轮选项后自然收起）
    var fid = ai && ai.id != null ? ai.id : -1;
    if (fid !== SH.abFloorId) { SH.abFloorId = fid; SH.abOpen = false; }

    var wrap = el('div', 'ab-wrap');

    // 事件 chips：最新楼增量（经验/物品/状态/驯服…；原卡事件挂件的壳内替代）
    if (evts.length) {
      var evrow = el('div', 'ab-events');
      for (var k = 0; k < evts.length && k < 8; k++) {
        (function (ev) {
          var c = el('span', 'ab-ev' + (ev.neg ? ' neg' : '') + (ev.kind ? ' k-' + ev.kind : ''));
          c.textContent = String(ev.text || '');
          evrow.appendChild(c);
        })(evts[k]);
      }
      wrap.appendChild(evrow);
    }

    // 选项（无选项时仅事件行）
    if (opts.length) {
      var toggle = el('button', 'ab-toggle');
      toggle.type = 'button';
      toggle.setAttribute('aria-expanded', SH.abOpen ? 'true' : 'false');
      toggle.appendChild(el('i', 'ab-tg-ico', '◈'));
      toggle.appendChild(el('span', 'ab-tg-title', '行动指令 · ' + opts.length + ' 项'));
      var caret = el('span', 'ab-caret', '⌄');
      toggle.appendChild(caret);
      toggle.addEventListener('click', function () {
        SH.abOpen = !SH.abOpen;
        applyAbState();
      });
      wrap.appendChild(toggle);

      var list = el('div', 'ab-list');
      var KINDS = [{ k: '稳妥行动', cls: 'safe', ico: '🛡' }, { k: '进取行动', cls: 'bold', ico: '⚔' }, { k: '探索行动', cls: 'scout', ico: '🧭' }];
      for (var i = 0; i < opts.length && i < 6; i++) {
        (function (o, idx) {
          var kind = KINDS[idx] || { k: '▸ 行动', cls: 'scout', ico: '▸' };
          var b = el('button', 'ab-opt ' + kind.cls);
          b.type = 'button';
          b.appendChild(el('i', 'ab-opt-ico', kind.ico));
          b.appendChild(el('b', 'ab-opt-k', (o.label || kind.k).replace(/行动$/, '')));
          var txt = el('span', 'ab-opt-t', o.text);      // 全文渲染，永不省略
          b.appendChild(txt);
          if (o.label) b.title = o.label + '：' + o.text;
          b.addEventListener('click', function () { setInput(o.text); });  // 填入+聚焦，不发送
          list.appendChild(b);
        })(opts[i], i);
      }
      wrap.appendChild(list);
    }
    SH.actionBar.appendChild(wrap);

    function applyAbState() {
      SH.actionBar.setAttribute('data-open', SH.abOpen ? '1' : '0');
      if (caret) caret.textContent = SH.abOpen ? '⌃' : '⌄';
      if (toggle) toggle.setAttribute('aria-expanded', SH.abOpen ? 'true' : 'false');
    }
    applyAbState();
  }

  /* ── 卡内前端过滤（仅 body.ark-shell-on 期间；退出即恢复） ────────
   * 识别 = TH 渲染 iframe 的 srcdoc 含卡内自然标记（6 条显示正则产物
   * 的稳定子串；外部正则产物不含）。标记命中 → TH 包裹元素加
   * .ark-card-off 类 → THEME_CSS（body.ark-shell-on 作用域）隐藏。
   * TH 惰性渲染：滚动进视口才建 iframe → MO + scroll rAF 双通道捕捉。 */
  var CARD_UI_MARKERS = ['ARK_CORE', 'ark-payload', 'ark-evt', 'ark-boss', 'ark-opt', 'akRoot', 'dwrap'];
  var cardObs = null;
  var cardSweepScheduled = false;

  function isCardUiFrame(fr) {
    try {
      var sd = fr.getAttribute && (fr.getAttribute('srcdoc') || fr.getAttribute('data-srcdoc'));
      if (!sd) return false;
      for (var i = 0; i < CARD_UI_MARKERS.length; i++) {
        if (sd.indexOf(CARD_UI_MARKERS[i]) >= 0) return true;
      }
    } catch (e) {}
    return false;
  }

  /* TH 包裹元素探测（V7 findThWrap 加固版：绝不允许标记到
   * .mes_text/.mes 整楼 —— 那会把正文一起藏掉；找不到 TH 包裹就只标记
   * iframe 自身）。 */
  function cardUiHost(fr) {
    var w = fr;
    try {
      var chat = liveNode('chat');
      var lim = chat || HD().body;
      while (w && w.parentElement && w.parentElement !== lim) {
        var p = w.parentElement;
        var cls = ' ' + (p.className || '') + ' ';
        if (cls.indexOf(' TH-') >= 0 || cls.indexOf('mes_renderer') >= 0) return p;
        w = p;
      }
    } catch (e) {}
    return fr;   // 兜底：只藏 iframe 自身
  }

  function sweepCardUi() {
    if (!SH.mounted) return;
    var chat = liveNode('chat');
    if (!chat) return;
    /* ① TH 渲染 iframe（HTML 代码块产物） */
    var frames = chat.querySelectorAll('.mes .mes_text iframe');
    for (var i = 0; i < frames.length; i++) {
      var fr = frames[i];
      if (!isCardUiFrame(fr)) continue;
      var host = cardUiHost(fr);
      if (host && host.classList && !host.classList.contains('ark-card-off')) host.classList.add('ark-card-off');
      if (fr !== host && fr.classList && !fr.classList.contains('ark-card-off')) fr.classList.add('ark-card-off');
    }
    /* ② TH 渲染关闭的兜底：```html 围栏残留的 pre>code 文本块 */
    try {
      var pres = chat.querySelectorAll('.mes .mes_text pre code');
      for (var j = 0; j < pres.length; j++) {
        var code = pres[j];
        var txt = code.textContent || '';
        if (txt.length < 40) continue;
        var hit = false;
        for (var m = 0; m < CARD_UI_MARKERS.length; m++) {
          if (txt.indexOf(CARD_UI_MARKERS[m]) >= 0) { hit = true; break; }
        }
        if (hit) {
          var pre = code.closest ? code.closest('pre') : (code.parentElement || code);
          if (pre && pre.classList && !pre.classList.contains('ark-card-off')) pre.classList.add('ark-card-off');
        }
      }
    } catch (e) {}
  }

