  function applyThemeAll(name, silent) {
    var found = null;
    for (var i = 0; i < ARK_THEMES.length; i++) {
      if (ARK_THEMES[i].id === name) { found = ARK_THEMES[i]; break; }
    }
    if (!found) { name = 'island'; found = { id: 'island', label: '孤岛青' }; }
    SH.theme = name;
    lsSet('theme', name);
    try { if (SH.rootEl) SH.rootEl.setAttribute('data-theme', name); } catch (e) {}
    try { HD().documentElement.setAttribute('data-ark-theme', name); } catch (e) {}
    if (!silent) toast('终端配色：' + found.label, 'info');
  }
  function cycleTheme() {
    var cur = lsGet('theme', 'island'), idx = 0;
    for (var i = 0; i < ARK_THEMES.length; i++) if (ARK_THEMES[i].id === cur) { idx = i; break; }
    var next = ARK_THEMES[(idx + 1) % ARK_THEMES.length];
    applyThemeAll(next.id, false);
  }

