  /* ── 状态刷新（CORE 优先，楼层兜底；不重复实现任何公式）──────── */
  var refreshStatusInner = debounce(function () {
    if (!SH.mounted || !SH.topbar) return;
    var snap = hudSnapshot();
    var st = statOf();
    var f = snap ? snap.fields : null;
    var m = f ? f.map : {};

    var g = function (id) { return SH.topbar.querySelector('#' + id); };

    var loc = g('tb-loc'), time = g('tb-time'), wx = g('tb-wx');
    var stLoc = st ? ((st['世界_领土势力'] || {})['当前地点'] || '') : '';
    var stTime = st ? ((st['世界_领土势力'] || {})['当前时间'] || '') : '';
    if (loc)  loc.textContent  = '📍 ' + (m['地点'] || m['位置'] || stLoc || '…');
    if (time) time.textContent = '🕐 ' + (m['时间'] || stTime || '…');
    if (wx) {
      var wxv = m['天气'];
      wx.textContent = wxv ? ('🌤 ' + wxv) : '';
      if (wxv) wx.removeAttribute('hidden'); else wx.setAttribute('hidden', '');
    }

    // 五维生命条
    for (var i = 0; i < VITAL_KEYS.length; i++) {
      var v = VITAL_KEYS[i];
      var raw = m[v.key] || '';
      var mm = String(raw).match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)/);
      var fill = g('vt-fill-' + v.key), num = g('vt-num-' + v.key);
      if (mm) {
        if (fill) fill.style.width = clamp(pct(mm[1], mm[2]), 0, 100) + '%';
        if (num) num.textContent = Math.round(Number(mm[1]));
        if (fill) fill.setAttribute('data-low', pct(mm[1], mm[2]) <= 25 ? '1' : '0');
      } else {
        if (fill) fill.style.width = '0%';
        if (num) num.textContent = '—';
      }
    }

    // 负重 / 等级经验
    var wt = g('tb-wt');
    if (wt) wt.textContent = '负重 ' + (m['负重状态'] || '—');
    var lvNum = g('tb-lv-num'), lvFill = g('tb-lv-fill');
    var li = levelInfo();
    if (li && lvNum) {
      lvNum.textContent = 'Lv.' + (li.level != null ? li.level : '—');
      if (lvFill) lvFill.style.width = clamp(pct(li.exp, li.expMax), 0, 100) + '%';
    } else if (lvNum) {
      lvNum.textContent = 'Lv.—';
      if (lvFill) lvFill.style.width = '0%';
    }

    // 威胁徽章
    var th = g('tb-threat');
    if (th) {
      var tv = m['威胁'];
      var danger = tv && tv !== '无' && trimS(tv) !== '';
      th.textContent = danger ? ('⚠ ' + tv) : '';
      th.className = 'tb-threat' + (danger ? ' on' : '');
      th.setAttribute('hidden', danger ? null : '');
    }

    // 只读警示（V4.2：warn 常驻 DOM，仅切 hidden）
    var warn = g('tb-warn');
    if (warn) {
      if (SH.coreReady) warn.setAttribute('hidden', '');
      else warn.removeAttribute('hidden');
    }

    // 生成指示
    var gen = g('tb-gen');
    if (gen) { if (SH.busy || SH.genActive) gen.removeAttribute('hidden'); else gen.setAttribute('hidden', ''); }

  }, 120);

  function refreshStatus() { refreshStatusInner(); }

  /* ── 手机端状态明细展开（浮层 sheet）─────────────────────────── */
  function openStatusSheet() {
    if (!SH.overlayHost || !SH.rootEl) return;
    var snap = hudSnapshot();
    var st = statOf();
    var m = snap ? snap.fields.map : {};
    var li = levelInfo();

    var sheet = el('div', 'status-sheet');
    var box = el('div', 'ss-box');
    var head = el('header', 'ss-head');
    head.appendChild(el('h3', null, '🧭 生存指标'));
    var x = el('button', 'ss-x');
    x.type = 'button'; x.textContent = '✕'; x.setAttribute('aria-label', '关闭');
    head.appendChild(x);
    box.appendChild(head);

    var grid = el('div', 'ss-grid');
    function addRow(k, v, cls) {
      if (v == null || trimS(String(v)) === '') return;
      var r = el('div', 'ss-row' + (cls ? ' ' + cls : ''));
      r.appendChild(el('span', 'ss-k', k));
      r.appendChild(el('b', 'ss-v', v));
      grid.appendChild(r);
    }
    for (var i = 0; i < VITAL_KEYS.length; i++) addRow(VITAL_KEYS[i].label, m[VITAL_KEYS[i].key]);
    addRow('体温', m['体温']);
    addRow('负重', m['负重状态']);
    addRow('状态效果', m['状态效果']);
    addRow('时间', m['时间']);
    addRow('天气', m['天气']);
    addRow('地点', m['地点'] || m['位置']);
    addRow('装备', m['装备']);
    addRow('恐龙', m['恐龙']);
    addRow('骑乘', m['骑乘']);
    addRow('威胁', m['威胁'], m['威胁'] && m['威胁'] !== '无' ? 'danger' : '');
    if (li) addRow('等级', 'Lv.' + li.level + ' · 经验 ' + (li.exp || 0) + '/' + (li.expMax || 0));
    if (li && (li.statPts || li.engPts)) addRow('可分配', '属性点 ' + (li.statPts || 0) + ' · 印痕点 ' + (li.engPts || 0));
    if (st) {
      var su = st['主角_生存状态'] || {};
      if (su['姓名']) addRow('生存者', su['姓名'] + (su['身份'] ? ' · ' + su['身份'] : ''));
    }
    if (!grid.childNodes.length) grid.appendChild(el('div', 'ss-row', '尚无数据——等待开局'));
    box.appendChild(grid);
    sheet.appendChild(box);

    var close = pushOverlay(sheet, { sheet: true });
    x.addEventListener('click', function () { close(); });
    sheet.addEventListener('click', function (ev) { if (ev.target === sheet) close(); });
  }

  /* ── 引擎/MVU 订阅：状态变化 → 防抖刷新（只读）───────────────── */
  function subscribeEngine() {
    if (SH.coreSubscribed || !SH.coreReady) return;
    SH.coreSubscribed = true;
    try {
      H().ARK_CORE.on(function () {         // 引擎广播（防抖 200ms 后派发）
        if (!SH.mounted) return;
        refreshStatusInner();
      });
    } catch (e) { logErr(e); }
    // MVU 变量更新完成 → 刷新（事件常量必须用 Mvu.events 枚举，防拼写 bug）
    try {
      if (typeof waitGlobalInitialized === 'function') {
        waitGlobalInitialized('Mvu').then(function (Mvu) {
          if (Mvu && Mvu.events && typeof eventOn === 'function') {
            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function () {
              if (!SH.mounted) return;
              refreshStatusInner();
              try { panelRefresh(); } catch (e) {}
            });
          }
        }).catch(function () {});
      }
    } catch (e) {}
  }


