  /* ── 仪表盘：卡内 HUD 正则模板 → srcdoc 嵌入 ─────────────────── */

  /* V5.2 修复①：剥离卡内 HUD 模板尾部的 TH 自动高度脚本部件。
   * 死循环机制：MO(观察 body 属性) → rAF(r) → r() 写 body.style
   * → 触发 MO → …… 60fps 永续强制布局。两处 split().join() 中性化：
   *   · 观察器回调改空函数（循环断路）
   *   · 内联高度写入改恒等（防覆盖 CSS 定高）
   * 标记未命中（模板已变）时为恒等操作，优雅退化。 */
  function stripAutoHeight(html) {
    var a = html.split('new MutationObserver(()=>requestAnimationFrame(r))')
               .join('new MutationObserver(()=>{})');
    var b = a.split('f.style.height=sh+"px"')
             .join('0&&(f.style.height=sh+"px")');
    return b;
  }

  function getHudTemplate() {
    if (SH.hudTpl !== undefined) return SH.hudTpl;
    SH.hudTpl = null;
    try {
      if (typeof RawCharacter === 'undefined' || !RawCharacter.find) return null;
      var raw = RawCharacter.find({ name: 'current' });
      if (!raw) return null;
      var rc = new RawCharacter(raw);
      var scripts = rc.getRegexScripts() || [];
      for (var i = 0; i < scripts.length; i++) {
        var s = scripts[i];
        /* V4.2：不检查 disabled —— 卡内 5 条重型显示正则已默认停用（让位用户
         * 全局正则前端），但 HUD 模板仍需从此处读取供仪表盘嵌入 */
        if (s && s.scriptName && s.scriptName.indexOf('显示方舟游戏主界面') >= 0 &&
            s.replaceString && s.replaceString.indexOf('$1') >= 0) {
          SH.hudTpl = s.replaceString;
          break;
        }
      }
    } catch (e) { logErr(e); SH.hudTpl = null; }
    return SH.hudTpl;
  }
  /* 剥 ```html 代码围栏 → 完整 HTML 文档 */
  function stripFence(tpl) {
    var t = String(tpl || '');
    var a = t.indexOf('```html');
    if (a >= 0) {
      var lb = t.indexOf('\n', a);
      var b = t.lastIndexOf('```');
      if (lb >= 0 && b > lb) return t.slice(lb + 1, b);
    }
    return t;
  }
  var scheduleDashRefresh = debounce(function () { renderDashboard(); }, 700);

  function renderDashboard() {
    var body = panelBody('dash');
    if (!body) return;
    if (SH.genActive && SH.dashIframe) return;   /* 修复③：生成中零重建 */
    var tpl = getHudTemplate();
    var payload = '';
    if (SH.coreReady) {
      try { payload = String(H().ARK_CORE.hud.payload() || ''); } catch (e) { payload = ''; }
    }
    if (!payload) {
      var ai = latestAiFloor();
      if (ai && ai.blocks && ai.blocks.hud) payload = trimS(ai.blocks.hud);
    }
    /* 修复②：载荷签名守卫——模板/载荷未变且 iframe 健在时零重建 */
    var sig = (tpl ? tpl.length : 0) + '|' + payload.length + '|' + payload.slice(-96);
    if (SH.dashIframe && SH.dashSig === sig &&
        SH.dashIframe.parentNode && SH.dashIframe.isConnected) return;
    SH.dashSig = sig;
    SH.dashIframe = null;
    body.textContent = '';

    if (!tpl) {
      body.appendChild(placeholder('🛠️', 'HUD 模板不可用',
        '未能从角色卡正则中读取「🖥️显示方舟游戏主界面」模板。请确认已导入本卡自带的角色正则并允许其运行。'));
      return;
    }
    if (!payload) {
      body.appendChild(placeholder('🌅', '等待开局后可用',
        '开局指令发送后，AI 将在每轮输出 ARK_HUD_DATA 状态载荷，仪表盘即可点亮。'));
      return;
    }

    // $1 载荷注入：split().join() 防 $ 转义（严禁 String.replace 裸替换）
    // 随后剥离 TH 自动高度自激循环（V5.2 修复①）
    var html = stripAutoHeight(stripFence(tpl).split('$1').join(payload));
    var wrap = el('div', 'dash-host');
    var ifr = HD().createElement('iframe');
    ifr.className = 'dash-iframe';
    ifr.setAttribute('title', '方舟游戏主界面（HUD）');
    ifr.setAttribute('loading', 'eager');
    ifr.setAttribute('referrerpolicy', 'no-referrer');
    ifr.srcdoc = html;                      // 与宿主同源 → window.parent.ARK_CORE 直连引擎
    wrap.appendChild(ifr);
    body.appendChild(wrap);
    SH.dashIframe = ifr;
  }

