    return d;
  }

  /* ── 图鉴：原生网格 + 详情浮层 ───────────────────────────────── */
  var DIET_CLS = { '草食': 'diet-herb', '植食': 'diet-herb', '肉食': 'diet-carn', '杂食': 'diet-omni', '食草': 'diet-herb', '食肉': 'diet-carn' };
  function renderDossier() {
