      body.appendChild(placeholder('🥚', '图鉴尚未开启', '首次遭遇生物后，这里会登记生存者图鉴。'));
      return;
    }
    var grid = el('div', 'ds-grid');
    names.sort(function (a, b) { return a.localeCompare(b, 'zh'); });
    for (var i = 0; i < names.length; i++) {
      (function (nm) {
        var e = entries[nm] || {};
        var card = el('button', 'ds-card');
        card.type = 'button';
        var img = el('img', 'ds-card-img');
        img.alt = nm;
        img.loading = 'lazy';
        img.decoding = 'async';
