  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:var(--amberL);
  filter:drop-shadow(0 2px 4px rgba(0,0,0,.6)) drop-shadow(0 0 22px rgba(232,163,61,.25))}
.hm-sub{font-family:var(--mono);font-size:11px;letter-spacing:.34em;color:var(--teal);margin:6px 0 2px;opacity:.85}
.hm-sub2{font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--ink3);margin-bottom:14px}
.hm-feat{margin:10px auto 0;max-width:520px;font-size:11.5px;letter-spacing:.06em;line-height:1.7;color:var(--ink3);border:1px dashed rgba(232,163,61,.28);border-radius:6px;padding:7px 14px;background:rgba(232,163,61,.05)}
.hm-badges{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:0 0 14px}
.hm-save{max-width:520px;margin:0 auto 10px;text-align:left;padding:11px 14px;border-radius:8px;
  border:1px solid var(--bd);border-left:3px solid var(--amber);background:rgba(232,163,61,.06);font-size:13px;color:var(--ink2)}
.hm-save b{color:var(--amberL);font-weight:600}
.hm-draft{max-width:520px;margin:0 auto 14px;text-align:left;padding:10px 14px;border-radius:8px;
  border:1px dashed var(--tbd);background:rgba(62,198,200,.05);font-size:13px;color:var(--ink2);
  display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.hm-draft .btn{min-height:44px;padding:8px 14px;font-size:12.5px}
.hm-start{min-height:56px;padding:13px 42px;font-size:17px;letter-spacing:.5em;text-indent:.5em;font-family:var(--serif);font-weight:700;
  background:linear-gradient(180deg,#f6c877,#e8a33d 55%,#c47f22);color:#241505;border-radius:8px;
  box-shadow:0 0 0 1px rgba(255,220,160,.4) inset,0 6px 20px rgba(0,0,0,.45),0 0 28px rgba(232,163,61,.22)}
.hm-start:hover{background:linear-gradient(180deg,#ffd98c,#f0b453 55%,#d99430);box-shadow:0 0 0 1px rgba(255,230,180,.55) inset,0 8px 24px rgba(0,0,0,.5),0 0 44px rgba(232,163,61,.4);transform:translateY(-1px)}
.howto{max-width:620px;margin:18px auto 0;text-align:left;border:1px solid var(--lineS);border-radius:10px;background:var(--panel2)}
.howto summary{list-style:none;min-height:48px;display:flex;align-items:center;gap:8px;padding:10px 16px;cursor:pointer;
  color:var(--amberL);letter-spacing:.14em;font-size:14px}
.howto summary::-webkit-details-marker{display:none}
.howto summary::after{content:'▾';margin-left:auto;color:var(--ink3);transition:transform .2s}
.howto[open] summary::after{transform:rotate(180deg)}
.howto .hw-bd{padding:2px 18px 14px;border-top:1px solid var(--lineS)}
.howto ol{list-style:none;margin:0;padding:0}
.howto li{position:relative;padding:7px 0 7px 26px;font-size:13px;color:var(--ink2);border-bottom:1px dashed var(--lineS)}
.howto li:last-child{border-bottom:0}
.howto li::before{content:attr(data-n);position:absolute;left:0;top:9px;font-family:var(--mono);font-size:11px;color:var(--amber);border:1px solid var(--bd);border-radius:3px;padding:0 5px;line-height:1.5}
.howto b{color:var(--ink);font-weight:600}
.howto .k{color:var(--teal);font-family:var(--mono);font-size:12px}
.hm-foot{margin-top:14px;font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--ink3)}

/* ═══ STEP1 世界地图网格 ═══ */
.mk-filter{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 14px}
.fchip{min-height:44px;padding:8px 16px;border-radius:99px;border:1px solid var(--line);background:var(--panel2);
  color:var(--ink2);font-size:13px;letter-spacing:.1em;transition:all .2s}
.fchip:hover{border-color:var(--bd);color:var(--amberL)}
.fchip.on{border-color:var(--amber);color:#241505;background:linear-gradient(180deg,#f2b95c,#dd922e);font-weight:700;box-shadow:0 0 14px rgba(232,163,61,.3)}
.fchip:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.mk-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}
.mk{position:relative;display:flex;flex-direction:column;text-align:left;border:1px solid var(--line);border-radius:9px;
  background:var(--panel2);overflow:hidden;transition:border-color .2s,box-shadow .2s,transform .15s;min-height:44px}
.mk::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--dge,var(--teal));z-index:2}
.mk:hover{border-color:var(--bd);transform:translateY(-2px);box-shadow:0 8px 22px rgba(0,0,0,.4)}
.mk.sel{border-color:var(--amber);box-shadow:0 0 0 1px var(--amber),0 0 26px rgba(232,163,61,.28)}
.mk-imgwrap{display:block;position:relative;aspect-ratio:16/10;background:#06131a;overflow:hidden}
.mk-imgwrap img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .4s ease;opacity:.92}
.mk:hover .mk-imgwrap img{transform:scale(1.04)}
.mk-imgwrap::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(5,11,14,.05) 40%,rgba(5,11,14,.82));}
.mk-shade{position:absolute;inset:0;background:radial-gradient(120% 90% at 50% 20%,transparent 55%,rgba(5,11,14,.5))}
.mk-dg{position:absolute;top:8px;right:8px;z-index:3;font-family:var(--mono);font-size:10px;letter-spacing:.1em;
  padding:2px 8px;border-radius:3px;color:#04121a;background:var(--dge,var(--teal));font-weight:700;box-shadow:0 1px 6px rgba(0,0,0,.5)}
.mk-ck{position:absolute;top:8px;left:8px;z-index:3;width:24px;height:24px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;font-size:14px;color:#241505;
  background:linear-gradient(180deg,#ffd98c,#e8a33d);box-shadow:0 0 12px rgba(232,163,61,.6);opacity:0;transform:scale(.4);transition:all .22s}
.mk.sel .mk-ck{opacity:1;transform:scale(1)}
.mk-bd{padding:9px 11px 10px;display:flex;flex-direction:column;gap:3px}
.mk-name{font-size:15px;font-weight:700;color:var(--ink);letter-spacing:.06em;display:flex;align-items:baseline;gap:7px}
.mk-name .lv{font-family:var(--mono);font-size:10px;color:var(--teal);letter-spacing:.06em;font-weight:400}
.mk-sub{font-size:11.5px;color:var(--ink2);font-style:italic}
.mk-biome{font-size:11px;color:var(--ink3);line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.mk-fauna{font-size:11px;color:rgba(62,198,200,.75);line-height:1.5;overflow:hidden;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical}
.mk-note{margin:12px 0 0;font-size:12px;color:var(--ink3)}

/* ═══ STEP2 出生区域 ═══ */
.rg-wrap{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(240px,1fr);gap:16px;align-items:start}
.rg-map{position:relative;aspect-ratio:1/1;width:100%;border:1px solid var(--line);border-radius:10px;overflow:hidden;
  background:radial-gradient(90% 90% at 50% 40%,#0d2830,#06131a 75%);box-shadow:inset 0 0 40px rgba(0,0,0,.5)}
.rg-map img.rg-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(.92)}
.rg-grid{position:absolute;inset:0;pointer-events:none;z-index:2;
  background:repeating-linear-gradient(0deg,rgba(62,198,200,.05) 0 1px,transparent 1px 12.5%),
             repeating-linear-gradient(90deg,rgba(62,198,200,.05) 0 1px,transparent 1px 12.5%)}
.rg-frame{position:absolute;inset:6px;border:1px solid rgba(232,163,61,.28);border-radius:6px;pointer-events:none;z-index:2}
.rg-corner{position:absolute;z-index:2;width:14px;height:14px;pointer-events:none;border:1.5px solid rgba(232,163,61,.7)}
.rg-corner.c1{top:10px;left:10px;border-right:0;border-bottom:0}
.rg-corner.c2{top:10px;right:10px;border-left:0;border-bottom:0}
.rg-corner.c3{bottom:10px;left:10px;border-right:0;border-top:0}
.rg-corner.c4{bottom:10px;right:10px;border-left:0;border-top:0}
.rg-dot{position:absolute;width:44px;height:44px;margin:-22px 0 0 -22px;z-index:4;transform:translateZ(0)}
.rg-dot i{display:block;width:13px;height:13px;margin:15px auto;border-radius:50%;position:relative;
  background:var(--dc,#7ec96b);box-shadow:0 0 8px var(--dc,#7ec96b),0 0 2px rgba(0,0,0,.8);transition:transform .18s}
.rg-dot i::before,.rg-dot i::after{content:'';position:absolute;inset:-4px;border-radius:50%;border:1.5px solid var(--dc,#7ec96b);opacity:.8}
.rg-dot i::before{animation:dotPulse 2s ease-out infinite}
.rg-dot i::after{animation:dotPulse 2s ease-out 1s infinite}
@keyframes dotPulse{0%{transform:scale(.55);opacity:.9}75%{transform:scale(2.1);opacity:0}100%{transform:scale(2.1);opacity:0}}
.rg-dot:hover i{transform:scale(1.35)}
.rg-dot.sel i{width:17px;height:17px;margin:13px auto;box-shadow:0 0 14px var(--dc),0 0 3px #000,0 0 0 3px rgba(232,163,61,.55)}
.rg-dot.sel::after{content:'';position:absolute;inset:6px;border-radius:50%;border:1.5px dashed rgba(255,217,140,.85);animation:dotSpin 6s linear infinite}
@keyframes dotSpin{to{transform:rotate(360deg)}}
.rg-dot.d1,.rg-dot.d2{--dc:#7ec96b}
.rg-dot.d3{--dc:#e8a33d}
.rg-dot.d4,.rg-dot.d5{--dc:#e2604f}
.rg-dot:focus-visible{outline:2px solid var(--teal);outline-offset:-8px;border-radius:50%}
.rg-tip{position:absolute;z-index:6;max-width:210px;padding:8px 11px;border-radius:7px;pointer-events:none;
  background:rgba(6,17,22,.96);border:1px solid var(--bd);box-shadow:0 6px 20px rgba(0,0,0,.55);
  opacity:0;transform:translateY(4px);transition:opacity .15s,transform .15s}
.rg-tip.on{opacity:1;transform:none}
.rg-tip .tt-n{font-size:13px;font-weight:700;color:var(--amberL);display:flex;gap:7px;align-items:baseline}
.rg-tip .tt-s{font-size:10.5px;letter-spacing:.05em}
.rg-tip .tt-s .st{color:var(--ink3)} .rg-tip .tt-s .on{color:var(--dc)}
.rg-tip .tt-d{font-size:11.5px;color:var(--ink2);line-height:1.55;margin-top:2px}
.rg-legend{display:flex;gap:14px;flex-wrap:wrap;margin:10px 2px 0;font-size:11px;color:var(--ink3)}
.rg-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px;vertical-align:1px}
.rg-side h3{font-size:12px;letter-spacing:.2em;color:var(--ink2);margin:2px 0 8px;font-weight:600}
.rg-side h3::before{content:'▤ ';color:var(--amber)}
.rg-list{display:flex;flex-direction:column;gap:4px;max-height:230px;overflow-y:auto;padding-right:4px;margin-bottom:12px}
.rg-item{display:flex;align-items:center;gap:8px;width:100%;min-height:44px;padding:8px 12px;text-align:left;
  border:1px solid var(--lineS);border-radius:7px;background:var(--panel2);color:var(--ink2);font-size:13.5px;
  transition:all .18s;letter-spacing:.03em}
.rg-item .st{font-size:9.5px;letter-spacing:0;margin-left:auto;flex:0 0 auto}
.rg-item .st .on{color:var(--dc)}
.rg-item .st .off{color:#3a4f55}
.rg-item:hover{border-color:var(--bd);color:var(--ink)}
.rg-item.sel{border-color:var(--amber);color:var(--amberL);background:rgba(232,163,61,.1);box-shadow:0 0 12px rgba(232,163,61,.15)}
.rg-item:focus-visible{outline:2px solid var(--teal);outline-offset:-2px}
.rg-card{border:1px solid var(--bd);border-radius:10px;padding:13px 15px;background:linear-gradient(165deg,rgba(232,163,61,.08),rgba(10,24,28,.5))}
.rg-card .rc-h{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap}
.rg-card .rc-n{font-family:var(--serif);font-size:19px;color:var(--amberL);letter-spacing:1px}
.rg-card .rc-tag{font-family:var(--mono);font-size:10px;padding:2px 8px;border-radius:3px;color:#04121a;font-weight:700;letter-spacing:.1em}
.rg-card .rc-st{font-size:12px;letter-spacing:.2em;margin:3px 0 5px}
.rg-card .rc-st .on{color:var(--dc)} .rg-card .rc-st .off{color:#3a4f55}
.rg-card .rc-d{font-size:13px;color:var(--ink2);line-height:1.7}
.rg-card .rc-tip{margin-top:8px;padding-top:8px;border-top:1px dashed var(--lineS);font-size:12px;color:var(--teal);opacity:.9}

/* ═══ STEP3 档案表单 ═══ */
.fld{margin-bottom:16px}
.fld-l{display:flex;align-items:baseline;justify-content:space-between;gap:10px;font-size:12px;letter-spacing:.18em;color:var(--ink2);margin-bottom:7px}
.fld-l .fhint{font-size:11px;letter-spacing:.02em;color:var(--ink3);font-weight:400}
.fld-row{display:flex;gap:9px}
.inp{width:100%;min-height:44px;padding:9px 13px;background:rgba(6,17,22,.85);border:1px solid var(--line);border-radius:7px;
  color:var(--ink);font-size:14.5px;transition:border-color .2s,box-shadow .2s}
.inp::placeholder{color:#54696f}
.inp:focus{outline:0;border-color:var(--amber);box-shadow:0 0 0 1px rgba(232,163,61,.35),0 0 14px rgba(232,163,61,.15)}
textarea.inp{resize:vertical;min-height:92px;line-height:1.7}
select.inp{appearance:none;-webkit-appearance:none;padding-right:34px;
  background-image:linear-gradient(45deg,transparent 49%,var(--ink2) 50%),linear-gradient(-45deg,transparent 49%,var(--ink2) 50%);
  background-position:calc(100% - 19px) 50%,calc(100% - 13px) 50%;background-size:6px 6px;background-repeat:no-repeat}
select.inp option{background:#0a161a;color:var(--ink)}
.inp-x{flex:0 0 auto;width:44px;min-height:44px;padding:0;display:inline-flex;align-items:center;justify-content:center;
  border:1px solid var(--bd);border-radius:7px;background:var(--panel2);color:var(--amberL);font-size:17px;transition:all .2s}
.inp-x:hover{border-color:var(--bd2);box-shadow:0 0 12px rgba(232,163,61,.25)}
.inp-x:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
/* 数字输入（年龄/身高/体重） */
.num-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.nf{position:relative}
.nf .inp{padding-right:46px}
.nf .unit{position:absolute;right:12px;top:0;bottom:0;display:flex;align-items:center;font-family:var(--mono);font-size:11px;color:var(--ink3);pointer-events:none}
/* 分段单选 */
.seg{display:flex;gap:8px;flex-wrap:wrap}
.seg .sgb{min-height:44px;padding:8px 22px;border-radius:99px;border:1px solid var(--line);background:var(--panel2);
  color:var(--ink2);font-size:14px;letter-spacing:.14em;transition:all .18s}
.seg .sgb:hover{border-color:var(--bd);color:var(--amberL)}
.seg .sgb.on{border-color:var(--amber);color:#241505;background:linear-gradient(180deg,#f2b95c,#dd922e);font-weight:700;box-shadow:0 0 14px rgba(232,163,61,.3)}
.seg .sgb:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
/* 身份卡片网格 */
.id-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.idc{position:relative;display:flex;flex-direction:column;gap:2px;text-align:left;padding:10px 12px;min-height:44px;
  border:1px solid var(--line);border-radius:9px;background:var(--panel2);transition:all .18s;overflow:hidden}
.idc:hover{border-color:var(--bd);transform:translateY(-1px)}
.idc .ic-e{font-size:20px;line-height:1.2}
.idc .ic-n{font-size:14.5px;font-weight:700;color:var(--ink);letter-spacing:.04em}
.idc .ic-t{font-size:11px;color:var(--ink2)}
.idc .ic-s{font-size:10.5px;color:rgba(62,198,200,.72)}
.idc .ic-ck{position:absolute;top:6px;right:7px;font-size:12px;color:var(--amberL);opacity:0;transform:scale(.4);transition:all .2s}
.idc.sel{border-color:var(--amber);background:rgba(232,163,61,.1);box-shadow:0 0 0 1px rgba(232,163,61,.5),0 0 16px rgba(232,163,61,.16)}
.idc.sel .ic-n{color:var(--amberL)}
.idc.sel .ic-ck{opacity:1;transform:scale(1)}
.idc.custom{border-style:dashed;border-color:var(--tbd)}
.idc.custom.sel{border-style:solid;border-color:var(--amber)}
.idc.custom .ic-n{color:var(--teal)}
.idc.custom.sel .ic-n{color:var(--amberL)}
.idc:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.id-custom{margin-top:10px;padding:13px 14px;border:1px solid var(--tbd);border-radius:10px;background:rgba(62,198,200,.05);
  display:flex;flex-direction:column;gap:9px}
.id-custom .idc-hint{font-size:12px;color:var(--ink2)}
.id-custom .idc-hint b{color:var(--teal);font-weight:600}
/* chips 组（时代/性格/外貌维度，神墟式 ＋自定义词条机制） */
.chipbox{display:flex;gap:8px;flex-wrap:wrap;margin-top:2px}
.chip{min-height:44px;padding:8px 16px;border-radius:99px;border:1px solid var(--line);background:var(--panel2);
  color:var(--ink2);font-size:13.5px;letter-spacing:.06em;transition:all .16s;display:inline-flex;align-items:center;gap:7px}
.chip:hover{border-color:var(--bd);color:var(--amberL)}
.chip.on{border-color:var(--amber);color:#241505;background:linear-gradient(180deg,#f2b95c,#dd922e);font-weight:700;box-shadow:0 0 12px rgba(232,163,61,.28)}
.chip:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.chip-custom{border-style:dashed;border-color:var(--tbd);color:#9fe6e8}
.chip-custom.on{border-style:solid}
.chip-custom .cx{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;
  font-size:10px;opacity:.75;transition:all .15s;flex:0 0 auto}
.chip-custom .cx:hover{opacity:1;background:rgba(226,96,79,.25);color:#f0b3a9}
.chip-addbtn{border-style:dashed;border-color:var(--tbd);color:#9fe6e8;font-size:12.5px;padding:8px 14px}
.chip-addbtn:hover{border-color:var(--tbd2);color:#c8f4f5;box-shadow:0 0 10px rgba(62,198,200,.15)}
/* ＋自定义 展开的内联输入 */
.chip-inline{display:inline-flex;gap:7px;align-items:center;flex-wrap:nowrap}
.chip-inline .cin{width:158px;min-height:44px;padding:7px 12px;font-size:13px}
.chip-inline .cok{width:44px;min-height:44px;border-radius:99px;border:1px solid var(--tbd);background:rgba(62,198,200,.1);
  color:#9fe6e8;font-size:15px;display:inline-flex;align-items:center;justify-content:center;transition:all .16s}
.chip-inline .cok:hover{border-color:var(--tbd2);box-shadow:0 0 10px rgba(62,198,200,.2)}
.cnt{font-family:var(--mono);font-size:11px;color:var(--ink3)}
.cnt-warn{color:var(--amber)}

/* ═══ 同行队友 ═══ */
.mate-card{border:1px solid var(--line);border-radius:10px;background:var(--panel2);margin-bottom:10px;overflow:hidden}
.mate-hd{display:flex;align-items:center;gap:8px;padding:6px 8px 6px 14px;
  background:linear-gradient(90deg,rgba(62,198,200,.1),transparent 72%);border-bottom:1px solid var(--lineS);
  font-size:12.5px;color:#9fe6e8;letter-spacing:.14em}
.mate-hd .mhint{font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;color:var(--ink3)}
.mate-hd .mx{margin-left:auto;width:44px;height:44px;border-radius:8px;border:1px solid var(--line);color:var(--ink2);
  font-size:14px;display:flex;align-items:center;justify-content:center;transition:all .18s;flex:0 0 auto}
.mate-hd .mx:hover{border-color:rgba(226,96,79,.55);color:#f0b3a9;box-shadow:0 0 10px rgba(226,96,79,.2)}
.mate-hd .mx:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.mate-bd{padding:10px 12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}
.mate-f{display:flex;flex-direction:column;gap:4px;min-width:0}
.mate-f label{font-size:11px;color:var(--ink3);letter-spacing:.12em}
.mate-bd .inp{min-height:44px;font-size:13.5px;padding:7px 11px}
.mate-add{width:100%;min-height:48px;border:1px dashed var(--tbd);border-radius:10px;background:rgba(62,198,200,.04);
  color:#9fe6e8;font-size:13.5px;letter-spacing:.14em;transition:all .18s;display:flex;align-items:center;justify-content:center;gap:8px}
.mate-add:hover:not(:disabled){border-color:var(--tbd2);background:rgba(62,198,200,.08);box-shadow:0 0 12px rgba(62,198,200,.12)}
.mate-add:disabled{opacity:.45}
.mate-empty{padding:12px 14px;border:1px dashed var(--line);border-radius:10px;font-size:12.5px;color:var(--ink3);line-height:1.8}

/* ═══ STEP5 属性 ═══ */
.st-head{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:14px;
  padding:12px 15px;border:1px solid var(--bd);border-radius:10px;background:linear-gradient(165deg,rgba(232,163,61,.09),rgba(10,24,28,.4))}
.st-bud{display:flex;flex-direction:column;gap:0;min-width:118px;padding:6px 16px;border-radius:9px;text-align:center;
  background:linear-gradient(180deg,rgba(232,163,61,.16),rgba(232,163,61,.05));border:1px solid var(--bd);box-shadow:0 0 16px rgba(232,163,61,.14) inset}
.st-bud .b-n{font-family:var(--mono);font-size:27px;line-height:1.15;color:var(--amberL);font-weight:700;text-shadow:0 0 14px rgba(232,163,61,.5)}
.st-bud .b-t{font-size:10.5px;letter-spacing:.24em;color:var(--ink2)}
.st-src{flex:1 1 200px;min-width:0;font-size:12.5px;color:var(--ink2);line-height:1.65}
.st-src b{color:var(--amberL);font-weight:600}
.st-src .k{font-family:var(--mono);font-size:11px;color:var(--teal)}
.st-rows{border:1px solid var(--lineS);border-radius:10px;overflow:hidden;background:rgba(6,17,22,.35)}
.st-row{display:grid;grid-template-columns:132px minmax(0,1fr) 118px auto;gap:10px;align-items:center;
  padding:7px 13px;min-height:58px;border-bottom:1px dashed var(--lineS);transition:background .15s}
.st-row:last-child{border-bottom:0}
.st-row:hover{background:rgba(62,198,200,.04)}
.st-row.hl{background:rgba(232,163,61,.07)}
.sr-n{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;color:var(--ink)}
.sr-n .ic{font-size:17px}
.sr-n .pv{margin-left:auto;font-family:var(--mono);font-size:10px;color:var(--ink3);background:rgba(232,163,61,.14);border:1px solid var(--bd0);border-radius:3px;padding:0 5px}
.sr-d{font-size:11px;color:var(--ink3);line-height:1.5}
.sr-v{font-family:var(--mono);text-align:right;white-space:nowrap}
.sr-v .b{font-size:12.5px;color:var(--ink3)}
.sr-v .ar{color:var(--ink3);font-size:11px;margin:0 3px}
.sr-v .a{font-size:16.5px;color:var(--amberL);font-weight:700}
.sr-v .a.zero{color:var(--ink2);font-weight:400}
.sr-b{display:flex;align-items:center;gap:7px}
.sbtn{width:44px;height:44px;border-radius:8px;border:1px solid var(--bd);background:var(--panel2);color:var(--amberL);
  font-size:19px;font-family:var(--mono);display:inline-flex;align-items:center;justify-content:center;transition:all .15s}
.sbtn:hover:not(:disabled){border-color:var(--bd2);background:rgba(232,163,61,.14);box-shadow:0 0 12px rgba(232,163,61,.25)}
.sbtn:disabled{opacity:.32}
.sbtn:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.sr-pts{min-width:26px;text-align:center;font-family:var(--mono);font-size:13px;color:var(--amber);font-weight:700}
.st-sum{margin-top:12px;padding:10px 14px;border:1px solid var(--tbd);border-radius:9px;background:rgba(62,198,200,.05);
  font-family:var(--mono);font-size:12px;color:var(--ink2);line-height:1.8;word-break:break-all}
.st-sum b{color:var(--teal);font-weight:600}
.st-note{margin-top:10px;font-size:12px;color:var(--ink3)}

/* ═══ STEP6 装备/宠物/作弊 ═══ */
.pk-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.pk{position:relative;display:flex;flex-direction:column;gap:6px;text-align:left;padding:13px 15px;min-height:44px;
  border:1px solid var(--line);border-radius:10px;background:var(--panel2);transition:all .18s;overflow:hidden}
.pk::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,var(--tbd),transparent);opacity:.6}
.pk:hover{border-color:var(--bd);transform:translateY(-2px);box-shadow:0 8px 20px rgba(0,0,0,.35)}
.pk.sel{border-color:var(--amber);background:linear-gradient(165deg,rgba(232,163,61,.1),rgba(10,24,28,.5));
  box-shadow:0 0 0 1px rgba(232,163,61,.55),0 0 22px rgba(232,163,61,.2)}
.pk.sel::before{background:linear-gradient(90deg,transparent,var(--amber),transparent);opacity:1}
.pk-h{display:flex;align-items:center;gap:9px}
.pk-h .ic{font-size:22px}
.pk-h .n{font-size:16px;font-weight:700;color:var(--ink);letter-spacing:.05em}
.pk-h .ck{margin-left:auto;font-size:13px;color:var(--amberL);opacity:0;transform:scale(.4);transition:all .2s}
.pk.sel .ck{opacity:1;transform:scale(1)}
.pk-f{font-size:12px;color:var(--ink2);font-style:italic}
.pk-list{list-style:none;display:flex;flex-direction:column;gap:2px;margin-top:2px}
.pk-list li{font-family:var(--mono);font-size:12px;color:var(--ink);padding:2.5px 0;border-bottom:1px dashed var(--lineS)}
.pk-list li:last-child{border-bottom:0}
.pk-list .q{color:var(--amber);margin-left:6px}
.pk-eng{display:flex;gap:5px;flex-wrap:wrap;margin-top:3px}
.pk-eng span{font-size:10.5px;padding:2px 8px;border-radius:3px;border:1px solid var(--tbd);color:#9fe6e8;background:rgba(62,198,200,.06)}
.pk-eng .none{border-color:var(--line);color:var(--ink3);background:none}
/* 宠物八选一 + 自定义物种（V3.4.1） */
.pet-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.petc{position:relative;display:flex;flex-direction:column;gap:3px;text-align:left;padding:12px 13px;min-height:44px;
  border:1px solid var(--line);border-radius:10px;background:var(--panel2);transition:all .18s;overflow:hidden}
.petc:hover{border-color:var(--bd);transform:translateY(-2px)}
.petc .pc-e{font-size:26px;line-height:1.2}
.petc .pc-n{font-size:15px;font-weight:700;color:var(--ink);letter-spacing:.06em;display:flex;align-items:baseline;gap:7px}
.petc .pc-lv{font-family:var(--mono);font-size:10px;color:var(--teal);font-weight:400}
.petc .pc-t{font-size:11.5px;color:var(--ink2)}
.petc .pc-d{font-size:10.5px;color:var(--ink3);line-height:1.55}
.petc .pc-ck{position:absolute;top:7px;right:8px;font-size:12px;color:var(--amberL);opacity:0;transform:scale(.4);transition:all .2s}
.petc.sel{border-color:var(--amber);background:rgba(232,163,61,.09);box-shadow:0 0 0 1px rgba(232,163,61,.5),0 0 16px rgba(232,163,61,.16)}
.petc.sel .pc-n{color:var(--amberL)}
.petc.sel .pc-ck{opacity:1;transform:scale(1)}
.petc:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.pet-name{margin-top:10px;display:flex;gap:9px;align-items:center;flex-wrap:wrap}
.pet-name .lbl{font-size:12px;letter-spacing:.14em;color:var(--ink2);flex:0 0 auto}
.pet-name .inp{flex:1 1 160px;min-width:0}
/* 苏醒资助（作弊） */
.cht-box{border:1px solid rgba(226,96,79,.4);border-radius:10px;padding:12px 14px 14px;background:rgba(226,96,79,.05)}
.cht-h{font-size:12px;letter-spacing:.22em;color:#f0b3a9;margin-bottom:3px;font-weight:600;display:flex;align-items:center;gap:8px}
.cht-h .en{font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;color:var(--ink3);font-weight:400}
.cht-h::before{content:'▸';color:var(--red)}
.cht-warn{font-size:12px;color:#f0b3a9;margin:0 0 10px;line-height:1.7}
.cht-box .chip.on{border-color:var(--red);background:linear-gradient(180deg,#e2604f,#c14a3b);color:#fff;box-shadow:0 0 12px rgba(226,96,79,.3)}
.cht-note{margin-top:9px;font-size:11.5px;color:var(--ink3)}

/* ═══ STEP4 游戏设定 ═══ */
.set-h{font-size:12px;letter-spacing:.22em;color:var(--ink2);margin:16px 0 9px;font-weight:600;display:flex;align-items:center;gap:8px}
.set-h:first-child{margin-top:0}
.set-h::before{content:'▸';color:var(--amber)}
.set-h .en{font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;color:var(--ink3);font-weight:400}
.df-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.md-grid,.sy-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.setc{position:relative;display:flex;flex-direction:column;gap:3px;text-align:left;padding:12px 14px;min-height:44px;
  border:1px solid var(--line);border-radius:9px;background:var(--panel2);transition:all .18s}
.setc:hover{border-color:var(--bd);transform:translateY(-1px)}
.setc .sc-n{font-size:15.5px;font-weight:700;color:var(--ink);letter-spacing:.08em}
.setc .sc-t{font-size:11.5px;color:var(--ink2)}
.setc .sc-d{font-size:11px;color:var(--ink3);line-height:1.55}
.setc .sc-b{margin-top:3px;font-family:var(--mono);font-size:10px;letter-spacing:.06em;color:var(--teal);
  align-self:flex-start;border:1px solid var(--tbd);border-radius:3px;padding:1px 7px;background:rgba(62,198,200,.06)}
.setc .sc-ck{position:absolute;top:7px;right:8px;font-size:12px;color:var(--amberL);opacity:0;transform:scale(.4);transition:all .2s}
.setc.sel{border-color:var(--amber);background:rgba(232,163,61,.09);box-shadow:0 0 0 1px rgba(232,163,61,.5),0 0 16px rgba(232,163,61,.15)}
.setc.sel .sc-n{color:var(--amberL)}
.setc.sel .sc-ck{opacity:1;transform:scale(1)}
.setc.warn.sel{box-shadow:0 0 0 1px rgba(226,96,79,.55),0 0 16px rgba(226,96,79,.18)}
.setc:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.set-warn{margin-top:10px;padding:10px 13px;border:1px solid rgba(226,96,79,.4);border-radius:8px;background:rgba(226,96,79,.06);
  font-size:12.5px;color:#f0b3a9}
.set-warn b{color:var(--red)}
/* V3.4.1：自定义卡片虚线变体（开局场景/宠物）与预算满禁用 chip */
.setc.custom,.petc.custom{border-style:dashed;border-color:var(--tbd)}
.setc.custom .sc-n,.petc.custom .pc-n{color:#9fe6e8}
.setc.custom.sel .sc-n,.petc.custom.sel .pc-n{color:var(--amberL)}
.chip:disabled{opacity:.38;filter:saturate(.55)}

/* ═══ STEP7 确认 ═══ */
.cf-groups{display:flex;flex-direction:column;gap:12px}
.cf-g{border:1px solid var(--lineS);border-radius:10px;background:var(--panel2);overflow:hidden}
.cf-g>.cg-h{display:flex;align-items:center;gap:9px;padding:9px 14px;font-size:12.5px;letter-spacing:.2em;color:var(--amberL);
  background:linear-gradient(90deg,rgba(232,163,61,.12),transparent 70%);border-bottom:1px solid var(--lineS)}
.cf-g>.cg-h .en{font-family:var(--mono);font-size:9.5px;letter-spacing:.16em;color:var(--ink3);margin-left:auto}
.cg-b{padding:6px 14px 9px}
.cg-r{display:flex;gap:12px;padding:5.5px 0;border-bottom:1px dashed var(--lineS);font-size:13.5px}
.cg-r:last-child{border-bottom:0}
.cg-r .k{flex:0 0 108px;color:var(--ink3);letter-spacing:.06em}
.cg-r .v{flex:1 1 auto;min-width:0;color:var(--ink);word-break:break-word;line-height:1.7}
.cg-r .v b{color:var(--amberL);font-weight:600}
.cg-r .v .tl{color:var(--teal)}
.cf-env{margin:14px 0;padding:12px 15px;border:1px solid var(--bd0);border-radius:10px;background:rgba(6,17,22,.5)}
.cf-env .ce-h{font-size:12px;letter-spacing:.2em;color:var(--ink2);margin-bottom:8px}
.cf-env .ce-badges{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px}
.cf-env .ce-fix{font-size:12.5px;color:var(--ink2);line-height:1.75}
.cf-env .ce-fix b{color:var(--amberL);font-weight:600}
.cf-st{margin:10px 0 4px;font-family:var(--mono);font-size:12px;color:var(--teal);text-align:center;min-height:18px;letter-spacing:.06em}
.cf-st.err{color:var(--red)}
/* 成功横幅（三通道结果） */
.cf-done{margin:14px 0 6px;border:1px solid rgba(232,163,61,.55);border-radius:12px;overflow:hidden;position:relative;
  background:linear-gradient(165deg,rgba(232,163,61,.13),rgba(10,24,28,.55) 46%,rgba(62,198,200,.05));
  box-shadow:0 0 30px rgba(232,163,61,.14),inset 0 1px 0 rgba(255,225,170,.18)}
.cf-done::before{content:'';position:absolute;inset:3px;border:1px solid rgba(232,163,61,.22);border-radius:9px;pointer-events:none}
.cd-hd{display:flex;align-items:center;gap:12px;padding:14px 18px 8px}
.cd-ico{flex:0 0 auto;width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:23px;
  background:radial-gradient(circle at 34% 30%,#ffe9b8,#e8a33d 58%,#b97c1e);color:#241505;font-weight:700;
  box-shadow:0 0 20px rgba(232,163,61,.5)}
.cd-tx{min-width:0}
.cd-t{font-family:var(--serif);font-size:20px;letter-spacing:3px;color:var(--amberL);text-shadow:0 0 14px rgba(232,163,61,.4)}
.cd-s{font-family:var(--mono);font-size:11px;color:var(--ink2);letter-spacing:.1em;margin-top:2px}
.cd-wait{padding:2px 18px 10px;font-size:13px;color:var(--ink);animation:cdBlink 1.8s ease-in-out infinite}
.cd-wait::before{content:'▍';color:var(--amber);margin-right:6px}
@keyframes cdBlink{0%,100%{opacity:1}50%{opacity:.45}}
.cd-list{padding:0 18px 6px;display:flex;flex-direction:column;gap:3px}
.cd-list .cd-r{display:flex;gap:8px;font-size:12.5px;color:var(--ink2);line-height:1.65}
.cd-list .cd-r .s{flex:0 0 auto;font-family:var(--mono)}
.cd-list .cd-r .s.ok{color:var(--green)} .cd-list .cd-r .s.wa{color:var(--amber)} .cd-list .cd-r .s.no{color:var(--red)}
.cd-cmd{margin:4px 18px 14px}
.cd-cmd summary{list-style:none;cursor:pointer;min-height:44px;display:flex;align-items:center;gap:8px;font-size:13px;color:var(--teal)}
.cd-cmd summary::-webkit-details-marker{display:none}
.cd-cmd summary::after{content:'▾';margin-left:auto;color:var(--ink3)}
.cd-cmd[open] summary::after{content:'▴'}
.cd-cmd pre{white-space:pre-wrap;word-break:break-all;max-height:180px;overflow:auto;margin:6px 0 10px;padding:11px 13px;
  background:rgba(4,11,14,.9);border:1px solid var(--lineS);border-radius:7px;font-family:var(--mono);font-size:11.5px;line-height:1.7;color:var(--ink2)}
.cd-acts{display:flex;gap:10px;flex-wrap:wrap}

/* ═══ 底栏（三段之三） ═══ */
.ak-foot{position:relative;z-index:10;display:flex;align-items:center;gap:12px;padding:12px 20px 14px;flex:0 0 auto;
  border-top:1px solid var(--bd0);background:linear-gradient(0deg,rgba(8,20,24,.7),rgba(8,20,24,.25))}
.ft-hint{flex:1 1 auto;min-width:0;text-align:center;font-size:12.5px;color:var(--ink2);letter-spacing:.04em}
.ft-hint.block{color:#f0b3a9}
.ft-hint.ok{color:var(--green)}
.ak-foot .btn{flex:0 0 auto}
.ak-foot .btn-next-hero{min-width:190px}

/* ═══ Toast ═══ */
#akToast{position:absolute;top:64px;right:14px;z-index:96;display:flex;flex-direction:column;gap:8px;align-items:flex-end;pointer-events:none;max-width:calc(100% - 28px)}
.toast{max-width:320px;padding:10px 15px;border-radius:7px;font-size:13px;line-height:1.6;color:var(--ink);
  background:rgba(7,18,22,.96);border:1px solid var(--bd);border-left:3px solid var(--amber);
  box-shadow:0 8px 24px rgba(0,0,0,.5);animation:tIn .3s cubic-bezier(.2,.8,.3,1)}
.toast.err{border-color:rgba(226,96,79,.55);border-left-color:var(--red)}
.toast.out{animation:tOut .3s forwards}
@keyframes tIn{from{opacity:0;transform:translateX(18px)}to{opacity:1;transform:none}}
@keyframes tOut{to{opacity:0;transform:translateX(18px)}}

/* ═══ 弹窗（复制兜底） ═══ */
.ak-modal{position:absolute;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;
  padding:30px 16px;background:rgba(3,8,10,.82)}
.ak-modal[hidden]{display:none}
.modal-box{position:relative;width:100%;max-width:640px;border:1px solid var(--bd2);border-radius:12px;
  background:linear-gradient(165deg,#10242a,#081419 52%,#050b0e);
  box-shadow:0 0 0 1px rgba(0,0,0,.5),0 24px 80px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,220,160,.14);
  animation:mIn .3s cubic-bezier(.2,.8,.3,1);max-height:100%;display:flex;flex-direction:column}
@keyframes mIn{from{opacity:0;transform:translateY(-14px) scale(.98)}to{opacity:1;transform:none}}
.modal-hd{display:flex;align-items:center;gap:10px;padding:13px 16px;border-bottom:1px solid var(--bd0);flex:0 0 auto}
.modal-t{font-family:var(--serif);font-size:17px;letter-spacing:2px;color:var(--amberL)}
.modal-t::before{content:'◈ ';color:var(--amber)}
.modal-x{margin-left:auto;width:44px;height:44px;border-radius:8px;border:1px solid var(--line);color:var(--ink2);
  font-size:15px;display:flex;align-items:center;justify-content:center;transition:all .18s}
.modal-x:hover{border-color:var(--bd2);color:var(--amberL)}
.modal-x:focus-visible{outline:2px solid var(--teal);outline-offset:2px}
.modal-bd{padding:14px 16px 16px;overflow-y:auto;min-height:0}
.modal-infobar{padding:10px 13px;border:1px solid var(--bd);border-left:3px solid var(--amber);border-radius:8px;
  background:rgba(232,163,61,.07);font-size:13px;color:var(--ink);margin-bottom:10px;line-height:1.7}
.modal-infobar b{color:var(--amberL)}
.modal-pre{white-space:pre-wrap;word-break:break-all;max-height:240px;overflow:auto;padding:12px 14px;
  background:rgba(4,11,14,.92);border:1px solid var(--lineS);border-radius:7px;
  font-family:var(--mono);font-size:11.5px;line-height:1.75;color:var(--ink2)}
.modal-note{font-size:12px;color:var(--ink3);margin-top:8px;line-height:1.7}
.modal-acts{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}

/* ═══ 响应式 ═══ */
@media (max-width:900px){
  .id-grid{grid-template-columns:repeat(3,1fr)}
  .mk-grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:820px){
  .rg-wrap{grid-template-columns:1fr}
  .rg-list{max-height:200px}
  .mate-bd{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:760px){
  .ak-body{flex-direction:column}
  .ak-side{width:auto;flex:0 0 auto;border-right:0;border-bottom:1px solid var(--bd0);padding:8px 10px;overflow:visible}
  .ak-steps{flex-direction:row;gap:2px;overflow-x:auto;padding-bottom:2px}
  .stp{flex:1 0 auto;min-width:92px;flex-direction:column;gap:4px;padding:6px 8px;justify-content:center;text-align:center}
  .side-cap,.side-foot{display:none}
  .ak-main{padding:14px 14px 22px}
  .pet-grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:700px){
  .pk-grid{grid-template-columns:1fr}
  .df-grid{grid-template-columns:repeat(2,1fr)}
  .md-grid,.sy-grid{grid-template-columns:repeat(2,1fr)}
  .hm-t{font-size:30px;letter-spacing:6px;text-indent:6px}
  .brand-t{font-size:17px}
}
@media (max-width:560px){
  .id-grid{grid-template-columns:repeat(2,1fr)}
  .mk-grid{grid-template-columns:1fr}
  .ak-head{padding:10px 14px 8px}
  .brand-s{white-space:normal;letter-spacing:.12em;line-height:1.6}
  .ak-env{margin-left:0}
  .ak-env .env-badge{font-size:10px;padding:3px 8px}
  .mate-bd{grid-template-columns:1fr}
  .num-grid{grid-template-columns:1fr 1fr}
  .num-grid .nf-full{grid-column:1 / -1}
}
@media (max-width:430px){
  .st-row{grid-template-columns:1fr auto;grid-template-areas:'n b' 'd b' 'v b';row-gap:4px}
  .sr-n{grid-area:n}.sr-d{grid-area:d}.sr-v{grid-area:v;text-align:left}.sr-b{grid-area:b}
  .df-grid{grid-template-columns:1fr}
  .ak-foot{flex-wrap:wrap}
  .ft-hint{order:3;flex-basis:100%}
  .chip-inline .cin{width:132px}
}
@media (max-width:380px){
  .md-grid,.sy-grid{grid-template-columns:1fr}
  .id-grid{grid-template-columns:1fr}
  .hm-t{font-size:25px}
}
/* ═══ 动效关停（prefers-reduced-motion） ═══ */
@media (prefers-reduced-motion:reduce){
  .ak-root,.ak-root::before,.ak-root::after,.ak-tex,.ak-tex::before,.ak-noise,
  .ak-panel.on .sg,.ak-panel.on .sg::before,.ak-panel.on .sg::after,
  .env-badge.ok .dot,.stp,.stp-n,.btn,.btn-hero,.fchip,.chip,.mk,.mk-imgwrap img,.mk-ck,.idc,.setc,.pk,.petc,
  .rg-dot,.rg-dot i,.rg-dot i::before,.rg-dot i::after,.rg-dot.sel::after,.rg-tip,
  .rg-item,.sbtn,.toast,.modal-box,.cd-wait,.cd-ico,.inp,.sgb,.inp-x,.howto summary::after,
  .hm-start,.st-bud .b-n,.cf-done,.cf-done::before,.mate-add,.mate-hd .mx,.chip-inline .cok{
    animation:none!important;transition:none!important}
}
</style>
<script>
/* iframe 内嵌探测（神墟模式）：srcdoc iframe 里 vh 不可靠，尽早加 embed 类解除高度约束 */
(function(){
  try{
    var embedded=false;
    try{embedded=(window.self!==window.top);}catch(e){embedded=true;}
    if(!embedded)return;
    var apply=function(){
      var rt=document.getElementById('akRoot');
      if(rt&&!rt.classList.contains('embed'))rt.classList.add('embed');
    };
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);
    else apply();
  }catch(e){}
})();
</script>
