    <main class="ak-main" id="akMain">
    <!-- ══ HOME 标题画 ══ -->
    <section class="ak-panel on" id="p-home" aria-label="标题画面">
      <div class="hm">
        <svg class="sg hm-hex" viewBox="0 0 96 96" aria-hidden="true" focusable="false">
          <defs><linearGradient id="akBigHex" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffe9b8"/><stop offset=".55" stop-color="#e8a33d"/><stop offset="1" stop-color="#a1723a"/></linearGradient></defs>
          <path d="M48 6 84 27v42L48 90 12 69V27Z" fill="none" stroke="url(#akBigHex)" stroke-width="3"/>
