      <div class="sec-h sg">基础身份 <span class="en">IDENTITY</span></div>
      <div class="fld sg">
        <label class="fld-l" for="fName">姓名 <span class="fhint">必填 · 可点击 🎲 随机英文名</span></label>
        <div class="fld-row">
          <input class="inp" id="fName" type="text" maxlength="24" autocomplete="off" placeholder="你的生存者姓名（中英文皆可）">
          <button type="button" class="inp-x" id="btnReroll" title="随机生成 ARK 风格姓名" aria-label="随机生成姓名">🎲</button>
        </div>
      </div>
      <div class="fld sg">
        <span class="fld-l">性别 <span class="fhint">影响叙事称谓，不影响数值</span></span>
        <div class="seg" id="segGender" role="group" aria-label="性别选择">
          <button type="button" class="sgb" data-v="男">男</button>
          <button type="button" class="sgb" data-v="女">女</button>
          <button type="button" class="sgb" data-v="不指定">不指定</button>
