        <div class="chipbox" id="skinChips" role="group" aria-label="肤色选择"></div>
      </div>
      <div class="fld sg">
        <span class="fld-l">发色 <span class="fhint">单选 · 可添加自定义词条</span></span>
        <div class="chipbox" id="hairChips" role="group" aria-label="发色选择"></div>
      </div>
      <div class="fld sg">
        <span class="fld-l">发型 <span class="fhint">单选 · 可添加自定义词条</span></span>
        <div class="chipbox" id="styleChips" role="group" aria-label="发型选择"></div>
      </div>
      <div class="fld sg">
        <span class="fld-l">气质 <span class="fhint">可多选（最多 3 项）· 他人对你的第一印象</span></span>
        <div class="chipbox" id="auraChips" role="group" aria-label="气质多选"></div>
