    </section>

    <!-- ══ STEP4 游戏设定（V3.4.2 步序前移：先定设定，再分配属性与装备） ══ -->
    <section class="ak-panel" id="p-4" aria-label="第四步 游戏设定">
      <h2 class="h2 sg">游戏设定 <span class="en">SESSION SETTINGS</span></h2>
      <p class="p-sub sg">难度影响资源与伤势判定；开局场景决定苏醒的第一幕，复活模式决定死亡的代价。</p>
      <div class="set-h sg">生存难度 <span class="en">DIFFICULTY</span></div>
      <div class="df-grid sg" id="dfGrid"></div>
      <div class="set-h sg">开场模式 <span class="en">OPENING MODE</span></div>
      <div class="md-grid sg" id="mdGrid"></div>
      <div id="mdWarn"></div>
      <div class="set-h sg">开局场景 <span class="en">OPENING SCENARIO</span></div>
      <div class="md-grid sg" id="scnGrid"></div>
      <div class="id-custom sg" id="scnCustom" hidden>
        <p class="idc-hint">✧ <b>自定义场景</b> —— 自由描述你的苏醒瞬间，AI 将按你的设定起笔（最多 400 字）。</p>
        <textarea class="inp" id="fScnText" maxlength="400" style="min-height:96px" placeholder="建议写明时间、地点、人物与事件。灵感：暴雨黄昏，我在瀑布后的干燥岩洞里苏醒，洞外传来重物拖行的声响，手臂上的菱形植入体闪着不稳定的红光……"></textarea>
        <p class="cnt" id="scnTextCnt" style="margin-top:5px"></p>
      </div>
      <div class="set-h sg">复活模式 <span class="en">REVIVE MODE</span></div>
      <div class="md-grid sg" id="rvGrid"></div>
      <p class="cht-note sg" id="rvNote" style="margin-top:9px">▸ 复活模式已写入会话设置，死亡结算按【死亡与重生规则】对应档位执行。</p>
      <div class="set-h sg">叙事风格 <span class="en">NARRATIVE STYLE</span></div>
      <div class="sy-grid sg" id="syGrid"></div>
      <div class="set-h sg">玩法偏好 <span class="en">PREFERENCES</span></div>
      <div class="chipbox sg" id="pfChips" style="margin-top:2px"></div>
      <div class="chip-add sg">
        <input class="inp" id="pfInput" type="text" maxlength="8" autocomplete="off" placeholder="自定义偏好，如：钓鱼佬">
        <button type="button" class="btn btn-teal" id="pfAdd">＋ 添加</button>
      </div>
    </section>

    <!-- ══ STEP5 初始属性 ══ -->
    <section class="ak-panel" id="p-5" aria-label="第五步 初始属性">
      <h2 class="h2 sg">初始属性 <span class="en">ATTRIBUTE ALLOCATION</span></h2>
