 s+='<defs>';
 s+='<radialGradient id="mfBg'+(big?'F':'G')+'" cx="50%" cy="42%" r="75%"><stop offset="0" stop-color="#0d2830"/><stop offset="1" stop-color="#06131a"/></radialGradient>';
 s+='<linearGradient id="mfLn'+(big?'F':'G')+'" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="rgba(232,163,61,.55)"/><stop offset="1" stop-color="rgba(62,198,200,.4)"/></linearGradient>';
 s+='</defs>';
 s+='<rect width="'+W+'" height="'+H+'" fill="url(#mfBg'+(big?'F':'G')+')"/>';
 var k=big?1.75:1;
 var cx=W/2,cy=big?H/2-40:H/2-30;
 s+='<g transform="translate('+cx+','+cy+') scale('+k+') translate(-240,-160)">';
 s+='<path d="'+path+'" fill="rgba(203,178,126,.13)" stroke="url(#mfLn'+(big?'F':'G')+')" stroke-width="2" stroke-linejoin="round" stroke-dasharray="7 5"/>';
 s+='<path d="'+path+'" fill="none" stroke="rgba(62,198,200,.22)" stroke-width="1" transform="translate(10,12)"/>';
 s+='</g>';
 s+='<text x="'+(W/2)+'" y="'+nmY+'" text-anchor="middle" font-family="Georgia,serif" font-size="'+sz+'" letter-spacing="6" fill="#ffd98c" opacity=".92">'+esc(m.n)+'</text>';
 s+='<text x="'+(W/2)+'" y="'+subY+'" text-anchor="middle" font-family="ui-monospace,monospace" font-size="'+(big?15:12)+'" letter-spacing="4" fill="#9fb8bf" opacity=".7">'+esc(m.en)+'</text>';
 s+='<text x="'+(W/2)+'" y="'+(subY+30)+'" text-anchor="middle" font-family="ui-monospace,monospace" font-size="'+(big?13:10.5)+'" letter-spacing="2" fill="#6d8288">官方地图影像离线 OFFLINE</text>';
