function guardImgs(root){
 qsa('img',root||document).forEach(function(img){
  if(img.__akGuarded)return;
  img.__akGuarded=true;
  img.addEventListener('error',function(){
   var k=img.getAttribute('data-k')||'';
   var mode=img.classList.contains('rg-img')?'full':'grid';
   var w=Number(img.getAttribute('data-w'))||(mode==='full'?800:480);
   var mf=MAP_FILES[k];
   if(mf){
    var idx=Number(img.getAttribute('data-mi')||'0');
    var chain=mapChain(mf,w);
    if(idx<chain.length){img.setAttribute('data-mi',String(idx+1));img.src=chain[idx];return;}
   }
   try{img.outerHTML=mapFallbackSVG(k,mode);}catch(e){}
  });
 });
}

/* ═══ 步骤导航（定高三段式：侧栏/主区/底栏联动） ═══ */
function panelId(n){return n===0?'#p-home':'#p-'+n;}
function setStep(n,opts){
 opts=opts||{};
 if(created&&!opts.force)return;
 n=Math.max(0,Math.min(7,n));
 S.step=n;
 qsa('.ak-panel').forEach(function(p){p.classList.remove('on');});
 var cur=qs(panelId(n));
 if(cur){
  cur.classList.add('on');
  var i=0;
  qsa('.sg',cur).forEach(function(el){
   el.style.setProperty('--i',String(Math.min(i,9)));
   i++;
  });
  try{qs('#akMain').scrollTop=0;}catch(e){}
 }
 var root=qs('#akRoot');
 if(root)root.classList.toggle('at-home',n===0&&!created);
 qsa('.stp').forEach(function(b){
  var idx=parseInt(b.getAttribute('data-n'),10)||1;
  b.classList.toggle('is-cur',idx===n);
  b.classList.toggle('is-done',idx<n);
  b.disabled=idx>n||created;
  var sn=qs('.stp-n',b);
  if(sn)sn.textContent=idx<n?'✓':(idx<10?'0'+idx:String(idx));
  if(idx===n)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');
 });
 var foot=qs('#akFoot');
 if(foot)foot.style.display=(n===0)?'none':'flex';
 var prev=qs('#btnPrev');
 if(prev)prev.disabled=(n<=1)||created;
 var next=qs('#btnNext');
 if(next){
  next.style.display='';
  next.disabled=created;
  if(created){next.textContent='已苏醒 ✓';next.className='btn btn-ghost';}
  else if(n>=7){next.textContent='◈ 确 认 苏 醒 ◈';next.className='btn btn-hero btn-next-hero';}
  else{next.textContent='下一步 →';next.className='btn btn-pri';}
 }
 renderStepContent(n);
 updateHint();
 renderEnv();
 scheduleDraft();
}
function renderStepContent(n){
 if(n===0){renderHomeSave();renderHomeDraft();renderEnv();}
 else if(n===1){renderMaps();}
 else if(n===2){renderRegions();}
 else if(n===3){hydrateProfile();}
 else if(n===4){renderSettings();}
 else if(n===5){renderStats();}
 else if(n===6){renderPacks();renderPets();renderCheats();renderExtras();}
 else if(n===7){renderConfirm();}
}
function stepReady(n){
 if(n===1)return !!S.mapKey;
 if(n===3)return !!trimmed(S.name);
 return true;
}
function stepMissing(n){
 if(n===1)return '请先在上方选择一张地图';
 if(n===3)return '姓名不可为空（可点击 🎲 随机生成）';
 return '';
}
function updateHint(){
 var el=qs('#ftHint');
 if(!el)return;
 if(created){el.textContent='状态 · 已苏醒 —— 开局指令待你亲手发送';el.className='ft-hint ok';return;}
 var n=S.step;
 if(n===0){el.textContent='';return;}
 if(n===7){el.textContent='复核无误后，点击「确认苏醒」';el.className='ft-hint';return;}
 if(!stepReady(n)){el.textContent='✖ '+stepMissing(n);el.className='ft-hint block';return;}
 var labels={1:'选定地图后继续',2:'选定出生区域后继续',3:'填写姓名后继续',4:'调整游戏设定',5:'分配属性点（可不分配）',6:'选择装备 / 宠物 / 资助'};
 el.textContent='▸ '+(labels[n]||'');
 el.className='ft-hint';
}
function goNext(){
 if(created)return;
 var n=S.step;
 if(n>=7){doConfirm();return;}
 if(!stepReady(n)){toast(stepMissing(n),true);return;}
 setStep(n+1);
}
function goPrev(){if(created)return;setStep(Math.max(0,S.step-1));}

