/* ═══ STEP2 出生区域 ═══ */
function renderRegions(){
 var m=S.mapKey?MAPS[S.mapKey]:null;
 if(!m){S.mapKey='island';m=MAPS.island;}
 var t=qs('#rgTitle');
 if(t)t.innerHTML=esc(m.n)+' · 出生区域 <span class="en">'+esc(m.en)+'</span>';
 var sub=qs('#rgSub');
 if(sub)sub.textContent='点击地图上的脉冲光点或右侧列表，选定你的苏醒之地。'+m.desc;
 var rs=REGIONS[S.mapKey]||[];
 var hasSel=false;
 for(var i=0;i<rs.length;i++)if(rs[i].n===S.region)hasSel=true;
 if(!hasSel)S.region=rs.length?rs[0].n:'';
 var map=qs('#rgMap');
 if(map){
  var h='<img class="rg-img" data-k="'+esc(S.mapKey)+'" src="'+esc(m.full)+'"" data-w="800 alt="'+esc(m.n)+' 官方地形勘察图" decoding="async">';
  h+='<span class="rg-grid"></span><span class="rg-frame"></span>';
  h+='<span class="rg-corner c1"></span><span class="rg-corner c2"></span><span class="rg-corner c3"></span><span class="rg-corner c4"></span>';
  rs.forEach(function(r,i){
   h+='<button type="button" class="rg-dot '+dangerClass(r.d)+(r.n===S.region?' sel':'')+'" style="left:'+r.x+'%;top:'+r.y+'%" data-i="'+i+'" aria-label="选择出生区域 '+esc(r.n)+'，危险 '+r.d+' 星" aria-pressed="'+(r.n===S.region?'true':'false')+'"><i></i></button>';
  });
  h+='<div class="rg-tip" id="rgTip"></div>';
  map.innerHTML=h;
  guardImgs(map);
  qsa('.rg-dot',map).forEach(function(d){
   var idx=parseInt(d.getAttribute('data-i'),10)||0;
   var r=rs[idx];
   if(!r)return;
   d.addEventListener('click',function(){selectRegion(r.n);});
   d.addEventListener('keydown',function(ev){
    if(ev.key==='Enter'||ev.key===' '||ev.key==='Spacebar'){ev.preventDefault();selectRegion(r.n);}
   });
   d.addEventListener('mouseenter',function(){showTip(d,r);});
   d.addEventListener('focus',function(){showTip(d,r);});
   d.addEventListener('mouseleave',hideTip);
   d.addEventListener('blur',hideTip);
  });
 }
 renderRegionList(rs);
 renderRegionCard();
}
function showTip(dot,r){
 var tip=qs('#rgTip');
 var map=qs('#rgMap');
 if(!tip||!map)return;
 var dt=dangerTag(r.d);
 var starsOn='';for(var i=0;i<r.d;i++)starsOn+='★';
 var starsOff='';for(var j=r.d;j<5;j++)starsOff+='★';
 tip.innerHTML='<span class="tt-n">'+esc(r.n)+'<span class="tt-s" style="--dc:'+dt.c+'"><span class="on">'+starsOn+'</span><span class="st">'+starsOff+'</span></span></span>'+
  '<span class="tt-d">'+esc(r.t)+'</span>';
 tip.classList.add('on');
 var mapW=map.clientWidth||300,mapH=map.clientHeight||300;
 var x=dot.offsetLeft+22,y=dot.offsetTop+22;
 var tw=tip.offsetWidth||190,th=tip.offsetHeight||70;
 if(x+tw>mapW-8)x=Math.max(6,dot.offsetLeft-tw-20);
 if(y+th>mapH-8)y=Math.max(6,dot.offsetTop-th-16);
 tip.style.left=x+'px';
 tip.style.top=y+'px';
}
function hideTip(){
 var tip=qs('#rgTip');
 if(tip)tip.classList.remove('on');
}
function renderRegionList(rs){
 var box=qs('#rgList');
 if(!box)return;
 box.innerHTML=rs.map(function(r,i){
  var dt=dangerTag(r.d);
  var starsOn='';for(var a=0;a<r.d;a++)starsOn+='★';
  var starsOff='';for(var b=r.d;b<5;b++)starsOff+='★';
  return '<button type="button" class="rg-item'+(r.n===S.region?' sel':'')+' '+dangerClass(r.d)+'" style="--dc:'+dt.c+'" data-i="'+i+'" role="option" aria-selected="'+(r.n===S.region?'true':'false')+'">'+
   '<span>'+esc(r.n)+'</span><span class="st">'+starsOn+'<span class="off">'+starsOff+'</span></span></button>';
 }).join('');
 qsa('.rg-item',box).forEach(function(b){
  b.addEventListener('click',function(){
   var idx=parseInt(b.getAttribute('data-i'),10)||0;
   var r=rs[idx];
   if(r)selectRegion(r.n);
  });
 });
}
function renderRegionCard(){
 var card=qs('#rgCard');
 if(!card)return;
 var r=regionData(S.region);
 if(!r){card.innerHTML='';return;}
 var dt=dangerTag(r.d);
 var starsOn='';for(var a=0;a<r.d;a++)starsOn+='★';
 var starsOff='';for(var b=r.d;b<5;b++)starsOff+='★';
 card.innerHTML=
  '<div class="rc-h"><span class="rc-n">'+esc(r.n)+'</span><span class="rc-tag" style="background:'+dt.c+'">'+esc(dt.t)+'</span></div>'+
  '<div class="rc-st" style="--dc:'+dt.c+'">'+starsOn+'<span class="off">'+starsOff+'</span> 危险度 '+r.d+'/5</div>'+
  '<p class="rc-d">'+esc(r.t)+'</p>'+
  '<p class="rc-tip">▸ 出生区域会写入存档「当前地点」，AI 将以此起笔你的苏醒场景。</p>';
}
function selectRegion(n){
 S.region=n;
 var rs=REGIONS[S.mapKey]||[];
 qsa('.rg-dot').forEach(function(d){
  var idx=parseInt(d.getAttribute('data-i'),10)||0;
  var r=rs[idx];
  var on=!!(r&&r.n===n);
  d.classList.toggle('sel',on);
  d.setAttribute('aria-pressed',on?'true':'false');
 });
 renderRegionList(rs);
 renderRegionCard();
 hideTip();
 scheduleDraft();
 updateHint();
}

/* ═══ STEP3 生存者档案：神墟式 chips 组件（＋自定义词条 / ✕ 删除） ═══ */
var CHIPCFG={
 era:{box:'#eraChips',presets:ERAS,customs:'eraCustoms',multi:false,def:'21世纪'},
 body:{box:'#bodyChips',presets:AP_BODY,customs:'bodyCustoms',multi:false,def:'匀称'},
 skin:{box:'#skinChips',presets:AP_SKIN,customs:'skinCustoms',multi:false,def:'小麦色'},
 hairColor:{box:'#hairChips',presets:AP_HAIRCOLOR,customs:'hairColorCustoms',multi:false,def:'深棕'},
 hairStyle:{box:'#styleChips',presets:AP_HAIRSTYLE,customs:'hairStyleCustoms',multi:false,def:'短发利落'},
 aura:{box:'#auraChips',presets:AP_AURA,customs:'auraCustoms',multi:true,max:3},
 traits:{box:'#trChips',presets:(function(){var a=[];for(var i=0;i<TRAITS.length;i++)a.push(TRAITS[i].n);return a;})(),customs:'traitsCustoms',multi:true,max:5}
};
function chipCurVal(key){
 if(key==='era')return S.era;
 if(key==='body')return S.body;
 if(key==='skin')return S.skin;
 if(key==='hairColor')return S.hairColor;
 if(key==='hairStyle')return S.hairStyle;
 return '';
}
function chipSetCurVal(key,v){
 if(key==='era')S.era=v;
 else if(key==='body')S.body=v;
 else if(key==='skin')S.skin=v;
 else if(key==='hairColor')S.hairColor=v;
 else if(key==='hairStyle')S.hairStyle=v;
}
function chipSelArr(key){
 if(key==='aura')return S.aura;
 if(key==='traits')return S.traits;
 return [];
}
function chipSetSelArr(key,arr){
 if(key==='aura')S.aura=arr;
 else if(key==='traits')S.traits=arr;
}
function chipInlineHTML(){
 return '<span class="chip-inline">'+
  '<input class="inp cin" type="text" maxlength="10" autocomplete="off" placeholder="输入词条后回车">'+
  '<button type="button" class="cok" aria-label="确认添加词条">✓</button>'+
  '</span>';
}
function renderChipSet(key){
 var cfg=CHIPCFG[key];
 var box=qs(cfg.box);
 if(!box)return;
 var customs=S[cfg.customs]||[];
 var h='';
 for(var i=0;i<cfg.presets.length;i++){
  var p=cfg.presets[i];
  var on=cfg.multi?has(chipSelArr(key),p):(chipCurVal(key)===p);
  h+='<button type="button" class="chip'+(on?' on':'')+'" data-v="'+esc(p)+'" aria-pressed="'+(on?'true':'false')+'">'+esc(p)+'</button>';
 }
 for(var j=0;j<customs.length;j++){
  var c=customs[j];
  var onc=cfg.multi?has(chipSelArr(key),c):(chipCurVal(key)===c);
  h+='<button type="button" class="chip chip-custom'+(onc?' on':'')+'" data-v="'+esc(c)+'" data-custom="1" aria-pressed="'+(onc?'true':'false')+'" title="点击切换选中 · ✕ 删除词条"><span class="cn">'+esc(c)+'</span><span class="cx" aria-label="删除词条 '+esc(c)+'">✕</span></button>';
 }
 if(box.__akInline)h+=chipInlineHTML();
 else h+='<button type="button" class="chip chip-addbtn" data-add="1" aria-label="添加自定义词条">＋ 自定义</button>';
 box.innerHTML=h;
 bindChipSet(key,box,cfg);
}
function bindChipSet(key,box,cfg){
 var inline=box.__akInline;
 qsa('.chip',box).forEach(function(b){
  b.addEventListener('click',function(ev){
   var tgt=ev.target;
   if(tgt&&tgt.classList&&tgt.classList.contains('cx')){
    ev.stopPropagation();
    removeCustomWord(key,b.getAttribute('data-v')||'');
    return;
   }
   if(b.getAttribute('data-add')==='1'){
    box.__akInline=true;
    renderChipSet(key);
    var cin=qs('.cin',box);
    if(cin){
     cin.focus();
     cin.addEventListener('keydown',function(e2){
      if(e2.key==='Enter'){e2.preventDefault();submitInlineWord(key,box,cfg);}
      else if(e2.key==='Escape'){box.__akInline=false;renderChipSet(key);}
     });
     var ok=qs('.cok',box);
     if(ok)ok.addEventListener('click',function(){submitInlineWord(key,box,cfg);});
    }
    return;
   }
   var v=b.getAttribute('data-v')||'';
   if(cfg.multi){
    var arr=chipSelArr(key).slice();
    var at=arr.indexOf(v);
    if(at>=0)arr.splice(at,1);
    else{
     if(cfg.max&&arr.length>=cfg.max){toast((key==='traits'?'最多选择 '+cfg.max+' 项性格特质':'最多选择 '+cfg.max+' 项气质'),true);return;}
     arr.push(v);
    }
    chipSetSelArr(key,arr);
    renderChipSet(key);
    updateTraitCount();
   }else{
    chipSetCurVal(key,v);
    renderChipSet(key);
   }
   scheduleDraft();
  });
 });
}
function submitInlineWord(key,box,cfg){
 var cin=qs('.cin',box);
 if(!cin)return;
 var v=trimmed(cin.value);
 if(!v){box.__akInline=false;renderChipSet(key);return;}
 addCustomWord(key,v);
}
function addCustomWord(key,v){
 var cfg=CHIPCFG[key];
 var customs=S[cfg.customs]||[];
 if(has(cfg.presets,v)||has(customs,v)){toast('该词条已存在',true);return;}
 customs.push(v);
 S[cfg.customs]=customs;
 var box=qs(cfg.box);
 if(box)box.__akInline=false;
 if(cfg.multi){
  var arr=chipSelArr(key).slice();
  if(!cfg.max||arr.length<cfg.max)arr.push(v);
  else toast('已添加词条（当前已选满，点击词条可替换）');
  chipSetSelArr(key,arr);
 }else{
  chipSetCurVal(key,v);
 }
 renderChipSet(key);
 updateTraitCount();
 scheduleDraft();
}
function removeCustomWord(key,v){
 var cfg=CHIPCFG[key];
 var customs=(S[cfg.customs]||[]).filter(function(x){return x!==v;});
 S[cfg.customs]=customs;
 if(cfg.multi){
  chipSetSelArr(key,chipSelArr(key).filter(function(x){return x!==v;}));
 }else if(chipCurVal(key)===v){
  chipSetCurVal(key,cfg.def);
 }
 renderChipSet(key);
 updateTraitCount();
 scheduleDraft();
 toast('已删除词条「'+v+'」');
}
function updateTraitCount(){
 var tc=qs('#trCnt');
 if(tc)tc.innerHTML='已选 <span class="on">'+S.traits.length+'</span> / 5';
 var mc=qs('#mateCnt');
 if(mc)mc.innerHTML=(S.mates.length?'已定 <span class="on">'+S.mates.length+'</span> / 3 名':'0–3 名');
}

