 }).join('');
 h+='<button type="button" class="idc custom'+(S.idKey==='__custom__'?' sel':'')+'" data-id="__custom__" aria-pressed="'+(S.idKey==='__custom__'?'true':'false')+'">'+
  '<span class="ic-e">✧</span><span class="ic-n">自定义身份</span><span class="ic-t">由你定义</span><span class="ic-s">自由输入 · 风味说明</span><span class="ic-ck">✓</span></button>';
