/* ═══ 同行队友（九字段：姓名/性别/身份/国籍/时代/性格/外貌/年龄/擅长 · V3.4.2『与主角关系』改『年龄』） ═══ */
function renderMates(){
 var zone=qs('#mateZone');
 if(!zone)return;
 if(!S.mates.length){
  zone.innerHTML='<p class="mate-empty">▸ 尚无队友 —— 独自苏醒，或点击下方按钮召唤与你一同坠入方舟的人（最多 3 名）。</p>';
 }else{
  zone.innerHTML=S.mates.map(function(m,i){
