     mateFieldText(i,'era',m.era,'时代','如：21世纪 / 汉朝',12)+
     mateFieldText(i,'personality',m.personality,'性格','如：沉稳寡言',16)+
     mateFieldText(i,'appearance',m.appearance,'外貌','如：高瘦灰眸短发',20)+
     mateFieldText(i,'age',m.age,'年龄','如：26岁',6)+
     mateFieldText(i,'skill',m.skill,'擅长','如：狩猎追踪 / 草药急救',16)+
    '</div></div>';
  }).join('');
  qsa('.mx',zone).forEach(function(b){
