/* ═══ STEP3 水合（静态骨架 + 一次性绑定） ═══ */
var profileBound=false;
function hydrateProfile(){
 var nm=qs('#fName');
 if(nm){
  if(!trimmed(S.name))S.name=randomName();
  if(document.activeElement!==nm)nm.value=S.name;
 }
 var gd=qs('#segGender');
 if(gd){
  qsa('.sgb',gd).forEach(function(b){
   var v=b.getAttribute('data-v');
   b.classList.toggle('on',S.gender===v);
   if(b.__akBnd)return;
   b.__akBnd=true;
   b.addEventListener('click',function(){
    S.gender=b.getAttribute('data-v')||'不指定';
    qsa('.sgb',gd).forEach(function(x){x.classList.toggle('on',x===b);});
    scheduleDraft();
   });
  });
 }
 var fa=qs('#fAge');
 if(fa&&document.activeElement!==fa)fa.value=String(S.age);
 renderIdentityGrid();
 var cn=qs('#idCustomName'),ce=qs('#idCustomNote');
 if(cn&&document.activeElement!==cn)cn.value=S.idCustom;
 if(ce&&document.activeElement!==ce)ce.value=S.idNote;
 for(var key in CHIPCFG)renderChipSet(key);
 var tn=qs('#fTraitNote');
 if(tn&&document.activeElement!==tn)tn.value=S.traitNote;
 var fh=qs('#fHeight'),fw=qs('#fWeight');
 if(fh&&document.activeElement!==fh)fh.value=String(S.heightCm);
 if(fw&&document.activeElement!==fw)fw.value=String(S.weightKg);
 var mk=qs('#fMarks');
 if(mk&&document.activeElement!==mk)mk.value=S.marks;
 var ap=qs('#fApText');
 if(ap&&document.activeElement!==ap)ap.value=S.apText;
 var st=qs('#fStory');
 if(st&&document.activeElement!==st)st.value=S.story;
 renderMates();
 updateTraitCount();
 updateTextCounters();
 if(!profileBound){
  profileBound=true;
  if(nm)nm.addEventListener('input',function(){S.name=nm.value;updateHint();scheduleDraft();});
  var rr=qs('#btnReroll');
  if(rr)rr.addEventListener('click',function(){
   S.name=randomName();
   if(nm)nm.value=S.name;
   scheduleDraft();
   toast('已随机生成新姓名：'+S.name);
  });
  if(fa)fa.addEventListener('input',function(){
   var v=parseInt(fa.value,10);
   if(isNaN(v))v=25;
   v=Math.max(16,Math.min(60,v));
   S.age=v;
   scheduleDraft();
  });
  if(cn)cn.addEventListener('input',function(){S.idCustom=cn.value;scheduleDraft();});
  if(ce)ce.addEventListener('input',function(){S.idNote=ce.value;scheduleDraft();});
  if(tn)tn.addEventListener('input',function(){S.traitNote=tn.value;updateTextCounters();scheduleDraft();});
  if(fh)fh.addEventListener('input',function(){
   var v=parseInt(fh.value,10);
   if(isNaN(v))v=170;
   S.heightCm=Math.max(120,Math.min(230,v));
   scheduleDraft();
  });
  if(fw)fw.addEventListener('input',function(){
   var v=parseInt(fw.value,10);
   if(isNaN(v))v=65;
   S.weightKg=Math.max(30,Math.min(200,v));
   scheduleDraft();
  });
  if(mk)mk.addEventListener('input',function(){S.marks=mk.value;scheduleDraft();});
  if(ap)ap.addEventListener('input',function(){S.apText=ap.value;updateTextCounters();scheduleDraft();});
  if(st)st.addEventListener('input',function(){S.story=st.value;updateTextCounters();scheduleDraft();});
  var ma=qs('#mateAdd');
  if(ma)ma.addEventListener('click',addMate);
 }
}
