/* ═══ STEP5 初始属性 ═══ */
function renderStats(){
 var bud=qs('#stBud');
 if(bud)bud.textContent=String(budget()-allocTotal());
 var src=qs('#stSrc');
 if(src){
  var md=null;
  for(var i=0;i<MODES.length;i++)if(MODES[i].v===S.mode)md=MODES[i];
  src.innerHTML='预算来源：<b>'+esc(S.mode)+'</b> <span class="k">'+(md?md.bud:3)+'点</span>'+
   ' · 等级 <span class="k">Lv'+modeLv()+'</span><br>已用 <span class="k">'+allocTotal()+'</span> / <span class="k">'+budget()+'</span> 点 —— 加点按 ARK 公式即时演算，剩余点苏醒后可在 HUD 继续分配。';
 }
 var rows=qs('#stRows');
 if(!rows)return;
 rows.innerHTML=STAT_KEYS.map(function(k){
  var info=statInfo(k);
  var pts=S.alloc[k]||0;
  var val=statCompute(k,pts);
  var base=statCompute(k,0);
  var usedUp=(allocTotal()>=budget());
  return '<div class="st-row'+(pts>0?' hl':'')+'">'+
   '<span class="sr-n"><span class="ic">'+info.icon+'</span>'+esc(k)+'<span class="pv">+'+info.per+info.unit+'</span></span>'+
   '<span class="sr-d">'+esc(info.desc)+'</span>'+
   '<span class="sr-v"><span class="b">'+base+info.unit+'</span><span class="ar">➔</span><span class="a'+(pts>0?'':' zero')+'">'+val+info.unit+'</span></span>'+
   '<span class="sr-b"><button type="button" class="sbtn" data-m="'+esc(k)+'" aria-label="回收一点'+esc(k)+'"'+(pts<=0?' disabled':'')+'>−</button><span class="sr-pts">'+(pts>0?'+'+pts:'·')+'</span><button type="button" class="sbtn" data-p="'+esc(k)+'" aria-label="分配一点'+esc(k)+'"'+(usedUp?' disabled':'')+'>＋</button></span>'+
   '</div>';
 }).join('');
 qsa('.sbtn',rows).forEach(function(b){
  b.addEventListener('click',function(){
   if(b.hasAttribute('data-p'))allocPlus(b.getAttribute('data-p'));
   else allocMinus(b.getAttribute('data-m'));
  });
 });
 renderStatSum();
}
function allocPlus(k){
 if(allocTotal()>=budget()){toast('属性点已用完',true);return;}
 S.alloc[k]=(S.alloc[k]||0)+1;
 allocLog.push(k);
 renderStats();
 scheduleDraft();
}
function allocMinus(k){
 if(!S.alloc[k])return;
 S.alloc[k]--;
 if(S.alloc[k]<=0)delete S.alloc[k];
 for(var i=allocLog.length-1;i>=0;i--){
  if(allocLog[i]===k){allocLog.splice(i,1);break;}
 }
 renderStats();
 scheduleDraft();
}
function clampAlloc(){
 var over=allocTotal()-budget();
 while(over>0&&allocLog.length){
  var k=allocLog[allocLog.length-1];
  allocLog.pop();
  if(S.alloc[k]>0){
   S.alloc[k]--;
   if(S.alloc[k]<=0)delete S.alloc[k];
   over--;
  }
 }
 if(over>0){
  for(var kk in S.alloc){delete S.alloc[kk];}
  allocLog=[];
 }
}
function renderStatSum(){
 var el=qs('#stSum');
 if(!el)return;
 var parts=[];
 STAT_KEYS.forEach(function(k){
  if(S.alloc[k])parts.push(esc(k)+'+'+S.alloc[k]+'（'+statCompute(k,S.alloc[k])+statInfo(k).unit+'）');
 });
 el.innerHTML='<b>已分配 '+allocTotal()+' / '+budget()+' 点</b>'+(parts.length?' —— '+parts.join(' · '):' —— 尚未分配（点数将保留至苏醒后）');
}

