/* ═══ STEP6 追加补给（V3.4.1 预算制多选：最多 3 项，满额禁用其余 chip） ═══ */
function extraQty(v){
 for(var i=0;i<EXTRAS.length;i++)if(EXTRAS[i].v===v)return EXTRAS[i].n;
 return 1;
}
function extrasDisplay(){
 return (S.extras||[]).map(function(v){return v+'×'+extraQty(v);});
}
function renderExtras(){
 var box=qs('#exChips');
 if(!box)return;
 var full=(S.extras||[]).length>=3;
 box.innerHTML=EXTRAS.map(function(x){
  var on=has(S.extras,x.v);
  var dis=!on&&full;
  return '<button type="button" class="chip'+(on?' on':'')+'" data-v="'+esc(x.v)+'"'+(dis?' disabled':'')+' aria-pressed="'+(on?'true':'false')+'">'+esc(x.v)+'×'+x.n+'</button>';
 }).join('');
 qsa('.chip',box).forEach(function(b){
  b.addEventListener('click',function(){
   var v=b.getAttribute('data-v')||'';
   if(has(S.extras,v)){
    S.extras=S.extras.filter(function(x){return x!==v;});
    renderExtras();
    scheduleDraft();
    toast('已取消追加「'+v+'×'+extraQty(v)+'」');
   }else{
    if(S.extras.length>=3){toast('追加补给最多 3 项（已选满）',true);return;}
    S.extras.push(v);
    renderExtras();
    scheduleDraft();
    toast('已追加「'+v+'×'+extraQty(v)+'」—— 计入初始物品');
   }
  });
 });
 var note=qs('#exNote');
 if(note){
  var exTail=(S.pack==='无初始装备')?'空投另行投放的额外补给，计入初始物品':'行囊之外的额外补给，计入初始物品，开局叙事中随行囊拾取';
  note.innerHTML=(S.extras||[]).length
   ?'▸ 已选 '+S.extras.length+' / 3 项：'+esc(extrasDisplay().join('、'))+' —— '+exTail+'。'
   :'▸ '+exTail+' —— 最多选 3 项，不选亦可。';
 }
}

