function addCustomPref(inp){
 var v=trimmed(inp.value);
 if(!v){toast('先输入偏好再添加',true);return;}
 if(has(PREFS,v)||has(S.prefsCustom,v)){toast('该偏好已存在',true);return;}
 if(S.prefsCustom.length>=4){toast('自定义偏好最多 4 个',true);return;}
 S.prefsCustom.push(v);
 if(S.prefs.length<5)S.prefs.push(v);
 inp.value='';
 renderPrefChips();
 scheduleDraft();
}
function renderPrefChips(){
 var box=qs('#pfChips');
 if(!box)return;
 var h='';
 PREFS.forEach(function(p){
  var on=has(S.prefs,p);
  h+='<button type="button" class="chip'+(on?' on':'')+'" data-p="'+esc(p)+'" aria-pressed="'+(on?'true':'false')+'">'+esc(p)+'</button>';
 });
 S.prefsCustom.forEach(function(c){
  var on=has(S.prefs,c);
  h+='<button type="button" class="chip chip-custom'+(on?' on':'')+'" data-p="'+esc(c)+'" data-custom="1" aria-pressed="'+(on?'true':'false')+'"><span class="cn">'+esc(c)+'</span><span class="cx" aria-label="删除词条">✕</span></button>';
 });
 box.innerHTML=h;
 qsa('.chip',box).forEach(function(b){
  b.addEventListener('click',function(ev){
   var tgt=ev.target;
   if(tgt&&tgt.classList&&tgt.classList.contains('cx')){
    ev.stopPropagation();
    var v0=b.getAttribute('data-p')||'';
    S.prefsCustom=S.prefsCustom.filter(function(x){return x!==v0;});
    S.prefs=S.prefs.filter(function(x){return x!==v0;});
    renderPrefChips();
    scheduleDraft();
    toast('已移除自定义偏好「'+v0+'」');
    return;
   }
   var v=b.getAttribute('data-p');
   if(has(S.prefs,v))S.prefs=S.prefs.filter(function(x){return x!==v;});
   else{
    if(S.prefs.length>=5){toast('最多选择 5 项玩法偏好',true);return;}
    S.prefs.push(v);
   }
   renderPrefChips();
   scheduleDraft();
  });
 });
}

