function appearanceFinal(){
 var w=trimmed(S.apText);
 if(w)return w;
 var parts=[];
 parts.push('身高'+S.heightCm+'cm、体重'+S.weightKg+'kg');
 if(S.body)parts.push('体型'+S.body);
 if(S.skin)parts.push(S.skin+'肤色');
 if(S.hairColor&&S.hairStyle)parts.push(S.hairColor+'发·'+S.hairStyle);
 else if(S.hairColor)parts.push(S.hairColor+'发');
 if(S.aura.length)parts.push('气质'+S.aura.join('、'));
 var mk=trimmed(S.marks);
 return '克隆体外观：'+parts.join('；')+'。'+(mk?'特殊标记：'+mk+'。':'')+'（白描未提供，AI 按上述特征补写）';
}
function validMates(){
 return (S.mates||[]).filter(function(m){return !!trimmed(m.name);});
}
function petFinal(){
 if(!S.pet||S.pet==='无')return null;
 if(S.pet===PET_CUSTOM){
  var sp=trimmed(S.petCustom);
  if(!sp)return null; /* 自定义未填物种名 → 按孤狼开局 */
  return {name:trimmed(S.petName)||sp,species:sp,level:PET_CUSTOM_LV,custom:true};
 }
 var lv=1;
 for(var i=0;i<PETS.length;i++)if(PETS[i].v===S.pet)lv=parseInt(String(PETS[i].lv).replace('Lv',''),10)||1;
 return {name:trimmed(S.petName)||S.pet,species:S.pet,level:lv};
}
function reviveDescOf(v){
 for(var i=0;i<REVIVES.length;i++)if(REVIVES[i].v===v)return ' —— '+REVIVES[i].d;
 return '';
}
function scenarioLabelOf(){
 return (S.scenario===SCN_CUSTOM)?'自定义':(S.scenario||'标准海滩苏醒');
}
