/* ═══ 全量档案对象（三通道共用数据源） ═══ */
function buildProfile(){
 var rs=REGIONS[S.mapKey]||[];
 var spawn=S.region||(rs.length?rs[0].n:'南部海滩'); /* 兜底与引擎默认口径一致 */
 var p=PACKS[S.pack]||PACKS['采集者'];
 var items={};
 for(var k in p.items)items[k]=p.items[k];
 var mysteryItems=[];
 for(var i=0;i<S.cheats.length;i++){
  var cv=S.cheats[i];
  var cdef=null;
  for(var j=0;j<CHEATS.length;j++)if(CHEATS[j].v===cv)cdef=CHEATS[j];
  if(!cdef)continue;
  if(cv==='神秘行囊'){
   var pool=MYSTERY_POOL.slice();
   for(var n=0;n<2&&pool.length;n++){
    var idx=Math.floor(mul(Math.random(),pool.length));
    var it=pool.splice(idx,1)[0];
    mysteryItems.push(it);
    items[it]=(items[it]||0)+1;
   }
  }else{
   for(var k2 in cdef.items)items[k2]=(items[k2]||0)+cdef.items[k2];
  }
 }
 var statsAlloc={};
 for(var k3 in S.alloc)if(S.alloc[k3]>0)statsAlloc[k3]=S.alloc[k3];
 /* V3.4.1：追加补给并入初始物品（引擎 addItem 记账，叙事中随行囊或空投拾取，绝境开局同样合法）。
    manifestItems = 补给并入前快照（装备包/资助清单），避免「追加补给」在正文重复罗列 */
 var manifest={};
 for(var mk in items)manifest[mk]=items[mk];
 var extrasArr=[];
 for(var e=0;e<(S.extras||[]).length;e++){
  var ev=S.extras[e];
  if(has(extrasArr,ev))continue;
  extrasArr.push(ev);
  items[ev]=(items[ev]||0)+extraQty(ev);
 }
 var extrasList=extrasArr.map(function(v){return v+'×'+extraQty(v);});
 var mates=validMates().map(function(m){
  return {
   name:trimmed(m.name),
   gender:m.gender||'不指定',
   identity:trimmed(m.identity)||'生存者',
   nationality:trimmed(m.nationality)||'未知',
   era:trimmed(m.era)||'21世纪',
   personality:trimmed(m.personality)||'坚毅',
   appearance:trimmed(m.appearance)||'',
   age:trimmed(m.age)||'',
   skill:trimmed(m.skill)||''
  };
 });
 var scenarioLabel=(S.scenario===SCN_CUSTOM)?'自定义':(S.scenario||'标准海滩苏醒');
 var scenarioText=(S.scenario===SCN_CUSTOM)?trimmed(S.scenarioText):'';
 return {
  v:3, createdAt:Date.now(),
  name:trimmed(S.name)||'未命名生存者',
  gender:S.gender, age:S.age,
  identity:identityFinal(), identityKey:S.idKey, identityNote:trimmed(S.idNote),
  era:eraFinal(),
  traits:S.traits.slice(), traitNote:trimmed(S.traitNote),
  appearance:{
   heightCm:S.heightCm, weightKg:S.weightKg,
   body:S.body, skin:S.skin, hairColor:S.hairColor, hairStyle:S.hairStyle,
   aura:S.aura.slice(), marks:trimmed(S.marks), apText:trimmed(S.apText)
  },
  appearanceText:appearanceFinal(),
  story:trimmed(S.story),
  map:mapName()||'孤岛', mapKey:S.mapKey||'island', spawn:spawn,
  difficulty:S.diff, mode:S.mode, style:S.style,
  prefs:S.prefs.slice(),
  pack:S.pack, items:items, manifestItems:manifest, engrams:p.eng.slice(),
  pet:petFinal(),
  cheats:S.cheats.slice(), mysteryItems:mysteryItems,
  scenario:scenarioLabel, scenarioText:scenarioText,
  scenarioEntry:((scenarioLabel==='自定义'&&scenarioText)?scenarioText.slice(0,200):scenarioLabel),
  revive:S.revive||'标准',
  extras:extrasList,
  mates:mates,
  alloc:statsAlloc, level:modeLv(),
  statsLeft:Math.max(0,budget()-allocTotal())
 };
}

/* ═══ 通道一：引擎档（ARK_CORE.initState + mergeState 叙事补丁） ═══ */
function buildCoreCfg(p){
 return {
  mode:p.mode,
  map:p.map,
  spawn:p.spawn,
  difficulty:p.difficulty,
  preferences:p.prefs,
  cheats:p.cheats,
  name:p.name,
  gender:p.gender,
  age:p.age,
  identity:p.identity,
  era:p.era,
  personality:p.traits.length?p.traits.join('、'):'未指定',
  background:p.story,
  currentStatus:'初醒·赤裸',
  appearance:p.appearanceText,
  level:p.level,
  statsAlloc:p.alloc,
  statsLeft:p.statsLeft,
  items:p.items,
  engrams:p.engrams,
  pet:p.pet,
  reviveMode:p.revive||'标准',
  scenario:p.scenarioEntry||p.scenario||'标准海滩苏醒',
  extras:(p.extras||[]).slice(0,10),
  mates:p.mates.map(function(m){
   return {name:m.name,gender:m.gender,nationality:m.nationality,age:m.age||'',identity:m.identity,personality:m.personality,skill:m.skill||'',era:m.era,appearance:m.appearance||''};
  }),
  weather:'晴朗'
 };
}
async function commitEngine(p){
 var core=COREAPI();
 if(!core||typeof core.initState!=='function'){
  try{localStorage.setItem('ark21-pending-create',JSON.stringify(buildCoreCfg(p)));}catch(e){}
  return {ok:false,pending:true,reason:'ARK 引擎未加载'};
 }
 try{
  core.initState(buildCoreCfg(p));
  var patch={};
  var ps={};
  ps['年龄']=p.age;
  ps['时代背景']=p.era;
  ps['性格特质']=p.traits.length?p.traits.join('、'):'未指定';
  if(p.story)ps['出身背景']=p.story;
  ps['经验']=0;
  ps['属性点']=p.statsLeft;
  ps['当前状态']='初醒·赤裸';
  patch['主角_生存状态']=ps;
  if(p.mates.length){
   var tbm={};
   p.mates.forEach(function(m){tbm[m.name]={时代:m.era,好感度:55};});
   patch['部落系统']={成员:tbm};
  }
  try{core.mergeState(patch);}catch(e2){}
  return {ok:true};
 }catch(e){
  return {ok:false,reason:'引擎写入异常'};
 }
}

/* ═══ 通道二：MVU 变量直写（神墟桥：状态源映射） ═══ */
