function withTimeout(promise,ms){
 return new Promise(function(resolve){
  var done=false;
  var t=setTimeout(function(){
   if(!done){done=true;resolve({ok:false,reason:'等待超时'});}
  },ms);
  Promise.resolve(promise).then(function(v){
   if(!done){done=true;clearTimeout(t);resolve(v);}
  },function(e){
   if(!done){done=true;clearTimeout(t);resolve({ok:false,reason:(e&&e.message)||'异常'});}
  });
 });
}
async function commitMvu(p){
 var mvu=getApi('Mvu');
 if(!mvu||!mvu.getMvuData||typeof mvu.replaceMvuData!=='function')return {ok:false,reason:'未检测到 MVU 框架'};
 var waitFn=getApi('waitGlobalInitialized');
 if(typeof waitFn==='function'){
  try{await withTimeout(waitFn('Mvu'),2500);}catch(e){}
 }
 var data=null;
 try{data=mvu.getMvuData({type:'message',message_id:'latest'});}catch(e2){}
 if(!data||!data.stat_data){
  /* V2.3.1：首楼尚无变量（开局界面楼层）—— 从引擎档构建状态源基础再写入 */
  var core=null;
  try{core=window.parent.ARK_CORE||window.ARK_CORE||null;}catch(eC){}
  if(core&&core.getState){
   try{
    var st=core.getState();
    data=data||{};
    data.stat_data=JSON.parse(JSON.stringify(st));
   }catch(eC2){}
  }
  if(!data||!data.stat_data)return {ok:false,reason:'MVU 数据不可读且引擎档缺失'};
 }
 try{
  mergeStatData(data.stat_data,p);
  await mvu.replaceMvuData(data,{type:'message',message_id:'latest'});
  return {ok:true};
 }catch(e3){
  return {ok:false,reason:(e3&&e3.message)||'MVU 回写失败'};
 }
}

/* ═══ 通道三：世界书写入（[生存者档案] 条目 + [地图] 条目激活） ═══ */
async function commitWorldbook(p){
 var TH=getApi('TavernHelper');
 if(!TH||!TH.getCharWorldbookNames)return {ok:false,reason:'TavernHelper 不可用（酒馆助手未授权或未启用）'};
 var wbs=null;
 try{wbs=TH.getCharWorldbookNames('current');}catch(e0){}
 var wbName=wbs&&(wbs.primary||(wbs.additional||[])[0]);
 var entries=[];
 if(wbName){try{entries=await TH.getWorldbook(wbName)||[];}catch(e1){}}
 /* V3.3：未绑定世界书时，优先把卡内嵌 character_book 完整导入并绑定
    （ST 不会自动导入内嵌书；此前只补建12条速览会导致AI看不到完整世界观） */
 var createdBook=false;
 if(!wbName||!entries.length){
  var emb=null,embName='';
  try{
   var ctx=getCtx();
   var ch=ctx&&ctx.characters&&ctx.characters[ctx.characterId];
   emb=ch&&ch.data&&ch.data.character_book;
   embName=(emb&&emb.name)||((ch&&ch.name)?(ch.name+' Lorebook'):'方舟V3.4');
  }catch(eE){}
  if(emb&&emb.entries&&emb.entries.length){
   try{
    /* V3.4.3 防复制修复（严重BUG：首次开局曾把世界书大量条目整份复制一遍）
       根因三连：
       ① TH.createWorldbook 同名世界已存在时静默返回 false 不清空；
       ② TH.createWorldbookEntries 是纯追加语义；两者连用 → 已有156条再追加156条；
       ③ 内嵌书旧名(方舟V3.3)与绑定名(方舟V3.4)分叉 → 另存一份完整世界书。
       修复：目标名优先沿用绑定名；世界不存在→原子创建；已有条目→按名称
       去重仅补缺失，并对世界内同名重复条目自愈去重（保留首份）。 */
    var target=wbName||embName;
    var knownNames=[];
    try{knownNames=TH.getWorldbookNames()||[];}catch(eN0){}
    var worldExists=(knownNames.indexOf(target)>=0);
    var existEnt=[];
    if(worldExists){try{existEnt=await TH.getWorldbook(target)||[];}catch(eG0){}}
    /* V2 character_book 条目 → TH WorldbookEntry */
    var conv=emb.entries.map(function(e){
     var ext=(e&&e.extensions)||{};
     var pos={type:'before_character_definition',depth:ext.depth!=null?ext.depth:4,role:'system',order:e.insertion_order||100};
     if(ext.position===1)pos={type:'after_character_definition',depth:ext.depth||0,role:'system',order:e.insertion_order||100};
     else if(ext.position===4)pos={type:'at_depth',depth:ext.depth||4,role:'system',order:e.insertion_order||100};
     else if(ext.position===2)pos={type:'before_author_note',depth:ext.depth||4,role:'system',order:e.insertion_order||100};
     else if(ext.position===3)pos={type:'after_author_note',depth:ext.depth||4,role:'system',order:e.insertion_order||100};
     else if(e.position==='after_char')pos={type:'after_character_definition',depth:ext.depth||0,role:'system',order:e.insertion_order||100};
     var strat=e.constant?{type:'constant',keys:[]}:{type:'selective',keys:e.keys||[],keys_secondary:{logic:'and_any',keys:e.secondary_keys||[]}};
     return {
      name:e.comment||('条目'+(e.id||'')),
      content:e.content||'',
      enabled:e.enabled!==false,
      position:pos,
      strategy:strat,
      probability:(ext.probability!=null?ext.probability:100),
      recursion:{prevent_incoming:!!ext.prevent_recursion,prevent_outgoing:!!ext.exclude_recursion,delay_until:ext.delay_until_recursion?'1':null},
      effect:{sticky:ext.sticky||null,cooldown:ext.cooldown||null,delay:ext.delay||null}
     };
    });
    if(!worldExists){
     /* 原子创建：仅当世界不存在时创建并一次性写入全部条目 */
     await TH.createWorldbook(target,conv);
    }else if(!existEnt.length){
     /* 存在但为空 → 首次填充 */
     await TH.createWorldbookEntries(target,conv);
    }else{
     /* 已有条目：按名称去重，仅补缺失 —— 绝不整份追加（防复制核心） */
     var have={};
     existEnt.forEach(function(x){if(x&&x.name)have[x.name]=1;});
     var missing=conv.filter(function(x){return !have[x.name];});
     if(missing.length){
      try{await TH.createWorldbookEntries(target,missing);}catch(eM){}
     }
     /* 自愈：世界内同名重复条目（历史复制残留）去重，保留首份 */
     var seenNames={},healed=[],dupFound=false;
     existEnt.forEach(function(x){
      var nm=(x&&x.name)||('uid'+(x&&x.uid));
      if(seenNames[nm]){dupFound=true;return;}
      seenNames[nm]=1;healed.push(x);
     });
     if(dupFound&&healed.length){
      try{await TH.replaceWorldbook(target,healed);}catch(eH){}
     }
    }
    await TH.rebindCharWorldbooks('current',{primary:target,additional:[]});
    wbName=target;
    createdBook='embedded';
    try{entries=await TH.getWorldbook(wbName)||[];}catch(eE2){}
    window.__arkEmbOk=(entries.length>=100); /* 内嵌书完整导入成功 → 不再补建速览 */
   }catch(eE3){/* 内嵌书导入失败 → 走速览兜底 */}
  }
 }
 if(!wbName)wbName='方舟V3.4';
 var allNames=[];
 try{allNames=TH.getWorldbookNames()||[];}catch(eN){}
 if(allNames.indexOf(wbName)<0){
  try{await TH.createWorldbook(wbName,[]);createdBook=true;}catch(eC){}
 }else if(!entries.length){
  /* V3.4.3：先实测世界内容再定性——「世界已存在且完整」不应被误报为补建兜底
     （绑定丢失场景下 entries 尚未加载，直接 getWorldbook 实测） */
  try{entries=await TH.getWorldbook(wbName)||[];}catch(eG2){}
  if(!entries.length)createdBook=true; /* 确实为空才补建地图条目 */
 }
 if(createdBook&&!(window.__arkEmbOk)){
  /* 兜底：内嵌书导入失败时补建 12 条「世界观/区域/地图_区域速览」条目 —— 文本来自引擎 MAP_LORE */
  var core=null;
  try{core=window.parent.ARK_CORE||window.ARK_CORE||null;}catch(eC0){}
  var mapLore=(core&&core.mapLore)?core.mapLore():null;
  if(mapLore&&mapLore[p.map]){
   var mkEntries=[];
   var mi=0;
   for(var mn in mapLore){
    mkEntries.push({
     name:'世界观/区域/'+mn+'_区域速览',
     content:mapLore[mn],
     enabled:mn===p.map,
     position:{type:'before_character_definition',depth:4,role:'system',order:3},
     strategy:{type:'constant',keys:[]},
     probability:100,
     recursion:{prevent_incoming:true,prevent_outgoing:false,delay_until:null},
     effect:{sticky:null,cooldown:null,delay:null}
    });
    mi++;
   }
   /* V3.4.3 防复制：兜底速览同样按名称去重 —— 世界已有同名条目时不再追加（含导入异常后重试场景） */
   try{
    var curEnt=[];
    try{curEnt=await TH.getWorldbook(wbName)||[];}catch(eG1){}
    var haveMap={};
    curEnt.forEach(function(x){if(x&&x.name)haveMap[x.name]=1;});
    var addEntries=mkEntries.filter(function(x){return !haveMap[x.name];});
    if(addEntries.length)await TH.createWorldbookEntries(wbName,addEntries);
   }catch(eC2){}
  }
  /* 重新绑定到角色 */
  try{await TH.rebindCharWorldbooks('current',{primary:wbName,additional:[]});}catch(eC3){}
  try{entries=await TH.getWorldbook(wbName)||[];}catch(eC4){}
 }
 var profName='[生存者档案]'+p.name;
 var exist=null;
 for(var i=0;i<entries.length;i++){
  if(entries[i]&&entries[i].name===profName){exist=entries[i];break;}
 }
 var entry={
  name:profName,
  content:buildProfileText(p),
  enabled:true,
  position:{type:'after_character_definition',depth:0,role:'system',order:100},
  strategy:{type:'constant',keys:[]},
  /* 双防递归：非递归扫描 + 防止进一步递归全开（与上方地图速览条目同款写法） */
  recursion:{prevent_incoming:true,prevent_outgoing:true,delay_until:null},
  extra:{arkProfile:p}
 };
 if(exist){
  entry.uid=exist.uid;
  /* V3.4.3：同名档案条目若因历史复制出现多份，仅保留首份（防重复注入/uid冲突） */
  var seenProf=false;
  var mapped=entries.filter(function(x){
   if(x&&x.name===profName){if(seenProf)return false;seenProf=true;}
   return true;
  }).map(function(x){return x.name===profName?entry:x;});
  await TH.replaceWorldbook(wbName,mapped);
 }else{
  await TH.createWorldbookEntries(wbName,[entry]);
 }
 var updated=[];
 try{updated=await TH.getWorldbook(wbName)||[];}catch(e2){}
 var changed=false;
 var MAP_SET={'孤岛':1,'仙境':1,'焦土':1,'畸变':1,'灭绝':1,'创世纪1':1,'创世纪2':1,'中心岛':1,'瓦尔盖罗':1,'水晶岛':1,'迷失岛':1,'菲尤尔':1};
 updated.forEach(function(x){
  /* V3.3：按「世界观/区域/地图_」「世界观/事件/地图_」前缀启停（兼容旧 [地图] 前缀） */
  var nm=x&&x.name?x.name:'';
  var isMap=false,ofMap='';
  var mPre=nm.match(/^世界观\/(?:区域|事件)\/([^_]+)_/);
  if(mPre&&MAP_SET[mPre[1]]){isMap=true;ofMap=mPre[1];}
  else if(nm.indexOf('[地图]')===0){
   isMap=true;
   for(var mk in MAP_SET){if(nm.indexOf('[地图]'+mk)===0){ofMap=mk;break;}}
  }
  if(!isMap)return;
  var should=(ofMap===p.map);
  if(!!x.enabled!==should){x.enabled=should;changed=true;}
 });
 if(changed)await TH.replaceWorldbook(wbName,updated);
 return {ok:true,entry:profName,map:p.map,created:createdBook,total:updated.length};
}

/* ═══ 世界书档案纯文本（全量） ═══ */
function buildProfileText(p){
 var L=[];
 L.push('【生存者档案】'+p.name+'（'+p.gender+' · '+p.age+'岁 · '+p.era+'人）');
 L.push('身份：'+p.identity);
 L.push('性格特质：'+(p.traits.length?p.traits.join('、'):'未指定'));
 if(p.traitNote)L.push('性格补充：'+p.traitNote);
 var ap=p.appearance||{};
 L.push('外貌：身高'+ap.heightCm+'cm、体重'+ap.weightKg+'kg；体型'+ap.body+'；肤色'+ap.skin+'；'+ap.hairColor+'发·'+ap.hairStyle+'；'+(ap.aura&&ap.aura.length?('气质'+ap.aura.join('、')+'；'):'')+(ap.marks?('特殊标记：'+ap.marks):''));
 if(ap.apText)L.push('外貌白描：'+ap.apText);
 else L.push('外貌白描：未提供——由 AI 按上述特征补写。');
 L.push('出身背景：'+(p.story||'未提供——由 AI 自由编织，须与身份/时代自洽。'));
 L.push('──────────');
 L.push('开局状态：'+p.map+' · '+p.spawn+'苏醒；等级 Lv'+p.level+'；属性点剩余 '+p.statsLeft+'（未分配点保留）。');
 var its=[];
 var mSrc=p.manifestItems||p.items;
 for(var k in mSrc)its.push(k+'×'+mSrc[k]);
 if(p.pack==='无初始装备'){
  /* 绝境开局：不写括号清单 → 引擎 parseOpeningCfg 装备包/印痕行均不命中 → 不加任何物品与印痕（契约对齐） */
  L.push('装备包：无初始装备 —— 苏醒点无行囊，绝境开局，一切从零开始。');
  L.push('预解锁印痕：无。');
 }else{
  L.push('装备包：'+p.pack+'（'+its.join('、')+'）；预解锁印痕：'+(p.engrams.length?p.engrams.join('、'):'无')+'。');
 }
 L.push('追加补给：'+((p.extras&&p.extras.length)?p.extras.join('、'):'无')+'。'+(p.pack==='无初始装备'?'（空投另行投放的额外补给，已计入初始物品）':'（行囊之外的额外补给，已计入初始物品）'));
 L.push('初始宠物：'+(p.pet?(p.pet.name+'（'+p.pet.species+' · Lv'+p.pet.level+'）'):'无。'));
 if(p.cheats.length){
  var cd=[];
  for(var c=0;c<p.cheats.length;c++)cd.push(p.cheats[c]);
  L.push('苏醒资助（玩家主动选择）：'+cd.join('、')+(p.mysteryItems&&p.mysteryItems.length?'；其中神秘行囊内容：'+p.mysteryItems.join('、')+'（苏醒叙事中揭示）':'')+'。');
 }
 if(p.mates.length){
  var ms=[];
  p.mates.forEach(function(m){
   /* 分隔符不带空格：与引擎 parseOpeningCfg 队友正则（…·性格…）严格对齐，回放不丢队友；
      『年龄』段位于外貌之后、擅长之前，无值跳过（引擎契约同格式） */
   var seg=m.name+'（'+m.gender+'·'+m.nationality+'·'+m.era+'·'+m.identity+'·性格'+m.personality;
   if(m.appearance)seg+='·外貌'+m.appearance;
   if(m.age)seg+='·年龄'+m.age;
   if(m.skill)seg+='·擅长'+m.skill;
   ms.push(seg+'）');
  });
  L.push('同行队友：'+ms.join('；')+'。');
 }else{
  L.push('同行队友：无（独自苏醒）。');
 }
 L.push('复活模式：'+(p.revive||'标准')+'。');
 L.push('开局场景：'+(p.scenario||'标准海滩苏醒')+'。');
 if(p.scenarioText)L.push('自定义场景：'+p.scenarioText+'（玩家自定义）。');
 L.push('游戏设定：'+p.difficulty+'难度 · '+p.mode+' · '+p.style+'叙事 · 偏好：'+(p.prefs.length?p.prefs.join('、'):'均衡生存')+'。');
 /* V3.4.4：白描化——去掉 [System Notice]/内部字段名（extra.arkProfile）等技术口径，只留对 AI 有用的两句指令 */
 L.push('请依据本档案与【开局协议】起笔苏醒叙事；后续 UpdateVariable 仅更新发生变化的变量字段。');
 return L.join('\n');
}

/* ═══ 开局指令（填入聊天框，绝不自动发送） ═══ */
function buildOpeningText(p,re,rw,rc){
 var id='E'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
 var marks=[];
 marks.push('【苏醒】编号='+id);
 marks.push('模式='+p.mode);
 marks.push('姓名='+p.name);
 marks.push('性别='+p.gender);
 marks.push('年龄='+p.age);
 marks.push('身份='+p.identity);
 marks.push('时代='+p.era);
 marks.push('性格='+(p.traits.length?p.traits.join('、'):'未指定'));
 marks.push('地图='+p.map);
 marks.push('出生点='+p.spawn);
 marks.push('难度='+p.difficulty);
 marks.push('复活='+(p.revive||'标准'));
 marks.push('场景='+(p.scenario||'标准海滩苏醒'));
 marks.push('风格='+p.style);
 marks.push('偏好='+(p.prefs.length?p.prefs.join('、'):'均衡生存'));
 marks.push('装备='+p.pack);
 marks.push('队友='+(p.mates.length?p.mates.length+'名（详见生存者档案）':'无'));
 marks.push('宠物='+(p.pet?(p.pet.name+'（'+p.pet.species+'Lv'+p.pet.level+'）'):'无'));
 var head=marks.join('；')+'。';
 /* V3.4.7：开局铁则（AI 直接读到的最强信号——装备/宠物选择必须严格映射到叙事） */
 var iron=[];
 iron.push('【开局铁则（叙事必须严格遵守）】');
 if(p.pack==='无初始装备'){
  var extraOnly=(p.extras&&p.extras.length)||(p.cheats&&p.cheats.length);
  iron.push('- 装备=无初始装备：主角苏醒时除'+(extraOnly?'（可选资助/补给对应的）空投物资外':'身上一无所有'));
  iron.push('  ——苏醒点没有任何行囊、工具、武器、衣物，绝不描写主角"摸到口袋里的XX""捡起身旁的行囊"；一切物资从零开始。');
 }else{
  var itNames=[];
  var mSrc2=p.manifestItems||p.items||{};
  for(var ik2 in mSrc2)itNames.push(ik2+'×'+mSrc2[ik2]);
  iron.push('- 装备='+p.pack+'：初始物品【'+(itNames.length?itNames.join('、'):'无')+'】收纳于散落在苏醒点附近的「苏醒行囊」，正文引导主角发现行囊时只出现这些物品，不多不少。');
 }
 if(p.pet){
  iron.push('- 初始宠物：'+p.pet.name+'（'+p.pet.species+' · Lv'+p.pet.level+'）已在主角身边苏醒——开局叙事必须让它登场（鸣叫/蹭近/警惕张望），后续剧情中它是常驻伙伴。');
 }else{
  iron.push('- 初始宠物=无：开局没有任何驯服生物陪伴主角，绝不描写"身边的宠物/伙伴动物"。');
 }
 if((p.revive||'标准')==='硬核'){
  iron.push('- 复活模式=硬核：完全不可复活——主角一旦死亡即本局终结（植入体烧毁），绝不描写重生/复活/苏醒重来；恐龙死亡同样永久消失。');
 }
 iron.push('- 等级/物品/印痕等数值已由引擎入账，你只需在叙事中体现上述装备与宠物设定，不要自行增删初始物品。');
 var ironText=iron.join('\n');
 /* V3.4.4：保存状态（✓/⚠）只给创建器完成面板与 toast 展示，绝不再拼进发给 AI 的开局指令 ——
    修复用户反馈“[System Notice] 生存者档案已保存（引擎档✓ / MVU变量✓ / 世界书✓）这种莫名其妙的东西发出去干嘛” */
 return head+'\n\n'+buildProfileText(p)+'\n\n'+ironText;
}

/* ═══ 聊天框填充（send_textarea 直填 → triggerSlash 兜底 → 复制兜底） ═══ */
function fillChatbox(text){
 try{
  var p=P();
  if(p&&p.document){
   var ta=p.document.getElementById('send_textarea');
   if(ta){
    ta.value=text;
    try{ta.dispatchEvent(new Event('input',{bubbles:true}));}catch(e2){}
    try{ta.dispatchEvent(new Event('change',{bubbles:true}));}catch(e3){}
    return {ok:true,via:'textarea'};
   }
  }
 }catch(e){}
 try{
  var run=getApi('triggerSlash');
  if(typeof run==='function'){
   run('/setinput '+JSON.stringify(text));
   return {ok:true,via:'slash'};
  }
 }catch(e4){}
 return {ok:false};
}

/* ═══ 复制（clipboard → execCommand 双通道） ═══ */
function copyText(text,okMsg){
 var done=function(){toast(okMsg||'已复制到剪贴板');};
 try{
  if(navigator.clipboard&&navigator.clipboard.writeText){
   navigator.clipboard.writeText(text).then(done,function(){legacyCopy(text,done);});
   return;
  }
 }catch(e){}
 legacyCopy(text,done);
}
function legacyCopy(text,done){
 try{
  var t=document.createElement('textarea');
  t.value=text;
  t.style.position='fixed';
  t.style.opacity='0';
  document.body.appendChild(t);
  t.select();
  var ok=false;
  try{ok=document.execCommand('copy');}catch(e2){ok=false;}
  document.body.removeChild(t);
  if(ok&&done)done();
  else toast('复制失败 —— 请长按 / 选中指令全文手动复制',true);
 }catch(e){
  toast('复制失败 —— 请长按 / 选中指令全文手动复制',true);
 }
}

