function showModal(title,text,note){
 var m=qs('#akModal');
 if(!m)return;
 var tt=qs('#mdTitle');
 if(tt)tt.textContent=title;
 var bd=qs('#mdBody');
 if(bd){
  bd.innerHTML='<div class="modal-infobar">'+note+'</div>'+
   '<pre class="modal-pre" id="mdPre">'+esc(text)+'</pre>'+
   '<p class="modal-note">▸ 这就是开局结算指令：发送后，AI 将按【开局协议】解析并以你的档案起笔苏醒场景。关闭本窗口也不怕 —— 成功横幅里仍有「复制开局指令」按钮。</p>'+
   '<div class="modal-acts"><button type="button" class="btn btn-pri" id="mdCopy">复制开局指令</button><button type="button" class="btn btn-ghost" id="mdShut">我已知晓</button></div>';
  var cp=qs('#mdCopy');
  if(cp)cp.addEventListener('click',function(){copyText(text,'开局指令已复制到剪贴板');});
  var sh=qs('#mdShut');
  if(sh)sh.addEventListener('click',closeModal);
 }
 m.hidden=false;
}
function closeModal(){
 var m=qs('#akModal');
 if(m)m.hidden=true;
