/* ═══ 确认苏醒：三通道写入链 ═══ */
async function doConfirm(){
 if(busy||created)return;
 busy=true;
 var btn=qs('#btnNext');
 if(btn){btn.disabled=true;btn.classList.add('busy');btn.textContent='正在写入 …';}
 try{
  cfStage('▸ 汇总生存者档案 …');
  var profile=buildProfile();
  profileCache=profile;
  cfStage('▸ 通道一 · 引擎建档 …');
  var rEngine=await withTimeout(commitEngine(profile),4000);
  cfStage('▸ 通道二 · MVU 变量直写 …');
  var rMvu=await withTimeout(commitMvu(profile),6000);
  cfStage('▸ 通道三 · 世界书铭刻 …');
  var rWb=await withTimeout(commitWorldbook(profile),8000);
  commitResults={engine:rEngine,mvu:rMvu,worldbook:rWb};
  cfStage('▸ 准备开局指令 …');
  var text=buildOpeningText(profile,rEngine,rMvu,rWb);
  var fr=fillChatbox(text);
  busy=false;
  finishCreate({via:fr.ok?fr.via:'modal',text:text,results:commitResults});
 }catch(e){
  busy=false;
  if(btn){btn.disabled=false;btn.classList.remove('busy');btn.textContent='◈ 确 认 苏 醒 ◈';}
  cfStage('✖ 写入链异常，请重试',true);
 }
}
function channelRows(o){
 var rows=[];
 var rs=o.results;
 if(o.via==='restore'){
  rows.push(['wa','⚠','本聊天已有一位苏醒者（幂等锁生效）—— 以下为当时的开局指令与保存结果']);
 }
 if(rs){
  if(rs.engine&&rs.engine.ok)rows.push(['ok','✓','通道一 · 引擎档 —— ARK_CORE.initState 已建档（等级 / 九属性 / 物品 / 印痕 / 宠物 / 队友 / 属性点余额）']);
  else if(rs.engine&&rs.engine.pending)rows.push(['wa','⚠','通道一 · 引擎未加载 —— 档案已暂存（ark21-pending-create），引擎脚本加载后自动建档']);
  else rows.push(['no','✖','通道一 · 引擎写入失败（'+esc((rs.engine&&rs.engine.reason)||'未知原因')+'）—— 请确认酒馆助手脚本「方舟2.2·ARK游戏核心引擎」已启用并授权']);
  if(rs.mvu&&rs.mvu.ok)rows.push(['ok','✓','通道二 · MVU 变量 —— 状态源已直写（会话设置 / 生存状态 / 物品印痕 / 恐龙 / 部落 / 世界，含复活模式 · 开局场景 · 追加补给）']);
  else rows.push(['wa','⚠','通道二 · MVU 直写未完成（'+esc((rs.mvu&&rs.mvu.reason)||'未检测')+'）—— 无碍：档案已由世界书持久化、引擎档已建档，AI 首回复的 UpdateVariable 将正式建立全部变量']);
  if(rs.worldbook&&rs.worldbook.ok){
   var wbNote='';
   if(rs.worldbook.created==='embedded')wbNote='（检测到卡内世界书未导入：已自动导入完整'+esc(String(rs.worldbook.total||''))+'条世界观并绑定）';
   else if(rs.worldbook.created)wbNote='（世界书未导入且卡内数据不可用：已补建12条地图速览兜底；建议重新导入本卡以获得完整世界观）';
   rows.push(['ok','✓','通道三 · 世界书 —— 「'+esc(rs.worldbook.entry||'')+'」已铭刻，[地图]'+esc(rs.worldbook.map||'')+' 条目已激活'+wbNote]);
  }
  else rows.push(['no','✖','通道三 · 世界书未写入（'+esc((rs.worldbook&&rs.worldbook.reason)||'未知原因')+'）—— 请确认角色卡已挂世界书且酒馆助手已授权']);
 }
 if(o.via==='textarea')rows.push(['ok','✓','开局指令 —— 已填入聊天框，<b>请检视后亲手发送</b>']);
 else if(o.via==='slash')rows.push(['ok','✓','开局指令 —— 已通过 setinput 填入输入框，<b>请检视后亲手发送</b>']);
 else if(o.via==='modal')rows.push(['wa','⚠','开局指令 —— 聊天框不可达，已弹出复制窗口']);
