}
function finishCreate(o,silent){
 created=true;
 try{writeLock(o.text,(o.results!==undefined?o.results:(o.results===undefined?commitResults:null))||null);}catch(e){}
 var done=qs('#cfDone');
 if(done){
  var rows=channelRows(o);
  var nm=(profileCache&&profileCache.name)||(trimmed(S.name)||'未命名生存者');
  var mp=(profileCache&&profileCache.map)||(mapName()||'孤岛');
  done.innerHTML='<div class="cf-done">'+
   '<div class="cd-hd"><span class="cd-ico">✓</span><div class="cd-tx"><div class="cd-t">苏醒档案已建立</div><div class="cd-s">AWAKENING REGISTERED · '+esc(nm)+' · '+esc(mp)+'</div></div></div>'+
   '<p class="cd-wait">等待你发送开局指令 …（发送后 AI 将以你的档案起笔苏醒场景）</p>'+
   '<div class="cd-list">'+rows.map(function(r){return '<div class="cd-r"><span class="s '+r[0]+'">'+r[1]+'</span><span>'+r[2]+'</span></div>';}).join('')+'</div>'+
   '<details class="cd-cmd"><summary>查看 / 复制开局指令全文</summary><pre>'+esc(o.text)+'</pre>'+
   '<div class="cd-acts"><button type="button" class="btn btn-pri" id="cdCopy">复制开局指令</button><button type="button" class="btn btn-ghost" id="cdRedo">重新创建角色</button></div></details>'+
   '</div>';
  var cp=qs('#cdCopy');
  if(cp)cp.addEventListener('click',function(){copyText(o.text,'开局指令已复制到剪贴板');});
  var rd=qs('#cdRedo');
  if(rd)rd.addEventListener('click',doRecreate);
 }
 qsa('button,input,textarea,select',qs('#akRoot')).forEach(function(el){
  if(el.closest&&el.closest('#cfDone'))return;
  el.disabled=true;
 });
 setStep(7,{force:true});
 if(!silent){
  if(o.via==='textarea'){
   toast('开局指令已填入聊天框 —— 请检视后亲手发送');
  }else if(o.via==='slash'){
   toast('开局指令已填入输入框 —— 请检视后亲手发送');
  }else if(o.via==='modal'){
   showModal('开局指令 · 复制发送',o.text,'当前环境无法直达酒馆聊天框（演示 / 预览环境）。<b>复制下方全文</b>，粘贴到聊天输入框发送即可开局。');
  }
 }
}
function doRecreate(){
 clearLock();
 clearDraft();
 created=false;
 busy=false;
 profileCache=null;
 commitResults=null;
 S=freshState();
 qsa('button,input,textarea,select',qs('#akRoot')).forEach(function(el){el.disabled=false;});
 var done=qs('#cfDone');
 if(done)done.innerHTML='';
 cfStage('');
 var btn=qs('#btnNext');
 if(btn){btn.disabled=false;btn.classList.remove('busy');}
 setStep(0,{force:true});
 toast('已重置 —— 开始新的创建');
}

/* ═══ 全局绑定与启动（神墟 launch 模式） ═══ */
function bindGlobal(){
 var start=qs('#btnStart');
 if(start)start.addEventListener('click',function(){
  if(created)return;
  setStep(1);
 });
 qsa('.stp').forEach(function(b){
  b.addEventListener('click',function(){
   if(created)return;
   var n=parseInt(b.getAttribute('data-n'),10)||1;
   if(n<=S.step)setStep(n);
  });
 });
 var prev=qs('#btnPrev');
 if(prev)prev.addEventListener('click',goPrev);
 var next=qs('#btnNext');
 if(next)next.addEventListener('click',goNext);
 var mx=qs('#mdClose');
 if(mx)mx.addEventListener('click',closeModal);
 var modal=qs('#akModal');
 if(modal){
  modal.addEventListener('click',function(ev){
   if(ev.target===modal)closeModal();
  });
 }
 document.addEventListener('keydown',function(ev){
  if(ev.key==='Escape'){
   var m=qs('#akModal');
   if(m&&!m.hidden)closeModal();
  }
 });
}
function init(){
 if(init.done)return;
 init.done=true;
 try{
  renderEnv();
  bindGlobal();
  var lock=null;
  try{lock=readLock();}catch(e){}
  if(lock){
   var d=readDraft();
   if(d)applyDraft(d);
   else S.name=lock.name||'未命名生存者';
   setStep(7,{force:true});
   renderConfirmEnv();
   finishCreate({via:'restore',text:lock.text||'',results:lock.results||null,restored:true},true);
   return;
  }
  setStep(0,{force:true});
 }catch(e){
  try{setStep(0,{force:true});}catch(e2){}
 }
}
(function launch(){
 try{
  if(document.readyState==='complete'||document.readyState==='interactive'){
   setTimeout(init,10);
  }else{
   document.addEventListener('DOMContentLoaded',init);
   window.addEventListener('load',init);
   setTimeout(init,200);
  }
 }catch(e){
  try{init();}catch(e2){}
 }
})();
})();
