.tgl[aria-pressed="true"]{color:var(--tek-hi);border-color:rgba(62,198,200,.75);background:rgba(62,198,200,.15);box-shadow:0 0 9px rgba(62,198,200,.25)}
/* 印痕列表（pane-scroll 内滚动 + 粘性分组头） */
.eng-list{margin-top:10px;padding:1px 2px 4px 0}
.ghead{position:sticky;top:0;z-index:6;display:flex;align-items:baseline;justify-content:space-between;gap:8px;
padding:7px 10px;margin:10px 0 4px;background:rgba(6,13,16,.98);border-left:3px solid var(--amber);
font-size:11.5px;font-weight:800;letter-spacing:.18em;color:var(--amber-hi);box-shadow:0 2px 8px rgba(0,0,0,.5)}
.ghead small{font-size:10px;color:var(--dim);letter-spacing:.1em;font-weight:600}
.ghead.tekera{border-left-color:var(--tek);color:var(--tek-hi)}
.erow{display:flex;gap:9px;align-items:stretch;padding:8px 9px 8px 6px;margin-bottom:5px;border:1px solid rgba(120,150,160,.16);
background:linear-gradient(150deg,rgba(62,198,200,.04),rgba(0,0,0,.22));transition:border-color .15s}
.erow:hover{border-color:rgba(62,198,200,.45)}
.erow.done{border-color:rgba(62,198,200,.3);background:linear-gradient(150deg,rgba(62,198,200,.1),rgba(0,0,0,.2))}
.catbar{flex:0 0 auto;width:4px;background:var(--dim)}
.erow[data-cat="工具"] .catbar{background:#8fb7c9}
.erow[data-cat="武器"] .catbar{background:#d86a5a}
.erow[data-cat="弹药"] .catbar{background:#c9a86a}
.erow[data-cat="防具"] .catbar{background:#7fb46a}
.erow[data-cat="建筑"] .catbar{background:#b08ad0}
.erow[data-cat="驯服"] .catbar{background:#e8a33d}
.erow[data-cat="鞍具"] .catbar{background:#d0a878}
.erow[data-cat="科技"] .catbar{background:#5ad0e8}
.erow[data-cat="泰克"] .catbar{background:#3ec6c8;box-shadow:0 0 8px rgba(62,198,200,.6)}
.erow[data-cat="材料"] .catbar{background:#9aa88a}
.e-main{flex:1 1 auto;min-width:0}
.e-line1{display:flex;align-items:center;gap:5px;flex-wrap:wrap}
.e-name{font-size:14px;font-weight:800;color:#eef6f8;letter-spacing:.03em}
.erow.done .e-name{color:var(--tek-hi)}
.tag{display:inline-flex;align-items:center;padding:1px 7px;font-size:10px;font-weight:700;letter-spacing:.05em;border:1px solid;font-variant-numeric:tabular-nums;white-space:nowrap}
.tag.lv{color:var(--tek);border-color:rgba(62,198,200,.4)}
.tag.ep{color:var(--amber-hi);border-color:rgba(232,163,61,.5);background:rgba(232,163,61,.08)}
.tag.batch{color:#d0a878;border-color:rgba(208,168,120,.45)}
.tag.stn{color:var(--dim);border-color:rgba(127,151,156,.35)}
.e-desc{margin-top:2px;font-size:11.5px;color:var(--dim)}
.e-req{margin-top:3px;font-size:11px;color:var(--dim)}
.e-req b.miss{color:#f08a7d;font-weight:700}
.e-req .okk{color:var(--tek-hi)}
.e-dino{margin-top:2px;font-size:11px;color:#d0a878}
.e-mats{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px}
.mat{display:inline-flex;align-items:baseline;gap:3px;padding:1.5px 7px;font-size:10.5px;border:1px solid;font-variant-numeric:tabular-nums}
.mat i{font-style:normal;font-size:9.5px;opacity:.75}
.mat.ok{color:#b9e39a;border-color:rgba(122,199,79,.4);background:rgba(122,199,79,.07)}
.mat.lack{color:#f08a7d;border-color:rgba(216,74,58,.45);background:rgba(216,74,58,.08)}
.e-act{flex:0 0 auto;display:flex;align-items:center;justify-content:center;min-width:86px}
.learnbtn{min-height:44px;min-width:82px;padding:6px 14px;cursor:pointer;font:inherit;font-size:13px;font-weight:900;letter-spacing:.14em;
color:#241503;border:0;background:linear-gradient(180deg,#f4c877,#e8a33d 55%,#c97f22);
clip-path:polygon(7px 0,100% 0,100% calc(100% - 7px),calc(100% - 7px) 100%,0 100%,0 7px);
box-shadow:0 0 12px rgba(232,163,61,.4);transition:filter .12s,transform .12s}
.learnbtn:hover{filter:brightness(1.18);transform:translateY(-1px)}
.learnbtn:active{transform:translateY(1px)}
.donebadge{display:inline-flex;align-items:center;gap:4px;min-height:36px;padding:4px 11px;font-size:12px;font-weight:800;color:var(--tek-hi);
border:1px solid rgba(62,198,200,.55);background:rgba(62,198,200,.12);text-shadow:0 0 8px rgba(62,198,200,.6)}
.lockchip{display:inline-flex;align-items:center;min-height:36px;padding:4px 10px;font-size:11px;font-weight:700;color:var(--faint);
border:1px solid rgba(127,151,156,.3);background:rgba(127,151,156,.06);text-align:center}
.bosschip{display:inline-flex;align-items:center;gap:4px;min-height:36px;padding:4px 10px;font-size:11px;font-weight:800;color:#ff9c8a;
border:1px solid rgba(216,74,58,.55);background:rgba(216,74,58,.12)}
/* 制作模式 */
.craft-side{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px;padding:1px 2px 3px 0}
.cchip2{min-height:44px;padding:6px 11px;cursor:pointer;font:inherit;font-size:11.5px;font-weight:700;white-space:nowrap;
border:1px solid rgba(127,151,156,.35);background:rgba(127,151,156,.06);color:var(--dim);transition:all .15s}
.cchip2 i{font-style:normal;font-size:9.5px;color:var(--faint);margin-left:3px}
.cchip2:hover{color:var(--ink)}
.cchip2.on{color:#241503;background:linear-gradient(180deg,#f0c169,#e8a33d 60%,#cf8a26);border-color:rgba(232,163,61,.8);box-shadow:0 0 10px rgba(232,163,61,.35)}
.cchip2.on i{color:rgba(36,21,3,.7)}
.ccard{position:relative;margin-top:10px;padding:12px 14px 14px}
.cc-line1{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.cc-name{font-size:17px;font-weight:900;color:#eef6f8;letter-spacing:.04em}
.cc-batch{margin-top:4px;font-size:11.5px;color:var(--dim)}
.cc-batch b{color:var(--amber-hi)}
.rt{width:100%;border-collapse:collapse;margin-top:9px;font-size:12px}
.rt th{text-align:right;padding:4px 8px;font-size:10.5px;letter-spacing:.14em;color:var(--amber);border-bottom:1px solid rgba(232,163,61,.3);font-weight:800}
.rt th:first-child{text-align:left}
.rt td{padding:5px 8px;border-bottom:1px dashed rgba(127,151,156,.16);text-align:right;font-variant-numeric:tabular-nums}
.rt td:first-child{text-align:left;color:var(--ink)}
.rt td.have{font-weight:800}
.rt td.have.ok{color:#b9e39a}
.rt td.have.lack{color:#f08a7d}
.rt .rt-total td{border-bottom:0;color:var(--dim);font-size:11px;padding-top:7px}
.stnline{display:flex;align-items:center;gap:7px;margin-top:9px;font-size:11.5px}
.stnb{padding:2px 9px;font-weight:800;border:1px solid;white-space:nowrap}
.stnb.ok{color:#b9e39a;border-color:rgba(122,199,79,.5);background:rgba(122,199,79,.09)}
.stnb.bad{color:#f08a7d;border-color:rgba(216,74,58,.55);background:rgba(216,74,58,.1);animation:barblink 2.4s ease-in-out infinite}
.stn-note{color:var(--faint);font-size:10.5px}
.tbtns{display:flex;gap:5px;margin-top:10px;align-items:center;flex-wrap:wrap}
.tbtns .lab{font-size:11px;color:var(--dim);margin-right:3px}
.tbtn{min-height:44px;min-width:52px;padding:6px 10px;cursor:pointer;font:inherit;font-size:13px;font-weight:800;
border:1px solid rgba(127,151,156,.4);background:rgba(127,151,156,.07);color:var(--dim);transition:all .15s}
.tbtn.on{color:var(--amber-hi);border-color:rgba(232,163,61,.75);background:rgba(232,163,61,.16);box-shadow:0 0 9px rgba(232,163,61,.3)}
.craftbtn{flex:1 1 auto;min-height:48px;margin-top:10px;padding:8px 16px;cursor:pointer;font:inherit;font-size:15px;font-weight:900;letter-spacing:.12em;
color:#241503;border:0;background:linear-gradient(180deg,#f4c877,#e8a33d 55%,#c97f22);
clip-path:polygon(9px 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%,0 9px);
box-shadow:0 0 14px rgba(232,163,61,.45);transition:filter .12s,transform .12s}
.craftbtn:hover{filter:brightness(1.15);transform:translateY(-1px)}
.craftbtn:active{transform:translateY(1px)}
.ptA{position:relative;display:block;height:0}
.pt{position:absolute;left:50%;bottom:26px;width:7px;height:7px;background:#f0c169;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%);
pointer-events:none;opacity:0;animation:ptfly .85s ease-out forwards;z-index:8}
.pt.tk{background:#3ec6c8}
@keyframes ptfly{0%{opacity:1;transform:translate(0,0) scale(1)}100%{opacity:0;transform:translate(var(--dx,0px),var(--dy,-80px)) scale(.25)}}
.emptybox{padding:20px 14px;text-align:center;border:1px dashed rgba(120,150,160,.28);margin-top:10px}
.emptybox .eico{font-size:34px;opacity:.75;margin-bottom:6px}
.emptybox p{margin:0 0 5px;font-size:13.5px;font-weight:700;color:#dfe9ec;letter-spacing:.06em}
.emptybox small{color:var(--dim);font-size:11.5px;line-height:1.6;display:block}
/* ── 物品面板 ── */
.wbox{display:flex;flex-direction:column;gap:5px;margin-top:10px;padding:11px 13px}
.w-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.w-title{font-size:11px;letter-spacing:.24em;color:var(--amber);font-weight:800}
.w-text{font-size:12.5px;color:var(--ink);font-weight:700}
.w-warn{font-size:11.5px;font-weight:800;color:#f0b0a8}
.w-warn.soft{color:#ecc98a}
.w-warn.okc{color:#b9e39a}
.tblwrap{overflow-x:auto;margin-top:9px;-webkit-overflow-scrolling:touch}
.restable{width:100%;border-collapse:collapse;font-size:12px;min-width:340px}
.restable th{text-align:right;padding:4px 9px;font-size:10.5px;letter-spacing:.14em;color:var(--amber);border-bottom:1px solid rgba(232,163,61,.3);font-weight:800;white-space:nowrap}
.restable th:first-child{text-align:left}
.restable td{padding:6px 9px;border-bottom:1px dashed rgba(127,151,156,.16);text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.restable td:first-child{text-align:left;color:var(--ink)}
.restable tr.rrow{cursor:pointer;transition:background .12s}
.restable tr.rrow:hover{background:rgba(232,163,61,.06)}
.restable tr.zero{opacity:.38}
.restable td .rw-ico{margin-right:6px}
.restable td.sub{color:var(--dim);font-size:11px}
.restable td.cnt{font-weight:800;color:var(--amber-hi)}
.restable tr.zero td.cnt{color:var(--faint);font-weight:400}
.igrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(128px,1fr));gap:7px;margin-top:10px;padding:1px 2px 4px 0;align-content:start}
.icard{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:3px;min-height:96px;
padding:10px 6px 8px;cursor:pointer;font:inherit;text-align:center;border:1px solid rgba(120,150,160,.2);
background:linear-gradient(165deg,rgba(62,198,200,.05),rgba(0,0,0,.28));transition:border-color .15s,transform .12s;overflow:hidden}
.icard::before{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:var(--cc,#7f979c)}
.icard[data-cat="工具"]{--cc:#8fb7c9}.icard[data-cat="武器"]{--cc:#d86a5a}.icard[data-cat="弹药"]{--cc:#c9a86a}
.icard[data-cat="防具"]{--cc:#7fb46a}.icard[data-cat="建筑"]{--cc:#b08ad0}.icard[data-cat="驯服"]{--cc:#e8a33d}
.icard[data-cat="鞍具"]{--cc:#d0a878}.icard[data-cat="科技"]{--cc:#5ad0e8}.icard[data-cat="泰克"]{--cc:#3ec6c8}
.icard[data-cat="材料"]{--cc:#9aa88a}.icard[data-cat="食物"]{--cc:#e8b64a}.icard[data-cat="药剂"]{--cc:#c98ad0}
.icard:hover{border-color:rgba(232,163,61,.6);transform:translateY(-2px)}
.icard:focus-visible{outline:1px solid var(--amber);outline-offset:2px}
.ic-ico{font-size:26px;line-height:1.2;filter:drop-shadow(0 2px 4px rgba(0,0,0,.6))}
.ic-name{font-size:12px;font-weight:700;color:var(--ink);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ic-n{font-size:11px;color:var(--amber-hi);font-weight:800}
.ic-tags{display:flex;gap:3px;flex-wrap:wrap;justify-content:center}
.ic-mini{font-size:9px;padding:0 5px;border:1px solid rgba(122,199,79,.45);color:#b9e39a;white-space:nowrap}
.ic-mini.dur{border-color:rgba(127,151,156,.4);color:var(--dim)}
.it-hint{margin-top:8px;font-size:11px;color:var(--faint)}
/* 物品操作菜单（底部抽屉） */
.menuveil{position:fixed;inset:0;z-index:110;background:rgba(2,7,10,.6);backdrop-filter:blur(2px)}
.imenu{position:fixed;left:50%;bottom:14px;transform:translateX(-50%);z-index:120;width:min(94%,430px);
padding:13px 15px 15px;border:1px solid rgba(232,163,61,.55);background:linear-gradient(165deg,#101f24,#0a1418);
box-shadow:0 -6px 34px rgba(0,0,0,.7),inset 0 0 26px rgba(0,0,0,.5);animation:menuin .22s ease}
@keyframes menuin{from{transform:translateX(-50%) translateY(16px);opacity:0}to{transform:translateX(-50%) translateY(0);opacity:1}}
.im-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.im-ico{font-size:22px}
.im-name{font-size:15px;font-weight:900;color:#eef6f8}
.im-n{font-size:12px;color:var(--amber-hi);font-weight:800}
.im-cat{margin-left:auto;font-size:10px;padding:1px 7px;border:1px solid rgba(127,151,156,.4);color:var(--dim)}
.im-hint{margin-top:5px;font-size:10.5px;color:var(--faint)}
.im-btns{display:flex;gap:6px;margin-top:11px;flex-wrap:wrap}
.imbtn{flex:1 1 auto;min-height:44px;padding:7px 10px;cursor:pointer;font:inherit;font-size:12.5px;font-weight:800;
border:1px solid rgba(127,151,156,.45);background:rgba(127,151,156,.08);color:var(--ink);transition:all .13s}
.imbtn:hover{border-color:rgba(207,227,230,.6)}
