.im-confirm{margin-top:11px;padding:9px 11px;border:1px dashed rgba(216,74,58,.6);background:rgba(216,74,58,.08);font-size:12.5px;color:#f0b0a8}
.im-confirm .im-btns{margin-top:8px}
/* ── 驯服面板 ── */
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:10px}
.step{position:relative;padding:11px 10px 10px;border:1px solid rgba(62,198,200,.25);background:linear-gradient(165deg,rgba(62,198,200,.07),rgba(0,0,0,.24))}
.step-no{position:absolute;top:-9px;left:8px;padding:0 7px;font-size:11px;font-weight:900;color:#241503;background:linear-gradient(180deg,#f0c169,#e8a33d);clip-path:polygon(5px 0,100% 0,calc(100% - 5px) 100%,0 100%)}
.step h4{margin:4px 0 4px;font-size:13px;color:#eaf6f7;letter-spacing:.05em}
.step p{margin:0;font-size:11px;color:var(--dim);line-height:1.6}
.tame-tip{margin-top:10px;padding:9px 12px;border-left:3px solid var(--amber);background:linear-gradient(90deg,rgba(232,163,61,.12),rgba(232,163,61,.02));font-size:12px;color:#e6d9bf;line-height:1.7}
.rectable{width:100%;border-collapse:collapse;font-size:12px;margin-top:9px}
.rectable th{text-align:left;padding:4px 9px;font-size:10.5px;letter-spacing:.14em;color:var(--amber);border-bottom:1px solid rgba(232,163,61,.3);font-weight:800;white-space:nowrap}
.rectable td{padding:6px 9px;border-bottom:1px dashed rgba(127,151,156,.16);white-space:nowrap}
.rectable td:first-child{color:#eef6f8;font-weight:700}
.rectable tr:hover td{background:rgba(62,198,200,.05)}
.rectable .temper{font-weight:700}
.temper.t-wen{color:#b9e39a}.temper.t-dan{color:#ecc98a}.temper.t-gong{color:#f08a7d}
.rectable .use{color:var(--dim);white-space:normal;font-size:11px}
/* 会话 */
.tc-head{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap}
.tc-sp{font-size:21px;font-weight:900;color:#eef6f8;letter-spacing:.05em;text-shadow:0 0 12px rgba(62,198,200,.35)}
.tc-lv{font-size:15px;font-weight:900;color:var(--amber-hi)}
.tc-chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px}
.tc-chip{font-size:10.5px;padding:1.5px 8px;border:1px solid rgba(127,151,156,.35);color:var(--dim)}
.tc-chip.hi{border-color:rgba(232,163,61,.5);color:var(--amber-hi)}
