.meter{margin-top:12px}
.meter .m-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.m-lab{font-size:11px;letter-spacing:.22em;color:var(--dim);font-weight:700}
.m-num{font-size:20px;font-weight:900;line-height:1}
.m-num.big{font-size:30px;color:#93e07f;text-shadow:0 0 14px rgba(110,200,110,.5)}
.m-num.torp-c{color:#c3a8ea}
.m-num.danger{color:#ef6a55;animation:barblink 1.1s ease-in-out infinite}
.m-sub{margin-top:2px;font-size:10.5px;color:var(--faint)}
.bar.fat{height:18px;border-color:rgba(122,199,79,.4)}
.bar.fat .fill{transition:width .45s ease}
.feedzone{margin-top:12px}
.fz-lab{font-size:11px;letter-spacing:.22em;color:var(--dim);font-weight:700;margin-bottom:6px}
.feedrow{display:flex;flex-wrap:wrap;gap:6px}
.feedbtn{min-height:44px;padding:7px 13px;cursor:pointer;font:inherit;font-size:12.5px;font-weight:800;color:var(--ink);
border:1px solid rgba(122,199,79,.5);background:linear-gradient(180deg,rgba(122,199,79,.16),rgba(122,199,79,.04));transition:all .13s}
.feedbtn i{font-style:normal;font-size:10.5px;color:#b9e39a;margin-left:4px}
