.narcbtn:hover:not(:disabled){box-shadow:0 0 10px rgba(176,138,232,.4)}
.narcbtn:disabled{cursor:not-allowed;opacity:.4;filter:saturate(.3)}
.blocknote{margin-top:8px;padding:7px 11px;font-size:11.5px;font-weight:700;color:#f0b0a8;border:1px dashed rgba(216,74,58,.55);background:rgba(216,74,58,.08)}
.dangernote{margin-top:8px;padding:8px 11px;font-size:12px;font-weight:800;color:#ffd2c9;border:1px solid rgba(216,74,58,.65);
