.effline{display:flex;align-items:center;gap:8px;margin-top:12px;flex-wrap:wrap}
.effbadge{display:inline-flex;align-items:center;gap:5px;min-height:34px;padding:4px 13px;font-size:12.5px;font-weight:900;letter-spacing:.08em;border:1px solid}
.effbadge.b-ok{color:var(--tek-hi);border-color:rgba(62,198,200,.7);background:rgba(62,198,200,.12);text-shadow:0 0 10px rgba(62,198,200,.7);animation:eppulse 1.9s ease-in-out infinite}
