.eff-note{font-size:10.5px;color:var(--faint)}
.finbtn{display:block;width:100%;min-height:58px;margin-top:14px;padding:10px 18px;cursor:pointer;font:inherit;font-size:17px;font-weight:900;letter-spacing:.22em;
color:#241503;border:0;background:linear-gradient(180deg,#ffe3a3,#e8a33d 45%,#b26f1e);
clip-path:polygon(11px 0,100% 0,100% calc(100% - 11px),calc(100% - 11px) 100%,0 100%,0 11px);
animation:finpulse 1.6s ease-in-out infinite;transition:filter .12s}
.finbtn:hover{filter:brightness(1.12)}
@keyframes finpulse{0%,100%{box-shadow:0 0 12px rgba(232,163,61,.5)}50%{box-shadow:0 0 34px rgba(255,214,130,.95)}}
.notyet{margin-top:12px;text-align:center;font-size:11.5px;color:var(--faint)}
/* 驯服完成庆祝横幅 */
.celebrate{overflow:hidden;border-color:rgba(232,163,61,.65);background:linear-gradient(160deg,rgba(232,163,61,.16),rgba(62,198,200,.07))}
.celebrate::before{content:"";position:absolute;inset:-60%;pointer-events:none;
background:repeating-conic-gradient(rgba(232,163,61,.13) 0 6deg,transparent 6deg 18deg);animation:rays 16s linear infinite}
.cl-in{position:relative;text-align:center;padding:4px 6px}
.cl-ico{font-size:34px;filter:drop-shadow(0 0 12px rgba(232,163,61,.7))}
/* ══ V3.0.1 庆祝系统增强 ══ */
.celebrate.ring-gold{border-color:rgba(255,214,120,.85);background:linear-gradient(160deg,rgba(232,163,61,.22),rgba(255,214,120,.08) 55%,rgba(62,198,200,.06));box-shadow:0 0 26px rgba(255,200,90,.28)}
.celebrate.ring-dim{border-color:rgba(127,149,160,.6);background:linear-gradient(160deg,rgba(127,149,160,.14),rgba(62,198,200,.04))}
.cl-ico.pop-in{animation:clPop .55s cubic-bezier(.2,1.6,.4,1) both}
@keyframes clPop{from{transform:scale(.2) rotate(-14deg);opacity:0}to{transform:scale(1) rotate(0);opacity:1}}
.cl-chips{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;margin-top:8px}
.cchip2{display:inline-flex;align-items:center;gap:4px;padding:3px 10px;font-size:12px;font-weight:800;letter-spacing:.4px;border:1px solid;border-radius:99px;animation:clPop .4s cubic-bezier(.2,1.4,.4,1) both}
.cchip2.lv{color:var(--amber-hi);border-color:rgba(232,163,61,.75);background:rgba(232,163,61,.1);text-shadow:0 0 8px rgba(232,163,61,.5)}
.cchip2.ef-g{color:#ffd98c;border-color:rgba(255,214,120,.8);background:linear-gradient(rgba(255,214,120,.18),rgba(255,214,120,.06));box-shadow:0 0 10px rgba(255,214,120,.3)}
.cchip2.ef-a{color:var(--amber-hi);border-color:rgba(232,163,61,.6);background:rgba(232,163,61,.1)}
.cchip2.ef-d{color:#9db2bb;border-color:rgba(127,149,160,.55);background:rgba(127,149,160,.1)}
.cchip2.sp{color:var(--teal-hi);border-color:rgba(62,198,200,.6);background:rgba(62,198,200,.08)}
.cchip2.mut{color:#ffe9b8;border-color:rgba(255,214,120,.85);background:linear-gradient(135deg,rgba(255,214,120,.22),rgba(232,163,61,.1));box-shadow:0 0 12px rgba(255,214,120,.35);animation:clPop .5s cubic-bezier(.2,1.6,.4,1) both,mutShine 2.4s ease-in-out .6s infinite}
.cchip2.mut.color{color:#c9b8ff;border-color:rgba(180,150,255,.8);background:linear-gradient(135deg,rgba(180,150,255,.22),rgba(120,80,220,.12));box-shadow:0 0 12px rgba(180,150,255,.4)}
@keyframes mutShine{0%,100%{filter:brightness(1)}50%{filter:brightness(1.35)}}
.cchip2.plain{color:#8fa6ab;border-color:rgba(127,149,160,.5);background:rgba(127,149,160,.08);font-weight:600}
.celebrate .ptA{position:absolute;top:14px;left:50%;width:0;height:0;pointer-events:none}
.celebrate .pt{position:absolute;left:0;top:0;width:6px;height:6px;border-radius:2px;background:linear-gradient(180deg,#ffe9b8,#e8a33d);opacity:0;animation:ptFly 1.05s cubic-bezier(.16,.84,.44,1) both;box-shadow:0 0 6px rgba(232,163,61,.65)}
.celebrate .pt.tk{background:linear-gradient(180deg,#b8f4f6,#3ec6c8);box-shadow:0 0 6px rgba(62,198,200,.65)}
.celebrate .pt.au{width:8px;height:8px;background:radial-gradient(circle at 30% 30%,#fff7dd,#ffd76e 55%,#c99229);border-radius:50%;box-shadow:0 0 10px rgba(255,214,120,.9)}
@keyframes ptFly{0%{transform:translate(0,0) rotate(0);opacity:1}70%{opacity:1}100%{transform:translate(var(--dx,0),var(--dy,-60px)) rotate(216deg);opacity:0}}
/* 蛋壳三段：完整蛋→裂纹抖动→破壳 */
.egg-stage{position:relative;height:52px;margin:2px auto 0}
.egg-stage i{position:absolute;left:50%;top:0;transform:translateX(-50%);font-style:normal;font-size:34px;line-height:52px;filter:drop-shadow(0 0 12px rgba(232,163,61,.7))}
.egg-stage .egg1{animation:eggWob 1.15s ease-in-out both}
.egg-stage .egg2{animation:eggCrack 1.15s steps(1) both;font-size:0}
.egg-stage .egg3{animation:eggOut 1.15s cubic-bezier(.2,1.6,.4,1) both;font-size:0}
@keyframes eggWob{0%{transform:translateX(-50%) rotate(0)}12%{transform:translateX(-52%) rotate(-7deg)}24%{transform:translateX(-48%) rotate(6deg)}36%{transform:translateX(-51%) rotate(-9deg)}48%{transform:translateX(-49%) rotate(8deg)}60%{transform:translateX(-50%) rotate(-11deg);opacity:1}75%,100%{transform:translateX(-50%) rotate(0);opacity:0;font-size:0}}
@keyframes eggCrack{0%,55%{font-size:0;opacity:0}56%{font-size:34px;opacity:1;transform:translateX(-50%) rotate(-4deg)}66%{transform:translateX(-49%) rotate(5deg)}76%{transform:translateX(-51%) rotate(-6deg)}86%{opacity:1}87%,100%{font-size:0;opacity:0}}
@keyframes eggOut{0%,85%{font-size:0;opacity:0;transform:translateX(-50%) scale(.3)}86%{font-size:38px;opacity:1}92%{transform:translateX(-50%) scale(1.18)}100%{transform:translateX(-50%) scale(1);font-size:38px;opacity:1}}
@media(prefers-reduced-motion:reduce){.egg-stage .egg1,.egg-stage .egg2,.egg-stage .egg3,.cl-ico.pop-in,.cchip2{animation:none!important}.egg-stage .egg1{opacity:0}.egg-stage .egg2{opacity:0}.egg-stage .egg3{font-size:38px;opacity:1}}
.cl-t{margin-top:2px;font-size:19px;font-weight:900;letter-spacing:.3em;color:var(--amber-hi);text-shadow:0 0 16px rgba(232,163,61,.7)}
.cl-line{margin-top:5px;font-size:13px;color:var(--ink)}
.cl-line b{color:var(--amber-hi);font-size:15px}
.cl-stat{margin-top:7px;font-size:11.5px;color:var(--dim)}
.cl-stat.okk{color:#b9e39a}
.ghostbtn{min-height:44px;margin-top:10px;padding:7px 22px;cursor:pointer;font:inherit;font-size:12.5px;font-weight:700;
border:1px solid rgba(127,151,156,.45);background:transparent;color:var(--dim);transition:all .13s}
.ghostbtn:hover{color:var(--ink);border-color:rgba(207,227,230,.6)}
@keyframes rays{to{transform:rotate(360deg)}}
/* ── 降级（只读）面板 ── */
.fb-rows{margin-top:9px}
.fb-row{display:flex;gap:10px;padding:6px 2px;border-bottom:1px dashed rgba(127,151,156,.18);font-size:12.5px}
.fb-k{flex:0 0 76px;color:var(--dim);letter-spacing:.06em}
.fb-v{color:var(--ink);word-break:break-all}
.fb-empty{margin-top:10px;padding:18px 12px;text-align:center;color:var(--faint);font-size:12.5px;border:1px dashed rgba(127,151,156,.3)}
.fb-note{margin-top:11px;padding-top:9px;border-top:1px dashed rgba(216,74,58,.35);font-size:11px;color:#d8a49b;line-height:1.7}
/* ── Toast ── */
.toasts{position:fixed;top:10px;right:10px;z-index:200;display:flex;flex-direction:column;gap:6px;max-width:min(86vw,330px);pointer-events:none}
.toast{padding:9px 13px;font-size:12.5px;font-weight:700;color:var(--ink);border:1px solid rgba(62,198,200,.5);
background:linear-gradient(165deg,rgba(10,22,26,.97),rgba(6,13,16,.97));box-shadow:0 4px 18px rgba(0,0,0,.6);
animation:toastin .25s ease;word-break:break-all}
.toast.ok{border-color:rgba(122,199,79,.65);color:#c9e9ad}
.toast.err{border-color:rgba(216,74,58,.65);color:#f0b0a8}
.toast.warn{border-color:rgba(232,163,61,.65);color:#ecc98a}
.toast.out{animation:toastout .32s ease forwards}
@keyframes toastin{from{transform:translateX(24px);opacity:0}to{transform:translateX(0);opacity:1}}
@keyframes toastout{to{transform:translateX(24px);opacity:0}}
/* ── 自定义滚动条（琥珀→泰克青渐变 thumb） ── */
.pane-scroll::-webkit-scrollbar,.tblwrap::-webkit-scrollbar{width:8px;height:8px}
.pane-scroll::-webkit-scrollbar-track,.tblwrap::-webkit-scrollbar-track{background:rgba(0,0,0,.42)}
.pane-scroll::-webkit-scrollbar-thumb,.tblwrap::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#e8a33d,#3ec6c8);border-radius:4px;border:1px solid rgba(0,0,0,.4)}
.pane-scroll,.tblwrap{scrollbar-width:thin;scrollbar-color:#e8a33d rgba(0,0,0,.42)}
/* 资源表「管理」小按钮 */
.mgbtn{min-height:44px;min-width:58px;padding:5px 12px;cursor:pointer;font:inherit;font-size:11px;font-weight:700;letter-spacing:.04em;
border:1px solid rgba(127,151,156,.4);background:rgba(127,151,156,.07);color:var(--dim);transition:all .13s;white-space:nowrap}
.mgbtn:hover:not(:disabled){color:var(--ink);border-color:rgba(207,227,230,.55);background:rgba(207,227,230,.08)}
.mgbtn:disabled{cursor:not-allowed;opacity:.35}
.count-line{margin-top:8px;font-size:11px;color:var(--faint);letter-spacing:.04em}
.count-line b{color:var(--dim)}
/* ═══ 驯服动画增强：漂浮增量粒子 / 进度条闪光 / 目标呼吸头像 ═══ */
.ffx{position:absolute;z-index:60;pointer-events:none;font-family:var(--mono);font-size:14px;font-weight:700;color:var(--amber);text-shadow:0 0 8px rgba(232,163,61,.6);animation:ffxUp .95s ease-out forwards;transform:translate(-50%,-50%)}
.ffx.torp{color:#c3a8ea;text-shadow:0 0 8px rgba(180,142,232,.6)}
.ffx.bad{color:var(--red-hi);text-shadow:0 0 8px rgba(216,74,58,.6)}
@keyframes ffxUp{0%{opacity:0;transform:translate(-50%,-30%) scale(.7)}15%{opacity:1;transform:translate(-50%,-52%) scale(1.15)}30%{transform:translate(-50%,-64%) scale(1)}100%{opacity:0;transform:translate(-50%,-170%) scale(.95)}}
.bar.prog .fill{overflow:hidden}
.bar.prog .fill::after{content:'';position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(105deg,rgba(255,255,255,0),rgba(255,255,255,.3),rgba(255,255,255,0));animation:tameShimmer 2.4s linear infinite}
@keyframes tameShimmer{0%{left:-60%}100%{left:132%}}
.tc-ava{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;font-size:26px;background:radial-gradient(circle at 50% 35%,#12262c,#0a161a 80%);border:1px solid #1e3a42;border-radius:9px;margin-right:11px;flex:0 0 auto;animation:tcBreathe 3.4s ease-in-out infinite;box-shadow:inset 0 0 12px rgba(62,198,200,.18)}
@keyframes tcBreathe{0%,100%{transform:scale(1);box-shadow:inset 0 0 12px rgba(62,198,200,.18)}50%{transform:scale(1.07);box-shadow:inset 0 0 18px rgba(62,198,200,.4),0 0 10px rgba(62,198,200,.25)}}
.tc-headrow{display:flex;align-items:center;margin:8px 0 4px}
.feedbtn{position:relative}
.feedbtn:active{transform:scale(.94)}

/* ═══ Tab 6 地图（迷雾探索 + 区域跳转） ═══ */
