/* NPC 聊天弹层（全屏遮罩 + 居中卡片） */
.chatveil{position:fixed;inset:0;z-index:130;background:rgba(2,7,10,.66);backdrop-filter:blur(2px)}
.chatbox{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:140;width:min(460px,94%);height:min(560px,86%);
display:flex;flex-direction:column;padding:12px 13px 13px;border:1px solid rgba(62,198,200,.6);
background:linear-gradient(165deg,#101f24,#0a1418);box-shadow:0 10px 44px rgba(0,0,0,.75),inset 0 0 26px rgba(0,0,0,.5);
animation:chatin .2s ease}
@keyframes chatin{from{opacity:0;transform:translate(-50%,-47%) scale(.97)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
.cb-head{display:flex;align-items:center;gap:9px;flex:0 0 auto;flex-wrap:wrap}
.cb-ava{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;font-size:21px;background:radial-gradient(circle at 50% 35%,#12262c,#0a161a 80%);border:1px solid #1e3a42;border-radius:8px;flex:0 0 auto;animation:tcBreathe 3.4s ease-in-out infinite}
.cb-nb{flex:1 1 auto;min-width:0}
.cb-nm{font-size:15px;font-weight:900;color:#eef6f8;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
