.cb-badge{flex:0 0 auto;font-size:9px;font-weight:800;letter-spacing:.06em;padding:2px 7px;border:1px solid rgba(62,198,200,.5);color:#8fe3e4;background:rgba(62,198,200,.08);white-space:nowrap}
.cb-x{flex:0 0 auto;width:34px;height:34px;cursor:pointer;font:inherit;font-size:15px;font-weight:900;color:var(--dim);border:1px solid rgba(127,151,156,.4);background:transparent;transition:all .13s}
