.cb-msgs::-webkit-scrollbar{width:7px}
.cb-msgs::-webkit-scrollbar-track{background:rgba(0,0,0,.42)}
.cb-msgs::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#e8a33d,#3ec6c8);border-radius:4px}
.bub{max-width:82%;padding:7px 11px;font-size:12.5px;line-height:1.55;word-break:break-word;border:1px solid}
.bub span{white-space:pre-wrap}
/* V3.4.6 单句操作：气泡悬停/长按浮现 ↻ 重新生成 与 🗑 删除 */
.bub{position:relative;display:flex;flex-direction:column;gap:3px}
