.bub-op{border:1px solid rgba(127,151,156,.4);background:rgba(10,22,26,.85);color:#9fb8bd;font-size:11px;line-height:1;padding:4px 7px;border-radius:7px;cursor:pointer;min-width:24px;min-height:22px}
.bub-op:hover{color:#e8a33d;border-color:rgba(232,163,61,.6)}
