.bub.regenerating{align-self:flex-start;color:var(--dim);border-color:rgba(127,151,156,.3);background:rgba(127,151,156,.06);font-size:11.5px;display:flex;align-items:center;gap:7px}
@media (hover:none){.bub-ops{opacity:1}} /* 触屏设备常显操作按钮 */
.bub.me{align-self:flex-end;color:#f6e3c2;border-color:rgba(232,163,61,.5);background:linear-gradient(165deg,rgba(232,163,61,.18),rgba(232,163,61,.05));border-radius:10px 10px 2px 10px}
