/* 弹窗层级：veil 150 / box 160 —— 高于普通面板与 NPC 聊天层(130/140)，低于 toast(200) */
.dmdveil,.nmdveil{position:fixed;inset:0;z-index:150;background:rgba(2,7,10,.68);backdrop-filter:blur(2px)}
.dmdbox,.nmdbox{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:160;width:min(470px,94%);max-height:min(600px,88%);
display:flex;flex-direction:column;padding:12px 13px 13px;border:1px solid rgba(232,163,61,.55);
background:linear-gradient(165deg,#131f22,#0a1418);box-shadow:0 10px 44px rgba(0,0,0,.8),inset 0 0 26px rgba(0,0,0,.5);
animation:chatin .2s ease}
.dmd-head,.nmd-head{display:flex;align-items:center;gap:9px;flex:0 0 auto;flex-wrap:wrap}
.dmd-head .tc-ava,.nmd-head .mono-ava{width:44px;height:44px;font-size:24px;border-radius:9px;flex:0 0 auto}
.dmd-sub{flex:0 0 auto;margin-top:7px;font-size:11px;color:var(--dim);letter-spacing:.04em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dmd-scroll,.nmd-scroll{flex:1 1 auto;min-height:0;overflow-y:auto;margin-top:8px;padding-right:2px;display:flex;flex-direction:column;gap:9px;scrollbar-width:thin;scrollbar-color:#e8a33d rgba(0,0,0,.42)}
.dmd-scroll::-webkit-scrollbar,.nmd-scroll::-webkit-scrollbar{width:7px}
.dmd-scroll::-webkit-scrollbar-track,.nmd-scroll::-webkit-scrollbar-track{background:rgba(0,0,0,.42)}
.dmd-scroll::-webkit-scrollbar-thumb,.nmd-scroll::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#e8a33d,#3ec6c8);border-radius:4px}
.dmd-sec,.nmd-sec{border:1px solid rgba(62,198,200,.2);border-radius:8px;padding:8px 10px;background:rgba(62,198,200,.04)}
.dmd-t{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--amber);border-bottom:1px dashed rgba(232,163,61,.35);padding-bottom:3px;margin-bottom:6px}
.nmd-t{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--tek-hi);border-bottom:1px dashed rgba(62,198,200,.35);padding-bottom:3px;margin-bottom:6px}
.dmd-kv,.nmd-kv{display:grid;grid-template-columns:84px 1fr;gap:8px;font-size:12px;padding:3px 0;border-bottom:1px dashed rgba(127,151,156,.14)}
.nmd-kv{grid-template-columns:88px 1fr}
.dmd-kv:last-child,.nmd-kv:last-child,.dmd-kv:last-of-type,.nmd-kv:last-of-type{border-bottom:0}
.dmd-kv .k,.nmd-kv .k{color:var(--dim);font-size:11px;letter-spacing:.04em;align-self:baseline}
.dmd-kv .v,.nmd-kv .v{color:var(--ink);word-break:break-word;line-height:1.55}
.dmd-stat{display:grid;grid-template-columns:44px 1fr 64px 40px;gap:6px;align-items:center;font-size:11.5px;padding:4px 0;border-bottom:1px dashed rgba(127,151,156,.14)}
.dmd-stat:last-of-type{border-bottom:0}
.dmd-stat .sn{color:var(--dim);letter-spacing:.06em}
.dmd-stat .sv{font-weight:800;color:var(--ink);text-align:right;font-variant-numeric:tabular-nums}
.dmd-stat .sp{font-size:10.5px;color:var(--amber-hi);text-align:right;white-space:nowrap}
.dmd-plus{min-height:36px;min-width:36px;padding:2px 6px;font-size:13px}
.dmd-note{margin-top:6px;font-size:10.5px;color:var(--dim);line-height:1.6}
.dmd-ops,.nmd-ops{flex:0 0 auto;margin-top:9px;display:flex;flex-wrap:wrap;gap:5px;align-items:center;border-top:1px dashed rgba(232,163,61,.35);padding-top:9px}
.nmd-rec{font-size:11px;color:var(--dim);padding:3px 0;border-bottom:1px dashed rgba(127,151,156,.14);line-height:1.55;word-break:break-word}
.nmd-rec:last-of-type{border-bottom:0}
/* 卡片头部可点击（打开详情弹窗） */
.tc2-head[data-act="dinosheet"]{cursor:pointer;border-radius:9px;outline:none}
.tc2-head[data-act="dinosheet"]:hover .tc2-nm,.tc2-head[data-act="dinosheet"]:focus-visible .tc2-nm{color:var(--amber-hi)}
.tc2-head[data-act="dinosheet"]:hover .tc2-sp,.tc2-head[data-act="dinosheet"]:focus-visible .tc2-sp{color:var(--tek-hi)}
.tc2-head[data-act="dinosheet"]:focus-visible{box-shadow:0 0 0 2px rgba(232,163,61,.45)}
/* 生存编年史：时间线（琥珀/苔绿/青铜/暮蓝四色分档，方舟暗色系） */
.chr-list{max-height:288px;overflow-y:auto;margin-top:8px;border:1px solid rgba(232,163,61,.28);background:rgba(232,163,61,.04);padding:4px 6px;scrollbar-width:thin;scrollbar-color:#e8a33d rgba(0,0,0,.42)}
.chr-list::-webkit-scrollbar{width:8px}
.chr-list::-webkit-scrollbar-track{background:rgba(0,0,0,.42)}
.chr-list::-webkit-scrollbar-thumb{background:linear-gradient(180deg,#e8a33d,#3ec6c8);border-radius:4px}
.chr-item{display:flex;align-items:baseline;gap:8px;padding:5px 4px;border-bottom:1px dashed rgba(127,151,156,.16)}
.chr-item:last-child{border-bottom:0}
.chr-day{flex:0 0 auto;font-family:var(--mono);font-size:10.5px;font-weight:800;color:var(--amber-hi);white-space:nowrap}
.chr-kind{flex:0 0 auto;font-size:9.5px;font-weight:800;letter-spacing:.06em;padding:1px 6px;border:1px solid;white-space:nowrap}
.chr-k-up,.chr-k-grow{color:#f0c169;border-color:rgba(232,163,61,.55);background:rgba(232,163,61,.12)}
.chr-k-tame{color:#b9e39a;border-color:rgba(122,199,79,.5);background:rgba(122,199,79,.1)}
.chr-k-meet{color:#e2b28a;border-color:rgba(201,136,74,.55);background:rgba(201,136,74,.12)}
.chr-k-find{color:#a8d8dc;border-color:rgba(58,106,114,.7);background:rgba(58,106,114,.2)}
.chr-k-else{color:var(--dim);border-color:rgba(127,151,156,.4)}
.chr-tx{flex:1 1 auto;min-width:0;font-size:11.5px;color:var(--ink);line-height:1.55;word-break:break-word}
.chr-empty{margin-top:8px;padding:12px 12px;border:1px dashed rgba(127,151,156,.3);font-size:11px;color:var(--dim);line-height:1.7;text-align:center}
.dmdbox .cb-x,.nmdbox .cb-x{width:38px;height:38px}
@media (max-width:600px){.npc-grid{grid-template-columns:1fr}.chatbox{width:94%}.dmdbox,.nmdbox{width:96%}.dmd-kv,.nmd-kv{grid-template-columns:76px 1fr}.dmd-stat{grid-template-columns:38px 1fr 56px 40px}}
@media (max-width:600px){.tm-grid{grid-template-columns:repeat(auto-fill,minmax(210px,1fr))}}

/* ── 响应式 ── */
@media (max-width:600px){
.ark21{padding:10px 9px;font-size:12.5px}
.tabwrap{margin:0 -9px;padding:5px 9px 0}
.tab{font-size:11.5px;min-width:46px;padding:5px 3px 8px;letter-spacing:0}
.tab .t-ico{display:none}
.minib{gap:3px}
.mb-lv{padding:2px 7px;font-size:12px}
.mb-pt,.mb-ep{padding:2px 5px;font-size:10.5px}
.ov-head{flex-wrap:wrap;padding:10px 11px}
.ptsbox{flex-direction:row;width:100%;justify-content:stretch}
.ptb{flex:1 1 50%;justify-content:center}
.dgrid{grid-template-columns:repeat(auto-fill,minmax(160px,1fr))}
.e-act{min-width:72px}
.learnbtn{min-width:70px;padding:6px 9px;font-size:12px}
.imenu{width:94%}
}
@media (max-width:380px){
.tab{min-width:42px;font-size:11px}
.mb-lv{font-size:11px;padding:1px 6px}
.mb-pt,.mb-ep{font-size:10px}
.stat-row{grid-template-columns:18px 30px 1fr 58px;gap:4px}
.stgrid{grid-template-columns:1fr 1fr}
.igrid{grid-template-columns:repeat(auto-fill,minmax(104px,1fr))}
.steps{grid-template-columns:1fr}
}
/* ── 动效降级 ── */
@media (prefers-reduced-motion:reduce){
.ark21 div,.ark21 span,.ark21 nav,.ark21 section,.ark21 button,.ark21 input,.ark21 h2,.ark21 h4,.ark21 p,.ark21 i,.ark21 em,.ark21 b,.ark21 small,.ark21 strong,.ark21 label,.ark21 ul,.ark21 li,.ark21 table,.ark21 thead,.ark21 tbody,.ark21 tr,.ark21 th,.ark21 td,.ark21 footer{animation:none!important;transition:none!important}
.ffx,.tc-ava,.egg-ava{animation:none!important}
.bar.prog .fill::after{animation:none!important}
.ink{transition:none}
}
