<body>
<div id="ark-payload" style="display:none">$1</div>
<script>window.ARK_PAYLOAD=(document.getElementById("ark-payload").textContent||"").trim();</script>

<div class="ark21 ak-root" id="arkRoot">

  <!-- 引擎缺失警示（仅降级模式显示） -->
