  <!-- 顶部身份条 -->
  <div class="toptag"><span class="tt-l"><i class="tt-dot"></i>ARK://SURVIVOR_TERMINAL</span><span class="tt-r" id="ttWho">V2.3</span></div>

  <!-- 固定标签栏（定高结构：panel 自身是滚动容器） + 迷你状态徽章 -->
