  <section class="pane" id="panel-stats" role="tabpanel" aria-labelledby="tab-stats" hidden>
    <div class="pane-scroll"><div id="stHero"></div><div id="stBands" hidden></div><div class="stgrid" id="stGrid"></div></div>
  </section>

