    <div class="pane-scroll">
    <div class="eng-head">
      <div class="ep-badge" id="epBadge"></div>
      <div class="segbtns" role="group" aria-label="印痕面板模式切换">
        <button type="button" class="seg on" id="segLearn" data-act="engmode" data-mode="learn" aria-pressed="true">学习印痕</button>
