<script>
// ═══ 方舟V2.3 五标签游戏主界面 · 主逻辑（IIFE + use strict）· 定高内滚 ═══
// 本界面是 ARK_CORE 游戏引擎（window.parent.ARK_CORE）的渲染层：
// · 加点 / 学印痕 / 制作 / 丢弃 / 驯服喂食 —— 全部调用 CORE 本地完成，0 条 AI 消息
// · 唯一允许发送消息的场景：驯服完成 → CORE.settle.send（一条结算消息）
// · 所有游戏数值均来自 CORE（引擎已实现公式），UI 绝不重复实现公式
// · 叙事数据：window.ARK_PAYLOAD（全角｜分隔的 字段名:值 列表，容错解析）
// · CORE 不可用 → 红色警示横幅 + 只读显示 ARK_PAYLOAD
// · CORE.on 订阅广播（防抖 200ms），其他 iframe 改状态时本实例自动刷新
(function () {
  'use strict';
  var doc = document;

  /* ── 多实例防重复初始化 ── */
  if (doc.body && doc.body.getAttribute('data-ark-hud-init')) return;
  if (doc.body) doc.body.setAttribute('data-ark-hud-init', '1');

  /* ═══ 0 · 运行环境探测 ═════════════════════════════════════ */
  var CORE = null, CORE_OK = false;
  try { CORE = window.ARK_CORE || null; } catch (e0a) {}
  if (!CORE) { try { if (window.parent) CORE = window.parent.ARK_CORE || null; } catch (e0b) {} }
  if (CORE) {
    try {
      CORE_OK = !!(CORE.getState && CORE.stats && CORE.eng && CORE.items && CORE.dino && CORE.settle && CORE.getState());
    } catch (e0c) { CORE_OK = false; }
  }
  /* 叙事载荷：加载器在 document.write 前设置（本窗口优先，父窗口兜底） */
  var PAYLOAD_RAW = '';
  try { if (typeof window.ARK_PAYLOAD === 'string') PAYLOAD_RAW = window.ARK_PAYLOAD; } catch (e0d) {}
  if (!PAYLOAD_RAW) { try { if (window.parent && typeof window.parent.ARK_PAYLOAD === 'string') PAYLOAD_RAW = window.parent.ARK_PAYLOAD; } catch (e0e) {} }

  /* ═══ 1 · 基础工具 ═════════════════════════════════════════ */
  var root = doc.getElementById('arkRoot');
  /* iframe 内嵌探测（神墟模式）：酒馆消息 iframe 内解除 vh 约束，改定高 700px */
  try {
    var embedded = false;
    try { embedded = (window.self !== window.top); } catch (eEm) { embedded = true; }
    if (embedded && root) root.classList.add('embed');
  } catch (eEm2) {}
  function $(id) { return doc.getElementById(id); }
  function esc(s) {
    s = (s === undefined || s === null) ? '' : String(s);
    /* 实体必须运行时动态构造：源码中出现字面量 HTML 实体会被酒馆 showdown 加解码链破坏成语法错误 */
    return s.replace(/[&<>'\x22']/g, function (c) {
      return '&' + '#' + c.charCodeAt(0) + ';';
    });
  }
  /* 乘法辅助：星号成对集中于此行（酒馆 fixMarkdown 奇偶防御），全部调用点零星号 */
  function mul(a, b) { return a * b; } // *（成对星号，勿删）
  function num(v) { var m = String(v == null ? '' : v).match(/-?\d+(?:\.\d+)?/); return m ? parseFloat(m[0]) : NaN; }
  function fmtN(x) {
    if (isNaN(x)) return '0';
    var r = Math.round(x);
    return Math.abs(r - x) < 1e-9 ? String(r) : (Math.round(mul(x, 10)) / 10).toFixed(1);
  }
  /* 重量显示：保留最多 2 位小数并去尾零（0.05 / 0.15 / 0.6 / 30） */
  function fmtW(x) {
    if (isNaN(x)) return '0';
    var s = (Math.round(mul(x, 100)) / 100).toFixed(2);
    if (s.indexOf('.') >= 0) s = s.replace(/0+$/, '').replace(/\.$/, '');
    return s || '0';
  }
  function lsGet(k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { window.localStorage.setItem(k, v); } catch (e) {} }
  /* 替换 innerHTML 时保留滚动位置（长列表广播刷新不跳动） */
  function setHTML(el, html) {
    if (!el) return;
    var top = el.scrollTop, left = el.scrollLeft;
    el.innerHTML = html;
    if (top || left) { try { el.scrollTop = top; el.scrollLeft = left; } catch (e) {} }
  }
  /* Toast 通知栈（最多同时 4 条，超出先出的先行离场） */
  function toast(msg, type) {
    var layer = $('toastLayer'); if (!layer) return;
    while (layer.children.length >= 4) layer.removeChild(layer.firstChild);
    var t = doc.createElement('div');
    t.className = 'toast' + (type ? ' ' + type : '');
    t.textContent = msg;
    layer.appendChild(t);
    setTimeout(function () {
      t.className += ' out';
      setTimeout(function () { if (t.parentNode) t.parentNode.removeChild(t); }, 360);
    }, 2800);
  }

  // ═══ 2 · ARK_PAYLOAD 解析（独立、容错） ═══
  // 格式：全角｜分隔的 字段名:值 列表
  // 例：生命值:85｜耐力:70｜饥饿:60｜口渴:55｜体温:36.8｜天气:小雨｜时间:第3天 14:20｜位置:孤岛_南部海滩｜状态效果:左臂擦伤,饥饿边缘
  // 容错：英文冒号也接受；｜ / | / ； / ; 均可作分隔；未知字段收入「其他情报」；空载荷显示占位
  var ALIAS = {
    '生命值': 'hp', '生命': 'hp', 'HP': 'hp', 'hp': 'hp',
