  function parsePayload(raw) {
    var out = { map: {}, extra: [], order: [], count: 0, has: false };
    if (typeof raw !== 'string') return out;
    raw = raw.replace(/^\s+|\s+$/g, '');
    if (!raw) return out;
    var segs = raw.split(/[｜|;；]/);
    for (var i = 0; i < segs.length; i++) {
      var seg = segs[i].replace(/^\s+|\s+$/g, '');
      if (!seg) continue;
      var ix = seg.indexOf('：'); if (ix < 0) ix = seg.indexOf(':');
      if (ix <= 0) continue;
      var k = seg.slice(0, ix).replace(/^\s+|\s+$/g, '');
      var v = seg.slice(ix + 1).replace(/^\s+|\s+$/g, '');
      if (!k || !v) continue;
      out.count++;
      out.has = true;
      var a = ALIAS[k] || ALIAS[String(k).toLowerCase()] || null;
      out.order.push({ k: k, a: a, v: v });
