  /* 加点成功后的数字滚动动画：旧值→新值 420ms 缓动滚入（reduced-motion 直接落位） */
  function rollStat(k, from, to, unit) {
    try {
      var c = root.querySelector('.stcard[data-st="' + k + '"] .sc-val');
      if (!c) return;
      var paint = function (v) { c.innerHTML = esc(fmtN(v)) + '<small>' + esc(unit || '') + '</small>'; };
      var reduce = false;
      try { reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}
      if (reduce || from === to) { paint(to); return; }
      var t0 = Date.now(), dur = 420;
      c.className = 'sc-val bump';
      setTimeout(function () { c.className = 'sc-val'; }, 560);
      (function step() {
        var p = Math.min(1, (Date.now() - t0) / dur);
        var eased = 1 - Math.pow(1 - p, 3);
        paint(from + mul(to - from, eased));
        if (p < 1) requestAnimationFrame(step); else paint(to);
      })();
    } catch (e) {}
  }
