    var c = null;
    try { c = CORE.eng.canLearn(e.id, ST); } catch (er) { c = null; }
    if (c && c.ok) return { st: 'can' };
    var why = (c && c.why) ? c.why : '无法学习';
    if (why.indexOf('需要等级') === 0) return { st: 'lv' };
    if (why.indexOf('印痕点不足') === 0) return { st: 'ep' };
    if (why.indexOf('前置') === 0) return { st: 'req', miss: missingReq(e, lrnd) };
