  /* ═══ 12-2 · 区2 已驯服生物管理（V3.0-D1）：卡片流 + 繁殖配对 ═══ */
  function fmtMS(sec) {
    sec = Math.max(0, Math.ceil(sec));
    var m = Math.floor(sec / 60), s = sec % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }
  function fmtCd(ms) {
    if (ms <= 0) return '就绪';
    if (ms > 3600000) return (Math.round(mul(ms, 10) / 360000) / 10) + '小时';
    return fmtMS(ms / 1000);
  }
  function gSym(g) { return g === '雄' ? '♂' : (g === '雌' ? '♀' : '?'); }
  function gCls(g) { return g === '雄' ? 'm' : (g === '雌' ? 'f' : 'u'); }
  function stCls(s) { return s === '跟随' ? 'st-f' : (s === '驻守' ? 'st-s' : 'st-w'); }
  function temperCls(tp) {
