    var needMs = mul(num(br['孵化需求秒']) || 180, 1000);
    var remain = (num(br['开始']) || 0) + needMs - Date.now();
    if (remain <= 0) { stopEggTimer(); renderTame(); return; }
    var cdEl = $('eggCd');
    if (cdEl) cdEl.textContent = fmtMS(remain / 1000);
    var eb = $('eggBar');
    if (eb) eb.style.width = Math.max(0, Math.min(100, needMs > 0 ? (100 - mul(remain, 100) / needMs) : 100)) + '%';
  }
  function ensureEggTimer() {
    stopEggTimer();
    var br = eggActive();
    if (!br) return;
    var needMs = mul(num(br['孵化需求秒']) || 180, 1000);
    if ((num(br['开始']) || 0) + needMs - Date.now() <= 0) return;
    eggTimer = setInterval(eggTick, 1000);
  }
