  function doRenameConfirm() {
    if (!dinoModal || dinoModal.mode !== 'rename') return;
    var old = dinoModal.name;
    var inp = $('dnameInp');
    var nn = inp ? String(inp.value || '') : '';
    /* 白名单过滤（中文/字母/数字/间隔号/空格），防御引号尖括号等注入源 */
    nn = nn.replace(/[^0-9A-Za-z\u4e00-\u9fa5· ]/g, '').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
    if (nn.length > 12) nn = nn.slice(0, 12);
    if (!nn) { toast('名字不能为空（仅限中文 / 字母 / 数字）', 'err'); return; }
    if (nn === old) { closeDinoMenu(); return; }
    var r = null;
    try { r = CORE.dino.rename(old, nn); } catch (eRn) { r = null; }
    if (r && r.ok) {
      for (var i = 0; i < breedSel.length; i++) if (breedSel[i] === old) breedSel[i] = r.name;
      toast('✏ 已改名：' + old + ' → ' + r.name, 'ok');
      closeDinoMenu();
      renderActive();
    } else {
      toast((r && r.why) || '改名失败', 'err');
    }
  }

