  function doChatCfgSave() {
    if (!CORE_OK || !CORE.npc || !CORE.npc.setCfg || !chatNPC) { toast('引擎未提供配置接口', 'err'); return; }
    cfgSyncInputs();
    var c = chatCfgRead(); /* V3.4.8 草稿已合并，直接取合并结果 */
    var patch = {
      len: c.len,
      spoiler: c.spoiler,
      honor: String(c.honor || '').trim(),
      style: String(c.style || '').trim(),
      persona: String(c.persona || '').trim(),
      knowledge: c.knowledge,
      initiative: c.initiative
    };
    try {
      CORE.npc.setCfg(chatNPC.name, patch);
      toast('⚙ 已保存「' + chatNPC.name + '」的对话设置', 'ok');
      chatCfgOpen = false;
      chatCfgDraftLen = ''; chatCfgDraftSpoil = ''; chatCfgDraftKnow = ''; chatCfgDraftInit = ''; /* V3.4.8 保存后清草稿 */
      chatCfgDraftHonor = null; chatCfgDraftStyle = null; chatCfgDraftPersona = null; chatCfgLenEdit = false;
      renderChat();
    } catch (eS) { toast('保存失败：' + (eS && eS.message ? eS.message : eS), 'err'); }
  }
  function openNpcChat(name) {
    if (!name) return;
    if (!CORE_OK || !CORE.ai || typeof CORE.ai.history !== 'function' || typeof CORE.ai.chat !== 'function') {
      toast('当前游戏核心未提供NPC独立对话能力', 'err');
      return;
    }
    chatNPC = { name: name, profile: npcProfileOf(name) };
    chatGuide = false; chatGuideWhy = ''; chatClearArm = false; chatBusy = false;
    chatRegenIdx = -1; chatRegenBusy = false; // V3.4.6 单句重生成状态复位
    chatCfgOpen = false; chatCfgDraftLen = ''; chatCfgDraftSpoil = ''; chatCfgDraftKnow = ''; chatCfgDraftInit = '';
    chatCfgDraftHonor = null; chatCfgDraftStyle = null; chatCfgDraftPersona = null; chatCfgLenEdit = false; /* V3.4.8 */
    renderChat();
    var v = $('chatVeil'), b = $('chatBox');
    if (v) v.removeAttribute('hidden');
    if (b) b.removeAttribute('hidden');
    var inp = $('chatInp');
    if (inp) { try { inp.focus(); } catch (eF) {} }
  }
  function closeChat() {
    chatNPC = null; chatBusy = false; chatGuide = false; chatGuideWhy = ''; chatClearArm = false;
    chatRegenIdx = -1; chatRegenBusy = false;
    var v = $('chatVeil'), b = $('chatBox');
    if (v) v.setAttribute('hidden', '');
    if (b) b.setAttribute('hidden', '');
  }
  function appendBub(side, text) {
    var el = $('cbMsgs'); if (!el) return null;
    var d = doc.createElement('div');
    d.className = 'bub ' + side;
    var s = doc.createElement('span');
    s.textContent = String(text == null ? '' : text);
    d.appendChild(s);
    el.appendChild(d);
    try { el.scrollTop = el.scrollHeight; } catch (eSc) {}
    return d;
  }
  function showThinking() {
    var el = $('cbMsgs'); if (!el || !chatNPC) return;
    var d = doc.createElement('div');
    d.className = 'bub npc think';
    d.id = 'chatThink';
    var dots = doc.createElement('span');
    dots.className = 'dots';
    dots.innerHTML = '<i></i><i></i><i></i>';
    d.appendChild(dots);
    d.appendChild(doc.createTextNode(chatNPC.name + ' 正在思考…'));
    el.appendChild(d);
    try { el.scrollTop = el.scrollHeight; } catch (eSc) {}
  }
  function killThinking() {
    var t = $('chatThink');
    if (t && t.parentNode) t.parentNode.removeChild(t);
  }
  function removeGuideNode() {
    var g = root.querySelector('#cbMsgs .cb-guide');
    if (g && g.parentNode) g.parentNode.removeChild(g);
  }
  function sendChatMsg() {
    if (!chatNPC || chatBusy) return;
    if (!CORE_OK || !CORE.ai || typeof CORE.ai.chat !== 'function') {
      toast('引擎未提供NPC对话能力（请更新游戏核心脚本）', 'err');
      return;
    }
    var inp = $('chatInp');
    var txt = inp ? String(inp.value || '').replace(/^\s+|\s+$/g, '') : '';
    if (!txt) return;
    var emptyEl = root.querySelector('#cbMsgs .cb-empty');
    if (emptyEl && emptyEl.parentNode) emptyEl.parentNode.removeChild(emptyEl);
    chatBusy = true;
    appendBub('me', txt);
    if (inp) inp.value = '';
    var btn = root.querySelector('.cb-send');
    if (btn) { btn.disabled = true; btn.textContent = '发送中'; }
    showThinking();
    var name = chatNPC.name, prof = chatNPC.profile || {};
    var finish = function (r) {
      chatBusy = false;
      killThinking();
      var b2 = root.querySelector('.cb-send');
      if (b2) { b2.disabled = false; b2.textContent = '发送'; }
      if (r && r.ok) {
        chatGuide = false; chatGuideWhy = '';
        removeGuideNode();
        renderChatMsgs(); /* V3.4.6：整层重渲染——新回复（及本轮玩家发言）自带 ↻/🗑 单句操作按钮 */
      } else {
        var why = (r && r.why) || '发送失败';
        chatGuide = true; chatGuideWhy = why;
        appendBub('err', '发送失败：' + why);
        var msgs = $('cbMsgs');
        if (msgs) {
          var g = doc.createElement('div');
          g.className = 'cb-guide';
          g.innerHTML = chatGuideHTML(why);
          msgs.appendChild(g);
          try { msgs.scrollTop = msgs.scrollHeight; } catch (eSc2) {}
        }
        toast(why, 'err');
      }
      var ci = $('chatInp');
      if (ci) { try { ci.focus(); } catch (eF2) {} }
    };
    try {
      CORE.ai.chat(name, prof, txt).then(finish, function (err) {
        finish({ ok: false, why: '对话请求异常' + (err && err.message ? '：' + err.message : '') });
      });
    } catch (eC) {
      finish({ ok: false, why: '对话调用异常：' + (eC && eC.message ? eC.message : String(eC)) });
    }
  }
  function archiveChat() {
    if (!chatNPC) return;
    if (chatArchBusy) return;
    if (!CORE_OK || !CORE.ai || typeof CORE.ai.summarize !== 'function') { toast('引擎未提供对话归档能力', 'err'); return; }
    var nm = chatNPC.name;
    chatArchBusy = true;
    renderChatFoot();
    var btn = root.querySelector('[data-act="chatsubmit"]');
    if (btn) { btn.disabled = true; btn.textContent = '⟳ 归档中…'; }
    CORE.ai.summarize(nm).then(function (r) {
      chatArchBusy = false;
      if (r && r.ok) {
        closeChat();
        toast('📮 已归档与' + nm + '的第' + (r.archived || 1) + '次对话：摘要存入TA的记忆，并随你下次发言送达主AI', 'ok');
        renderActive();
      } else {
        renderChatFoot();
        toast((r && r.why) || '没有可归档的对话', 'warn');
      }
    }, function () {
      chatArchBusy = false;
      renderChatFoot();
      toast('归档请求异常', 'err');
    });
  }
  function clearChatHistory() {
    if (!chatNPC) return;
    try { CORE.ai.clearHistory(chatNPC.name); } catch (eCl) {}
    chatClearArm = false;
    chatGuide = false; chatGuideWhy = '';
