  }
  /* ═══ V3.4.6 酒馆式单句操作：重新生成并替换 / 删除单句 ═══ */
  function doChatRegen(i) {
    if (!chatNPC || chatRegenBusy || chatBusy) return;
    if (!CORE_OK || !CORE.ai || typeof CORE.ai.regenerate !== 'function') { toast('引擎未提供单句重新生成能力（需更新游戏核心脚本）', 'err'); return; }
    chatRegenBusy = true;
    chatRegenIdx = i;
    renderChatMsgs();
    CORE.ai.regenerate(chatNPC.name, i).then(function (r) {
      chatRegenBusy = false;
      chatRegenIdx = -1;
      renderChatMsgs();
      if (r && r.ok) toast('↻ 已重新生成这句回复（原句被替换）', 'ok');
      else toast((r && r.why) || '重新生成失败', 'err');
    }, function (err) {
      chatRegenBusy = false;
      chatRegenIdx = -1;
      renderChatMsgs();
      toast('重新生成请求异常' + (err && err.message ? '：' + err.message : ''), 'err');
    });
  }
  function doChatDel(i) {
    if (!chatNPC || chatRegenBusy) return;
