/* ═══ 羊皮纸卡片（紧凑版） ═══ */
.dcard{position:relative;z-index:0;border-radius:11px 14px 9px 12px/12px 9px 14px 11px;padding:15px 17px 11px;color:#3a2c16;
 background:
  radial-gradient(48% 38% at 100% 100%,rgba(64,36,10,.27),rgba(64,36,10,0) 72%),
