.dfbnm{margin:8px 0 0;font-family:Georgia,'Kaiti SC','STKaiti','KaiTi',serif;font-size:15px;letter-spacing:2.5px;color:#5a4326}
.dfbcp{margin:3px 0 0;font-size:9.5px;letter-spacing:1.5px;color:#94774e}

/* 右栏 */
.dbody{min-width:0}
.dtr{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;margin:1px 0 0}
.dname{font-family:Georgia,'Times New Roman','Songti SC','SimSun','STSong',serif;font-size:21px;line-height:1.22;font-weight:700;letter-spacing:.5px;color:#33240f;text-decoration:underline wavy rgba(96,66,26,.5);text-decoration-thickness:2px;text-underline-offset:6px;overflow-wrap:anywhere}
.dbadge{display:inline-block;padding:2px 9px;font-size:10px;font-weight:700;letter-spacing:1.5px;color:#f6eed8;border:1px solid transparent;border-radius:3px;text-shadow:0 1px 1px rgba(0,0,0,.25)}
.dbadge.r0{background:linear-gradient(180deg,#93744e,#6d5233);border-color:#b39267}
.dbadge.r1{background:linear-gradient(180deg,#3a79c4,#245091);border-color:#7fb0e0}
.dbadge.r2{background:linear-gradient(180deg,#8748c8,#5b2d8a);border-color:#b087e2}
