.drow{display:flex;align-items:baseline;gap:6px;padding:5px 2px 4px;border-bottom:1px dashed rgba(110,78,40,.38)}
.dico{flex:none;font-size:12.5px;line-height:1.4;filter:sepia(.28) saturate(.9)}
.dlab{flex:none;font-size:9.5px;letter-spacing:2px;color:#8a6a44;font-weight:600}
.dval{flex:1;min-width:0;margin:0;font-size:12.5px;font-weight:600;color:#3a2c16;overflow-wrap:anywhere}
.dval.vempty{color:#9a7c54;font-weight:400}
.dthreat{margin:0 0 3px;padding:7px 10px 8px;border:1px solid rgba(128,46,32,.3);border-radius:3px;background:linear-gradient(180deg,rgba(128,46,32,.05),rgba(128,46,32,.02))}
.dtlab{display:flex;align-items:center;gap:7px;margin:0 0 6px;font-size:9.5px;font-weight:700;letter-spacing:2.5px;color:#8a4030}
.dtlab::after{content:"";flex:1;border-top:1px solid rgba(128,46,32,.22)}
.dtr2{display:flex;flex-wrap:wrap;align-items:center;gap:3px 6px}
.dclaws{display:inline-flex;flex:none;gap:5px;align-items:center}
.dcl{display:inline-flex;width:13px;height:19px}
.dcl svg{display:block;width:100%;height:100%}
.dcl path{fill:none;stroke:rgba(96,66,26,.2);stroke-width:2.3;stroke-linecap:round}
.dcl.on path{stroke:#8a2a1e;filter:drop-shadow(0 1px 0 rgba(255,246,224,.4))}
.dthtx{margin-left:auto;min-width:0;font-size:10.5px;font-style:italic;color:#7a4a30;overflow-wrap:anywhere;text-align:right}

/* 手记与驯服建议 */
.dnotes{position:relative;z-index:1;margin:11px 0 0;padding-top:8px;border-top:1px solid rgba(110,78,40,.3)}
.dseclab{display:flex;align-items:center;gap:8px;margin:0 0 6px;font-size:9px;font-weight:700;letter-spacing:3px;color:#8a6a44}
.dseclab::after{content:"";flex:1;border-top:1px solid rgba(110,78,40,.24)}
