}

/* 动画（reduced-motion 全关） */
@media(prefers-reduced-motion:no-preference){
@keyframes dclaw{from{opacity:0;transform:scale(.6) rotate(-8deg)}to{opacity:1;transform:none}}
@keyframes ddraw{to{stroke-dashoffset:-100}}
