.dcl:nth-child(2){animation-delay:.05s}
.dcl:nth-child(3){animation-delay:.1s}
.dcl:nth-child(4){animation-delay:.15s}
.dcl:nth-child(5){animation-delay:.2s}
.dsil path{animation:ddraw 9s linear infinite}
}
