/* 多源镜像链：wsrv.nl（国内可达镜像，webp 压缩）→ images.weserv.nl（备用镜像）→ wiki 直链缩略（国际线路）→ 剪影占位 */
function chainLoad(im,f,w,finalFn){
 var u=[
  'https://wsrv.nl/?url=ark.wiki.gg/images/'+f+'&w='+w+'&output=webp&q=58',
  'https://images.weserv.nl/?url=ark.wiki.gg/images/'+f+'&w='+w+'&output=webp&q=58',
  'https://ark.wiki.gg/images/thumb/'+f+'/'+(w+40)+'px-'+f
 ];
 var i=-1;
 function nxt(){
  i++;
  if(i<u.length){im.src=u[i];}
  else if(finalFn){finalFn();}
 }
 im.addEventListener('error',nxt);
 nxt();
}
function hashStr(s){var h=7;s=String(s||'ARK');var i;for(i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))>>>0;}return h;}
function clampT(n){n=Math.round(Number(n)||0);return n<0?0:(n>5?5:n);}
function parseThreat(s){
var m;
if(!s){return 0;}
if((m=s.match(/([0-9])\s*[\/／]\s*[0-9]/))){return clampT(m[1]);}
if((m=s.match(/([0-9])\s*(?:星|级|档|阶)/))){return clampT(m[1]);}
if((m=s.match(/等级\s*[:：]?\s*([0-9])/))){return clampT(m[1]);}
if((m=s.match(/([一二两三四五])\s*(?:星|级|档|阶)/))){
if(m[1]==='两'){return 2;}
var ci='一二三四五'.indexOf(m[1]);
return clampT(ci<0?0:(ci+1));
}
if((m=s.match(/(?:^|[^\d])([1-5])(?!\d)/))){return clampT(m[1]);}
if(/致命|极高|顶点|顶级|噩梦|毁灭|灭绝/.test(s)){return 5;}
if(/很高|高度危险|极其危险|凶残|残暴|强大|较高|危险|强悍|凶猛/.test(s)){return 4;}
if(/中等|一般|普通|均衡/.test(s)){return 3;}
if(/较低|温和|胆小|谨慎|畏缩/.test(s)){return 2;}
if(/极低|无害|安全|温顺|和平|低|弱/.test(s)){return 1;}
if(/高/.test(s)){return 4;}
return 0;
}
function lookup(nm){
var cn=String(nm||'').replace(/[（(][^（()）]*[）)]/g,'').replace(/[\s·、，。.\-—]+$/,'').trim();
var k;
if(!cn){return '';}
if(IMG[cn]){return cn;}
var best='';
for(k in IMG){if(IMG.hasOwnProperty(k)&&cn.indexOf(k)>-1&&k.length>best.length){best=k;}}
if(best){return best;}
if(cn.length>1){for(k in IMG){if(IMG.hasOwnProperty(k)&&k.indexOf(cn)===0){return k;}}}
return '';
}
function ping(){try{document.body.setAttribute('data-ark-img',String((Date.now()/97|0)%89));}catch(e){}}
function init(root){
function fa(k){return root.querySelector('[data-f='+k+']');}
var tpl=root.querySelector('template.ark-data');
var raw={};
if(tpl){
var ns=tpl.content.querySelectorAll('[data-k]'),i;
for(i=0;i<ns.length;i++){raw[ns[i].getAttribute('data-k')]=(ns[i].textContent||'').trim();}
}
function val(k){
var s=(raw[k]||'').trim();
if(!s||s==='-'||s==='—'||s.charCodeAt(0)===36){return '';}
return s;
}
var name=val('name')||'未知生物';
var noe=fa('no');
if(noe){noe.textContent='No.'+(1000+(hashStr(raw.name||'ARK')%9000));}
var bno=fa('bno');
if(bno){bno.textContent='No.'+(1000+(hashStr(raw.name||'ARK')%9000));}
var ne=fa('name');
if(ne){ne.textContent=name;}
var rar=val('rarity')||'未定级';
var rc=0;
if(rar.indexOf('传说')>-1||rar.indexOf('神话')>-1){rc=3;}
else if(rar.indexOf('史诗')>-1||rar.indexOf('精英')>-1){rc=2;}
else if(rar.indexOf('稀有')>-1){rc=1;}
var re=fa('rarity');
if(re){re.textContent=rar;re.className='dbadge r'+rc;}
var bre=fa('brarity');
if(bre){bre.textContent=rar;bre.className='dbar-badge r'+rc;}
var key=lookup(name);
var ens=key?(EN[key].toUpperCase()+' · WILD'):'UNCATALOGUED SPECIMEN · 未收录';
var ee=fa('ensub');
if(ee){ee.textContent=ens;}
var ben=fa('ben');
if(ben){ben.textContent=ens;}
var F=['diet','temper','size','loc'],j;
for(j=0;j<F.length;j++){
var el=fa(F[j]);
if(el){
var tv=val(F[j]);
el.textContent=tv||'—';
if(!tv&&el.classList){el.classList.add('vempty');}
}
}
var nt=val('notes');
var np=fa('notes');
if(np){
np.textContent=nt||'（纸页空白，尚无观察记录。）';
if(nt){
if(/^[A-Za-z0-9\u4e00-\u9fff]/.test(nt)){np.className='dnote dcap';}
}else if(np.classList){np.classList.add('dempty');}
}
var tm=val('tame');
var tp=fa('tame');
if(tp){
tp.textContent=tm||'（尚无驯服相关记录。）';
if(!tm&&tp.classList){tp.classList.add('dempty');}
}
var th=val('threat');
var lv=clampT(parseThreat(th));
function clawsInto(el,cls){
if(!el){return;}
var htm='',c;
for(c=0;c<5;c++){htm+='<span class="dcl'+(c<lv?' on':'')+'">'+CLAW+'</span>';}
el.innerHTML=htm;
el.setAttribute('aria-label','威胁评级 '+(lv>0?(lv+'/5'):'未知'));
}
clawsInto(fa('claws'));
clawsInto(fa('bclaws'));
var tte=fa('thtx');
if(tte){tte.textContent=th||'—';}
var bnm=fa('bname');
if(bnm){bnm.textContent=name;}
/* 展开区缩略图（折叠头）：38px，静默失败保留🦖 */
var bt=fa('bthumb');
if(bt&&key){
var bi=document.createElement('img');
bi.alt='';
bi.decoding='async';
chainLoad(bi,IMG[key],96,function(){bi.remove();});
bt.appendChild(bi);
}
/* 主图鉴影像：三源镜像链 → 剪影 */
var box=fa('imgbox');
if(box){
function fb(cap){
if(box.querySelector('.dfb')){return;}
var d=document.createElement('div');
d.className='dfb';
d.innerHTML='<svg class="dsil" viewBox="0 0 120 72" aria-hidden="true">'+SIL+'</svg>';
var nm=document.createElement('p');
nm.className='dfbnm';
nm.textContent=name;
var cp=document.createElement('p');
cp.className='dfbcp';
cp.textContent=cap;
d.appendChild(nm);
d.appendChild(cp);
box.appendChild(d);
}
if(key){
var im=document.createElement('img');
im.className='dimg';
im.alt=name+' 野生图鉴影像';
im.decoding='async';
im.addEventListener('error',function(){
if(im.parentNode){im.parentNode.removeChild(im);}
fb('图鉴影像离线');
ping();
});
im.addEventListener('load',ping);
box.appendChild(im);
chainLoad(im,IMG[key],300,function(){
if(im.parentNode){im.parentNode.removeChild(im);}
fb('档案库未收录该物种影像');
ping();
});
}else{
fb('档案库未收录该物种影像');
}
}
/* 折叠/展开切换 */
var bar=fa('bar');
if(bar){
bar.addEventListener('click',function(){
var open=root.getAttribute('data-open')==='1';
root.setAttribute('data-open',open?'0':'1');
bar.setAttribute('aria-expanded',open?'false':'true');
try{if(window.__dosFit){requestAnimationFrame(window.__dosFit);requestAnimationFrame(window.__dosFit);}else{ping();}}catch(e){ping();}
});
}
}
var roots=document.querySelectorAll('.dwrap'),r;
for(r=0;r<roots.length;r++){
var el=roots[r];
if(el.getAttribute('data-dos-init')){continue;}
el.setAttribute('data-dos-init','1');
try{init(el);}catch(err){}
}
