<title>下一步行动 · 行动选项</title>
<style>
*{box-sizing:border-box}
body{margin:0;padding:3px;background:transparent}
.ark-opt{--amb:#e8a33d;--hi:#f6c96b;--tea:#3ec6c8;--ink:#d5e4e7;--dim:#5f7a80;position:relative;max-width:640px;margin:5px auto;padding:11px 12px 10px;font:14px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;color:var(--ink);background:repeating-linear-gradient(0deg,rgba(255,255,255,.014) 0 1px,transparent 1px 3px),linear-gradient(180deg,#0a161a,#060d10);border:1px solid rgba(232,163,61,.26);box-shadow:0 4px 16px rgba(0,0,0,.45)}
.ark-opt::before,.ark-opt::after{content:"";position:absolute;width:11px;height:11px;pointer-events:none;border:0 solid rgba(232,163,61,.7)}
.ark-opt::before{top:3px;left:3px;border-top-width:2px;border-left-width:2px}
.ark-opt::after{bottom:3px;right:3px;border-bottom-width:2px;border-right-width:2px}
.ao-head{display:flex;align-items:baseline;gap:7px;padding-bottom:6px;border-bottom:1px solid rgba(232,163,61,.18)}
.ao-title{font-size:11px;font-weight:700;letter-spacing:2.5px;color:var(--amb)}
.ao-en{font-size:10px;letter-spacing:1.5px;color:var(--dim)}
.ao-count{margin-left:auto;font-size:10px;letter-spacing:1px;color:var(--dim)}
.ao-list{margin-top:2px}
.ao-card{display:flex;align-items:center;gap:11px;width:100%;min-height:54px;margin-top:8px;padding:8px 11px;font-family:inherit;font-size:14px;text-align:left;color:#cfe3e6;background:rgba(13,30,36,.72);border:1px solid rgba(62,198,200,.18);cursor:pointer;position:relative;overflow:hidden;transition:border-color .16s,box-shadow .16s,background .16s,transform .16s}
.ao-card::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:transparent;transition:background .16s}
.ao-card:hover,.ao-card:focus-visible{border-color:rgba(232,163,61,.75);background:rgba(20,40,47,.86);box-shadow:0 0 14px rgba(232,163,61,.22),inset 0 0 20px rgba(232,163,61,.05);outline:0;transform:translateY(-1px)}
