</style>
</head>
<body>
<div id="ark-payload" style="display:none">$1</div>
<script>window.ARK_PAYLOAD=(document.getElementById("ark-payload").textContent||"").trim();</script>

<div class="ark-opt" aria-label="下一步行动选项">
<div class="ao-head"><span class="ao-title">下一步行动</span><span class="ao-en">// NEXT MOVE</span><span class="ao-count" id="aoCount"></span></div>
<div class="ao-list" id="aoList"></div>
<p class="ao-empty" id="aoEmpty" hidden>（本回合无选项，请自由输入行动）</p>
<p class="ao-status" id="aoStatus" aria-live="polite"><span class="dot" aria-hidden="true"></span><span id="aoStatusTxt">等待你的选择。</span></p>
<p class="ao-tip">点击仅填入输入框，可直接修改或自行输入其他行动</p>
</div>
<script>
(function(){
'use strict';
/* V3.0 通用选项解析器：接受 稳妥行动：/进取行动：/探索行动：/选项一：/任意xx： 乃至无前缀行 */
function init(root){
var listEl=root.querySelector('.ao-list');
var emptyEl=root.querySelector('.ao-empty');
var cntEl=root.querySelector('#aoCount')||root.querySelector('.ao-count');
function setStatus(msg){var st=root.querySelector('#aoStatusTxt');if(st)st.textContent=msg||'等待你的选择。';}
function writeInput(text){
var helper=(window.TavernHelper||window.parent&&window.parent.TavernHelper)||{};
var run=typeof triggerSlash==='function'?triggerSlash:(typeof helper.triggerSlash==='function'?helper.triggerSlash:null);
if(!run){setStatus('无法自动写入，请手动输入');return;}
run('/setinput '+JSON.stringify(text)).then(function(){setStatus('已写入输入框，请确认后手动发送');},function(){
try{return run('/setinput '+String(text).replace(/\|/g,'｜')).then(function(){setStatus('已写入输入框，请确认后手动发送');});}catch(e){}
setStatus('无法自动写入，请手动输入');
}).catch(function(){setStatus('无法自动写入，请手动输入');});
}
var payload='';
try{payload=String(window.ARK_PAYLOAD||'');}catch(e){}
payload=payload.replace(/^\s+|\s+$/g,'');
/* 行解析：tag：text 或 纯text */
var KINDS=[
{re:/(稳妥|安全|保守|防御)/,kind:'safe',label:'稳妥',ico:'🛡'},
{re:/(进取|冒险|大胆|激进|高风险|强攻)/,kind:'bold',label:'进取',ico:'⚔'},
{re:/(探索|侦察|侦查|搜索|冒险探)/,kind:'explore',label:'探索',ico:'🧭'}
];
var NUMS=['Ⅰ','Ⅱ','Ⅲ','Ⅳ','Ⅴ','Ⅵ'];
var opts=[];
payload.split(/\r?\n/).forEach(function(line){
line=line.replace(/^\s*[-·•*]\s*/,'').replace(/\s+$/,'');
if(!line)return;
var m=line.match(/^(?:【|〖)?([^：:]{1,12})(?:】|〗)?[：:]\s*(.+)$/);
if(m){opts.push({tag:m[1].replace(/\s+/g,''),txt:m[2]});}
else if(line.length>=2){opts.push({tag:'',txt:line});}
});
if(opts.length>6)opts=opts.slice(0,6);
if(!opts.length){
if(listEl)listEl.hidden=true;
if(emptyEl)emptyEl.hidden=false;
if(cntEl)cntEl.textContent='';
setStatus('');
return;
}
if(cntEl)cntEl.textContent=opts.length+' 个可选';
var html='';
opts.forEach(function(o,i){
var kind='plain',label=o.tag,ico='▸';
for(var k=0;k<KINDS.length;k++){if(KINDS[k].re.test(o.tag)){kind=KINDS[k].kind;label=KINDS[k].label;ico=KINDS[k].ico;break;}}
if(!label){kind=['safe','bold','explore'][i%3];label=['稳妥','进取','探索'][i%3];ico=['🛡','⚔','🧭'][i%3];}
html+='<button type="button" class="ao-card" data-i="'+i+'">'
+'<span class="ao-num" aria-hidden="true"><i>'+NUMS[i]+'</i></span>'
+'<span class="ao-body"><span class="ao-tag '+kind+'">'+ico+' '+escT(label)+'</span><span class="ao-txt">'+escT(o.txt)+'</span></span>'
+'<span class="ao-arrow" aria-hidden="true">➔</span></button>';
});
if(listEl){listEl.innerHTML=html;listEl.hidden=false;}
var cards=listEl?listEl.querySelectorAll('.ao-card'):[];
for(var c=0;c<cards.length;c++){
(function(card,idx){
card.addEventListener('click',function(){
var prev=listEl.querySelector('.ao-card.chosen');
if(prev)prev.classList.remove('chosen');
card.classList.add('chosen');
writeInput(opts[idx].txt);
});
})(cards[c],c);
}
}
function escT(s){return String(s==null?'':s).replace(/[&<>'\x22]/g,function(c){return '&'+'#'+c.charCodeAt(0)+';';});}
var roots=document.querySelectorAll('.ark-opt');
for(var r=0;r<roots.length;r++){
var el=roots[r];
if(el.getAttribute('data-ark-init'))continue;
el.setAttribute('data-ark-init','1');
try{init(el);}catch(err){}
}
})();
</script>
</body>
</html>
